const e=[{id:1,code:"RED-01",icon:"Flame",accent:"#dc2626",category:"الطوارئ",title:"Code Red — الاستجابة لحالات الحريق",subtitle:"حماية أرواح المرضى والعاملين في أثناء الحريق في المستشفى",summary:"Code Red هو الرمز الذي يستخدمه المستشفى للإعلان عن نشوب حريق. فالاستجابة السريعة والمنظّمة تحمي أرواح المرضى، لأنّ كثيرًا منهم لا يستطيعون الخروج بأنفسهم. ويعمل الكوادر وفق إجراء RACE: الإنقاذ (Rescue)، والإنذار (Alarm)، والاحتواء (Contain)، والإطفاء أو الإخلاء (Extinguish / Evacuate). وتُستخدم مطفأة الحريق وفق تقنية PASS. ويوضّح هذا الدرس كيف يُكتشف الحريق، وكيف يُطلق الإنذار، وكيف يُحتوى الحريق ويُطفأ بأمان.",facts:[{label:"أرقام الطوارئ",value:"رقم الطوارئ الداخلي للمستشفى + 115"},{label:"المعيار",value:"NFPA 101 + NFPA 99"},{label:"إجراء الاستجابة",value:"RACE + PASS"},{label:"مطفأة الأجهزة الكهربائية",value:"CO₂ أو Clean Agent"}],steps:[{title:"R — Rescue (الإنقاذ)",detail:"أبعِد فورًا المرضى القريبين من النار والدخان عن مصدر الخطر. انقل المريض الراقد على سريره بالسرير نفسه بعد فكّ مكابح العجلات. وانقل المرضى الموصولين بالأكسجين أو بجهاز التنفس الاصطناعي باستخدام أسطوانة أكسجين محمولة أو كيس التنفس اليدوي (bag-mask).",critical:!0},{title:"A — Alarm (الإنذار)",detail:"اسحب أو اضغط جهاز إنذار الحريق اليدوي (Pull Station)، واتصل برقم الطوارئ الداخلي للمستشفى. قل بصوت هادئ «Code Red» وحدّد موقع الحريق (الطابق والغرفة). ويُبلَّغ الدفاع المدني (115) وفق خطة الحريق المعتمدة في المستشفى.",critical:!0},{title:"C — Contain (الاحتواء)",detail:"أغلق أبواب غرفة الحريق والممر لمنع انتشار الدخان والنار، ولكن لا تقفلها بالمفتاح. لا تغلق صمام الأكسجين الخاص بالمنطقة (zone valve) فورًا: فهو لا يُغلق إلا بعد تحويل المرضى الموصولين بالأكسجين والمرضى على أجهزة التنفس الاصطناعي إلى أسطوانة محمولة أو كيس التنفس اليدوي (bag-mask)، وبأمر من الطبيب أو الممرض المسؤول أو وفق خطة الحريق.",critical:!0},{title:"E — Extinguish (الإطفاء)",detail:"لا تُطفئ إلا إذا تحقّق كل ما يلي: الحريق صغير وفي بدايته (لا يتجاوز حجم سلة المهملات)، والمطفأة مناسبة، وطريق الخروج خلفك مفتوح، وتمّ إطلاق الإنذار، وقد تلقّيت التدريب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب خلفك. اختر المطفأة المناسبة: CO₂ للأجهزة الكهربائية، وWet Chemical (الفئة K) لزيوت المطبخ، وفي غرفة MRI المطفأة غير المغناطيسية فقط."},{title:"E — Evacuate (الإخلاء)",detail:`إذا كان الحريق كبيرًا أو لم تتمكن من السيطرة عليه، فانقل المرضى أفقيًا (Horizontal) إلى قسم آمن خلف الأبواب المانعة للدخان في الطابق نفسه. وعند الضرورة، انقلهم بعد ذلك عموديًا (Vertical) إلى طابق أدنى.
• لا تستخدم المصعد.`,critical:!0}],reference:[{heading:"المطفأة المناسبة بحسب المكان",points:["غرفة العمليات (OR): المحلول الملحي (saline) للحريق على جسم المريض، ومطفأة CO₂ (توصية ASA).","MRI: المطفأة غير المغناطيسية المعلَّمة للاستخدام في MRI فقط؛ فالمطفأة الحديدية تتحوّل إلى قذيفة.","المختبر: CO₂ أو ABC بحسب المواد الموجودة فيه؛ وClass D يذكر ملصقها المعدن، حيث توجد معادن قابلة للاشتعال.","ICU: CO₂ أو Clean Agent للأجهزة الكهربائية.","المطبخ والكافتيريا: Wet Chemical (الفئة K).","الممرات والأماكن العامة: مسحوق ABC."]},{heading:"PASS — تقنية استخدام المطفأة",points:["قبل PASS، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك.","P = Pull: اسحب مسمار الأمان.","A = Aim: وجّه فوهة الخرطوم نحو قاعدة النار، لا نحو أعلى اللهب.","S = Squeeze: اضغط مقبض المطفأة بقوة.","S = Sweep: حرّك الخرطوم من جانب إلى آخر؛ وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب.","تفرغ المطافئ الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة (والمدة الدقيقة مكتوبة على الملصق). ابدأ من المسافة المحددة على الملصق، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار."]},{heading:"ما لا يجوز فعله",points:["لا تستخدم المصعد: فقد يتوقف في طابق الحريق.","لا تفتح النوافذ: فالهواء الإضافي يزيد اشتعال النار.","لا تُدخل مطفأة حديدية إلى غرفة MRI: فالمغناطيس يجذبها بقوة.","لا تصبّ الماء على الأجهزة الكهربائية الموصولة بالتيار: خطر صعق كهربائي قاتل.","لا تصبّ الماء على الزيت الساخن: فالزيت يتطاير بعنف وينتشر الحريق."]}],warnings:["الخطوة الأولى دائمًا هي إنقاذ الأشخاص المعرّضين للخطر. لا تغلق صمام الأكسجين الخاص بالمنطقة فورًا: يُحوَّل أولًا المرضى الموصولون بالأكسجين أو بجهاز التنفس الاصطناعي إلى أسطوانة محمولة أو كيس التنفس اليدوي (bag-mask)، ثم يُغلق الصمام بأمر من المسؤول السريري أو وفق خطة الحريق. لا تستخدم المطفأة إلا لحريق صغير؛ فإذا تجاوز الحريق حجم سلة المهملات، فأخلِ المنطقة."],realCase:"حالة عملية (مثال تعليمي): في مختبر أحد المستشفيات، اشتعلت زجاجة كحول بتركيز 70% على طاولة العمل. فطبّقت ممرضة مدرَّبة إجراء RACE فورًا: 1) أبعدت الأشخاص القريبين، 2) أعلنت Code Red عبر الرقم الداخلي، 3) أبقت طريق خروجها مفتوحًا خلفها وأطفأت النار الصغيرة بمطفأة CO₂ وتقنية PASS قبل أن تنتشر، 4) خرجت وأغلقت باب المختبر، وجرت تهوية الغرفة قبل أن يعود إليها أحد. ولأنّ CO₂ لا يترك أي بقايا، لم تتضرّر أجهزة المختبر. ولو استُخدم مسحوق ABC لكان تنظيف الأجهزة أصعب بكثير.",caseStudy:[{prompt:"تعمل في ICU. وفجأة يتصاعد دخان من مضخة IV وتظهر شعلة صغيرة على سلكها. ويوجد مريض على جهاز التنفس الاصطناعي على بُعد مترين. ماذا تفعل أولًا؟",options:[{text:"آخذ مطفأة CO₂ وأبدأ الإطفاء بتقنية PASS",correct:!1,feedback:"ما زال الوقت مبكرًا لذلك. فالمريض معرّض للخطر؛ والخطوة الأولى هي الإنقاذ (R)."},{text:"أفتح باب الغرفة لتجديد الهواء",correct:!1,feedback:"خطير: فالهواء الإضافي يزيد اشتعال النار وينشر الدخان."},{text:"بمساعدة زميلي، أصل المريض بكيس التنفس اليدوي (bag-mask) أو بأسطوانة محمولة، وأبعد سريره عن النار",correct:!0,feedback:"صحيح: الإنقاذ (R — Rescue). وبعد تأمين المريض يأتي الإنذار."},{text:"أستدعي المصعد لنقل المريض",correct:!1,feedback:"لا يجوز استخدام المصعد في أثناء Code Red؛ فقد يتوقف."}]},{prompt:"أُبعد المريض عن الخطر. وما زالت النار صغيرة ولم يمضِ على بدايتها سوى ثوانٍ معدودة. ما الخطوة الثانية؟",options:[{text:"آخذ المطفأة وأبدأ الإطفاء",correct:!1,feedback:"في إجراء RACE يأتي الإنذار قبل الإطفاء، حتى تعلم فرق الإسناد بالحادث."},{text:"أضغط جهاز إنذار الحريق اليدوي (Pull Station) وأتصل برقم الطوارئ الداخلي",correct:!0,feedback:"صحيح: الإنذار (A — Alarm). يجب إعلان Code Red قبل الإطفاء."},{text:"أتصل بأحد زملائي في القسم من هاتفي الشخصي",correct:!1,feedback:"هذا ليس الطريق الرسمي. فجهاز إنذار الحريق والرقم الداخلي يُبلغان فريق Code Red، ويُبلغ المستشفى الدفاع المدني (115) وفق خطته."},{text:"أُسدل ستارة الباب",correct:!1,feedback:"هذا جزء من الاحتواء (Contain)، لا من الإنذار (Alarm). والإنذار يسبق الاحتواء."}]},{prompt:"ما زالت النار صغيرة (أصغر من سلة المهملات)، ومطفأة CO₂ في متناول يدك على بُعد 3 أمتار. ما الخطوة التالية؟",options:[{text:"أُبقي طريق الخروج مفتوحًا خلفي، وأطفئ النار الصغيرة بمطفأة CO₂؛ وإذا لم تنطفئ فورًا، أخرج وأغلق الباب خلفي",correct:!0,feedback:"صحيح: لا تُطفئ إلا والنار صغيرة وطريق خروجك مفتوح؛ وإذا لم تنطفئ، فاخرج وأغلق الباب (Contain). فـ CO₂ مناسب لحرائق الأجهزة الكهربائية ولا يترك أي بقايا؛ وفي الغرفة الصغيرة هوِّ المكان بعد الاستخدام."},{text:"آخذ مطفأة ABC لأنها تصلح لجميع الحرائق",correct:!1,feedback:"تصلح مطفأة ABC للحرائق الكهربائية، لكنّ مسحوقها يلوّث الأجهزة الطبية ويهيّج المجاري التنفسية للمرضى. ومطفأة CO₂ أفضل في ICU."},{text:"أصبّ الماء عليها",correct:!1,feedback:"خطير: فالسلك ما زال موصولًا بالكهرباء، فيحدث صعق كهربائي."},{text:"أفتح الباب لتجديد الهواء",correct:!1,feedback:"فتح الباب لتجديد الهواء يمدّ النار بالأكسجين وينشر الدخان. أبقِ طريق خروجك فقط مفتوحًا، وأغلق الباب خلفك عند خروجك."}]}],quiz:[{question:"ما الخطوة الأولى في ICU عند إعلان Code Red؟",options:[{text:"آخذ أقرب مطفأة وأطفئ النار قبل نقل أيّ مريض",correct:!1,feedback:"قبل الإطفاء، يجب إبعاد المريض عن الخطر."},{text:"أنقذ المرضى المعرّضين للخطر، وأصل الموصولين بالأكسجين بأسطوانة محمولة أو bag-mask",correct:!0,feedback:"صحيح: يبدأ RACE بالإنقاذ. ويُغلق صمام الأكسجين الخاص بالمنطقة لاحقًا وبأمر من المسؤول."},{text:"أفتح النوافذ لإخراج الدخان قبل أيّ إجراء آخر",correct:!1,feedback:"هذا يزيد الهواء ويكبّر الحريق."},{text:"أُبقي المرضى في أسرّتهم وأنتظر في الغرفة حتى يصل فريق 115 ويتولّى الأمر",correct:!1,feedback:"لا تنتظر الفريق؛ ابدأ RACE فورًا."}]},{question:"أيّ مطفأة مناسبة في غرفة MRI؟",options:[{text:"مطفأة ABC العادية (الحديدية) من غرفة التمريض",correct:!1,feedback:"تنجذب المطفأة الحديدية بقوة نحو المغناطيس وتتحوّل إلى قذيفة خطيرة."},{text:"مطفأة غير مغناطيسية معلَّمة للاستخدام في MRI (MR Conditional)",correct:!0,feedback:"صحيح: لا يدخل غرفة MRI (Zone IV) إلا المعدات غير المغناطيسية. ويبقى مغناطيس MRI فعّالًا حتى عند انقطاع الكهرباء."},{text:"ماء في دلو حديدي",correct:!1,feedback:"الدلو الحديدي يتحوّل هو أيضًا إلى قذيفة، والماء خطير على الأجهزة الكهربائية."},{text:"مطفأة CO₂ عادية تُجلب بسرعة من أقرب ممرّ إلى الغرفة",correct:!1,feedback:"المطافئ العادية في الممرات حديدية عمومًا، ولا يجوز إدخالها إلى غرفة MRI."}]},{question:"إلامَ يشير الحرف C في RACE؟",options:[{text:"Call (الاتصال)",correct:!1,feedback:"الاتصال جزء من A (Alarm)."},{text:"Contain (احتواء الحريق)",correct:!0,feedback:"صحيح: إغلاق الأبواب لمنع انتشار الدخان والنار."},{text:"Cool (تبريد الحريق)",correct:!1,feedback:"غير صحيح؛ C تعني Contain (الاحتواء)."},{text:"Collect (جمع المرضى)",correct:!1,feedback:"غير صحيح؛ C تعني Contain (الاحتواء)."}]},{question:"كم من الوقت تعمل تقريبًا مطفأة صغيرة سعة 2 كغ؟",options:[{text:"بضع ثوانٍ فقط؛ والمدة الدقيقة مكتوبة على ملصقها",correct:!0,feedback:"صحيح: إنها مدة قصيرة جدًا، ولذلك يجب توجيهها بدقة نحو قاعدة النار. ومدة التفريغ الدقيقة مكتوبة على الملصق."},{text:"نحو 5 دقائق، وهي مدة تكفي للدوران حول الحريق كله",correct:!1,feedback:"هذا كثير جدًا؛ فالمطفأة الصغيرة تفرغ في غضون ثوانٍ قليلة."},{text:"2–3 دقائق؛ والمدة الدقيقة يُظهرها مقياس الضغط",correct:!1,feedback:"ما زال هذا كثيرًا؛ فالمطفأة الصغيرة تفرغ خلال ثوانٍ قليلة (انظر الملصق)."},{text:"ساعة واحدة",correct:!1,feedback:"هذا طويل جدًا: فالمطفأة الصغيرة تفرغ في غضون ثوانٍ قليلة، والمدة الدقيقة مكتوبة على ملصقها."}],explanation:"تفرغ المطفأة الصغيرة في بضع ثوانٍ فقط، لذا كن مستعدًّا ووجّهها بدقة نحو قاعدة النار. ومدة التفريغ الدقيقة مكتوبة على ملصقها."},{question:"في أثناء Code Red، يريد زميل أن يقفل باب غرفة الحريق بالمفتاح كي لا يدخلها أحد. ما الصحيح؟",options:[{text:"أُغلق الباب ولا أقفله بالمفتاح، كي يتمكّن فريق الاستجابة من الدخول",correct:!0},{text:"أقفله وأترك المفتاح في محطة التمريض لفريق 115",correct:!1},{text:"أتركه مفتوحًا بالكامل ليخرج الدخان إلى الممر",correct:!1},{text:"أتركه نصف مفتوح كي يواصل العاملون تفقّد الحريق",correct:!1}],explanation:"يُغلق الباب لحبس الدخان والنار، لكنه لا يُقفل بالمفتاح، كي يصل فريق 115 وفريق الحريق في المستشفى إلى النار دون تأخير."},{question:"استخدمت مطفأة CO₂ على حريق صغير فوق عربة أجهزة في وحدة العناية المركزة (ICU)، لكن النار لم تنطفئ فورًا. ماذا تفعل؟",options:[{text:"أغادر الغرفة وأغلق الباب خلفي وأواصل خطوات RACE",correct:!0},{text:"أُحضر مطفأة ثانية وأهاجم النار مجددًا وحدي",correct:!1},{text:"أبقى في الغرفة وأواصل الرش حتى تفرغ المطفأة",correct:!1},{text:"أفتح النافذة لإخراج الدخان وأواصل مكافحة النار",correct:!1}],explanation:"المطفأة لحريق ينطفئ فورًا فقط. وإذا لم ينطفئ، فغادر وأغلق الباب لاحتواء الحريق، وواصل الإخلاء وفق خطة الحريق."}],tips:["في بداية كل مناوبة، اعرف مكان أقرب جهاز إنذار حريق يدوي (Pull Station)، ومطافئ الحريق، وصمام الأكسجين الخاص بمنطقة قسمك.","أبقِ الممرات والأبواب المانعة للدخان خالية من الأسرّة والعربات والأجهزة، كي تُغلق الأبواب وتمرّ الأسرّة.","اعرف أيّ مرضاك موصولون بالأكسجين أو بجهاز التنفس الاصطناعي، وأين تُحفظ الأسطوانات المحمولة وأجهزة bag-mask.","عند الاتصال برقم الطوارئ الداخلي، اذكر الطابق والغرفة وما الذي يحترق، ثم اتّبع خطة الحريق في مستشفاك."],activity:{prompt:"أنت ممرض في قسم عام ليلًا. يصرخ أحد الزوّار بأن دخانًا يخرج من غرفة مريض، حيث يوجد شاحن هاتف موصول بالكهرباء بجانب السرير. المريض مسنّ ولا يستطيع المشي. ماذا تفعل أولًا؟",options:[{text:"أُخرج المريض بسريره، وأغلق باب الغرفة، ثم أُطلق إنذار الحريق وأتصل برقم الطوارئ الداخلي",correct:!0,feedback:"صحيح: يبدأ RACE بالإنقاذ، وإغلاق الباب يحبس الدخان داخل الغرفة. وإذا كان زميل قريبًا، يُنقذ أحدكما ويُطلق الآخر الإنذار في الوقت نفسه."},{text:"أذهب إلى محطة التمريض لإحضار مطفأة وأترك باب الغرفة مفتوحًا لأعود بسرعة",correct:!1,feedback:"يبقى المريض في خطر، والباب المفتوح يسمح للدخان بالانتشار في الممر. الإنقاذ أولًا، ثم أغلق الباب."},{text:"أسكب إناءً من الماء على الشاحن والسرير لإيقاف الدخان",correct:!1,feedback:"الماء على مصدر كهربائي موصول بالتيار قد يسبّب الصعق الكهربائي، والمريض لا يزال في الدخان. أنقذ المريض أولًا."},{text:"أتصل بعائلة المريض لأسألهم عمّا يريدون منّا فعله",correct:!1,feedback:"هذا يُضيّع الوقت والمريض في الدخان. ابدأ RACE فورًا واتّبع خطة الحريق في مستشفاك."}]}},{id:2,code:"BLUE-02",icon:"HeartPulse",accent:"#2563eb",category:"الطوارئ",title:"Code Blue — الإنعاش القلبي",subtitle:"الإنعاش القلبي الرئوي (CPR) المتقدّم، وجهاز AED، وعمل فريق Code Blue",summary:"Code Blue هو الرمز الذي يُعلَن في المستشفى عند توقّف القلب أو التنفّس. وكل دقيقة تأخير في الإنعاش القلبي الرئوي (CPR) والصدمة الكهربائية تُنقص فرصة النجاة. ووفق إرشادات AHA 2025، لا يتجاوز فحص التنفّس والنبض 10 ثوانٍ، ثم يبدأ CPR فورًا. ويوضّح هذا الدرس الإنعاش القلبي الرئوي المتقدّم، واستخدام جهاز إزالة الرجفان الخارجي الآلي (AED)، وأدوار فريق Code Blue.",facts:[{label:"الضغطات الصدرية",value:"100–120 ضغطة في الدقيقة"},{label:"عمق الضغط",value:"5–6 سم (للبالغين)"},{label:"نسبة CPR",value:"30:2 (ضغطات:أنفاس)"},{label:"المعيار",value:"AHA 2025"}],steps:[{title:"1. التعرّف على الحالة (أقل من 10 ثوانٍ)",detail:"المريض لا يستجيب، ولا يتنفّس أو يقتصر تنفّسه على شهقات غير طبيعية (gasping)، ولا يوجد نبض في الشريان السباتي (carotid). يجب ألّا يتجاوز الفحص 10 ثوانٍ.",critical:!0},{title:"2. إعلان Code Blue",detail:`اضغط زر Code Blue المثبّت على الجدار، أو اتصل برقم الطوارئ الداخلي للمستشفى.
• لا تنتظر الفريق: ابدأ CPR فورًا.`,critical:!0},{title:"3. CPR بنسبة 30:2",detail:"ضع كعب اليدين على النصف السفلي من عظم القص، وأبقِ ذراعيك مستقيمتين، واضغط بعمق 5–6 سم وبمعدّل 100–120 ضغطة في الدقيقة. اسمح للصدر بالارتداد الكامل إلى وضعه الطبيعي. وبعد كل 30 ضغطة، أعطِ نَفَسين بكيس التنفس اليدوي (bag-mask).",critical:!0},{title:"4. استخدام AED",detail:`شغّل الجهاز، وضع اللاصقتين (pads) على الصدر العاري وفق الرسم الموجود عليهما: واحدة في الجهة اليمنى العليا من الصدر، وأخرى في الجهة اليسرى السفلى من الصدر. يحلّل الجهاز نظم القلب تلقائيًا.
• في أثناء التحليل والصدمة، يجب ألّا يلمس أحد المريض.`,critical:!0},{title:"5. أدوار فريق Code Blue",detail:"الطبيب: قائد الفريق. الممرض 1: الضغطات الصدرية. الممرض 2: الخط الوريدي أو داخل العظم (IV/IO) والأدوية. الفنّي: AED أو جهاز إزالة الرجفان. المسجِّل: يدوّن الأوقات والأدوية والصدمات. ويُستبدل الشخص الذي يجري الضغطات كل دقيقتين."},{title:"6. الأدوية",detail:"Epinephrine 1 mg IV/IO كل 3–5 دقائق. Amiodarone 300 mg في حالات الرجفان البطيني (VF) أو تسرّع القلب البطيني عديم النبض (pVT) المستمرة بعد الصدمات (الجرعة الثانية 150 mg). أمّا Atropine فهو لبطء القلب (bradycardia)، لا لتوقّف القلب."}],reference:[{heading:"CPR للبالغين والأطفال والرضّع",points:["البالغ (من سن البلوغ فما فوق): يدان اثنتان، 5–6 سم، 30:2.","الطفل (من عمر سنة واحدة حتى البلوغ): يد واحدة أو يدان، نحو 5 سم (ثلث عمق الصدر)، 30:2 بمسعف واحد و15:2 بمسعفَين اثنين.","الرضيع (أقل من سنة واحدة): الإبهامان مع إحاطة الصدر باليدين أو كعب يد واحدة، نحو 4 سم، 30:2 بمسعف واحد و15:2 بمسعفَين اثنين.","بدّل الشخص الذي يجري الضغطات كل دقيقتين حتى تبقى الضغطات قوية."]},{heading:"AED — أربع خطوات",points:["1. شغّل الجهاز واتّبع تعليماته الصوتية.","2. ضع اللاصقتين على الصدر العاري وفق الرسم الموجود عليهما.","3. في أثناء التحليل والصدمة، يجب ألّا يلمس أحد المريض.","4. بعد الصدمة، تابع CPR فورًا؛ وسيُعلمك الجهاز متى يعيد تحليل النظم."]},{heading:"حالات خاصة",points:["المرأة الحامل: أزِح الرحم يدويًا نحو اليسار لتخفيف الضغط عن الأوعية الدموية الكبيرة.","الصعق الكهربائي: افصل التيار الكهربائي قبل لمس المصاب.","التأق (Anaphylaxis): Epinephrine حقنًا في العضل (IM) في الجهة الخارجية من الفخذ.","النزف الشديد: ضغط مباشر على الجرح، وخط وريدي لإعطاء السوائل والدم.","المريض على جهاز التنفس الاصطناعي: أعطه التنفّس بكيس التنفس اليدوي (bag-mask) في أثناء النقل."]}],warnings:["لا تنتظر الفريق: ابدأ CPR فورًا. فكل دقيقة تأخير في CPR والصدمة تُنقص فرصة النجاة. اضغط زر Code Blue وابدأ CPR في الوقت نفسه، أو أرسل شخصًا آخر لإطلاق الإنذار."],realCase:"حالة عملية (مثال تعليمي): توقّف قلب مريض عمره 62 عامًا في ICU بعد جراحة قلبية، عند الساعة 22:14. فضغطت ممرضة المناوبة زر Code Blue عند 22:14:07، وبدأت CPR فورًا بنسبة 30:2. ووصل فريق Code Blue عند 22:14:45. ورصد جهاز AED عند 22:15:12 نظم الرجفان البطيني (VF) وأعطى الصدمة الأولى. وبعد صدمتين ونحو 4 دقائق من CPR، عاد القلب إلى العمل عند 22:19 (ROSC). وبقي المريض في ICU لرعاية ما بعد توقّف القلب، وخرج منها بحالة جيدة بعد بضعة أيام. ويبيّن هذا المثال مدى أهمية البدء بـ CPR في الثواني الأولى والصدمة المبكرة.",caseStudy:[{prompt:"أنتِ ممرضة المناوبة في ICU. عند الساعة 23:40 يُظهر جهاز المراقبة لدى أحد المرضى نظم تسرّع القلب البطيني (V-tach)، ثم يتحوّل إلى خط مستقيم. تقتربين من المريض: فإذا هو لا يستجيب ولا يتنفّس. ماذا تفعلين أولًا؟",options:[{text:"أستدعي طبيب المناوبة ليشخّص الحالة",correct:!1,feedback:"تأخير CPR من أجل التشخيص يُنقص فرصة النجاة. فالحالة واضحة: توقّف قلب."},{text:"أضغط زر Code Blue وأبدأ CPR فورًا بنسبة 30:2",correct:!0,feedback:"صحيح: إعلان Code Blue وبدء CPR في الوقت نفسه. لا تنتظري الفريق."},{text:"أبحث عن AED قبل البدء بـ CPR",correct:!1,feedback:"ابدئي CPR فورًا؛ ويمكن لزميل أن يُحضر AED."},{text:"أحضّر دواء Epinephrine",correct:!1,feedback:"الأدوية من مهام فريق Code Blue بعد بدء CPR. والضغطات الصدرية أولًا."}]},{prompt:"مضى على CPR نحو دقيقتين. وصل فريق Code Blue ووُضعت لاصقتا AED. يقول الجهاز: «Shock advised» (يُنصح بالصدمة). ماذا تفعلين؟",options:[{text:"أواصل الضغطات الصدرية حتى في أثناء الصدمة",correct:!1,feedback:"خطير: فالتيار الكهربائي سيصيبك أنتِ أيضًا. في أثناء الصدمة لا يلمس أحد المريض."},{text:"أقول بصوت عالٍ «Clear!»، وأتأكد أنّ أحدًا لا يلمس المريض، ثم أعطي الصدمة",correct:!0,feedback:"صحيح: يجب أن يبتعد الجميع. وبعد الصدمة يُستأنف CPR فورًا."},{text:"بعد الصدمة أنتظر عودة النبض (ROSC)",correct:!1,feedback:"بعد الصدمة تُجرى فورًا دقيقتان من CPR؛ لا تنتظري."},{text:"أنزع AED وأنشغل بتركيب الخط الوريدي (IV)",correct:!1,feedback:"يجب أن يبقى AED موصولًا بالمريض. ويُعاد تحليل النظم بعد دقيقتين من CPR."}]},{prompt:"بعد صدمتين و4 دقائق من CPR، تظهر لدى المريض علامات عودة الدورة الدموية التلقائية (ROSC): يعود النبض والتنفّس. ما الخطوة التالية؟",options:[{text:"أوقف CPR وقد انتهت مهمتنا",correct:!1,feedback:"بعد ROSC تلزم مراقبة دقيقة: جهاز المراقبة، والمجرى الهوائي، والتنفّس، وضغط الدم."},{text:"مراقبة مستمرة، وتقييم المجرى الهوائي والتنفّس والدوران (ABC)، ورعاية ما بعد توقّف القلب في ICU",correct:!0,feedback:"صحيح: تشمل رعاية ما بعد توقّف القلب (post-cardiac arrest care) أيضًا ضبط حرارة الجسم (temperature control)."},{text:"أُخرج المريض من المستشفى",correct:!1,feedback:"يحتاج المريض إلى رعاية مركّزة في ICU."},{text:"أعطي جرعة أخرى من Epinephrine 1 mg كي يستمر ROSC",correct:!1,feedback:"بعد ROSC لا تُعطى جرعة توقّف القلب (1 mg). وإذا كان ضغط الدم منخفضًا، فقد يعطي الطبيب دواءً رافعًا للضغط (vasopressor) بالتسريب المستمر (infusion)."}]}],quiz:[{question:"ما المعدّل الصحيح للضغطات الصدرية؟",options:[{text:"60–80 ضغطة في الدقيقة",correct:!1,feedback:"هذا قليل؛ فالدم لا يصل إلى الدماغ بصورة كافية."},{text:"100–120 ضغطة في الدقيقة",correct:!0,feedback:"صحيح: وفق AHA 2025."},{text:"أكثر من 150 ضغطة في الدقيقة",correct:!1,feedback:"سريع جدًا؛ فلا يمتلئ القلب امتلاءً كاملًا ويقلّ عمق الضغطات."},{text:"أيّ معدّل",correct:!1,feedback:"المعدّل مهم لفعالية CPR."}]},{question:"كيف يُجرى CPR للرضيع (أقل من سنة واحدة)؟",options:[{text:"اليدان معًا في منتصف الصدر، بعمق نحو 6 سم",correct:!1,feedback:"هذا عميق جدًا بالنسبة إلى الرضيع."},{text:"الإبهامان مع إحاطة الصدر باليدين (أو كعب يد واحدة)، نحو 4 سم",correct:!0,feedback:"صحيح: وفق AHA 2025، لم تعد طريقة الإصبعين (two-finger) تُدرَّس."},{text:"يد واحدة، 5 سم",correct:!1,feedback:"هذا للأطفال من عمر سنة واحدة حتى البلوغ."},{text:"لا يُجرى CPR للرضيع؛ تُعطى أنفاس الإنقاذ فقط حتى وصول المساعدة",correct:!1,feedback:"غير صحيح؛ فكل رضيع توقّف قلبه يتلقّى CPR."}]},{question:"متى لا يعطي AED صدمة؟",options:[{text:"عندما يقول الجهاز «No shock advised» (لا يُنصح بالصدمة)",correct:!0,feedback:"صحيح: لا يعطي AED الصدمة إلا لنظمَي VF وVT عديم النبض."},{text:"تُعطى الصدمة دائمًا في البداية، أيًّا كان نظم القلب",correct:!1,feedback:"غير صحيح: فنظم انعدام الانقباض القلبي (Asystole) لا يُعالَج بالصدمة."},{text:"دائمًا قبل CPR",correct:!1,feedback:"يبدأ CPR فورًا، ويُستخدم AED حين يصل."},{text:"للبالغين فقط",correct:!1,feedback:"يُستخدم AED للأطفال أيضًا (بلاصقات الأطفال إن توفّرت)."}]},{question:"ما الدواء الأول في Code Blue؟",options:[{text:"الأتروبين (Atropine) 1 mg IV كل 3–5 دقائق",correct:!1,feedback:"Atropine لبطء القلب، لا لتوقّف القلب."},{text:"الإبينفرين (Epinephrine) 1 mg IV/IO كل 3–5 دقائق",correct:!0,feedback:"صحيح: وفق AHA."},{text:"الأميودارون (Amiodarone) 300 mg IV/IO بجرعة سريعة (bolus)",correct:!1,feedback:"هو لحالات VF أو pVT المستمرة بعد الصدمات، وليس الدواء الأول في جميع الحالات."},{text:"البيكربونات (Bicarbonate) 50 mEq IV لكل المرضى",correct:!1,feedback:"في حالات خاصة فقط، مثل فرط بوتاسيوم الدم (hyperkalemia)."}]},{question:"يُعلن جهاز AED أنه يحلّل نظم القلب، وزميلك يواصل الضغطات. ماذا تفعل؟",options:[{text:"أطلب من الجميع الابتعاد: لا أحد يلمس المريض في أثناء التحليل",correct:!0},{text:"أترك الزميل يواصل، لأن الضغطات لا تتوقف لأي سبب",correct:!1},{text:"أنزع اللاصقتين وأطفئ الجهاز ثم أشغّله من جديد",correct:!1},{text:"أعطي نفَسين بجهاز bag-mask في أثناء تحليل الجهاز",correct:!1}],explanation:"الحركة واللمس يُربكان التحليل، ومن يلمس المريض في أثناء الصدمة قد يُصاب. ابتعدوا في أثناء التحليل والصدمة، ثم تابعوا CPR فورًا."},{question:"تجري الممرضة الضغطات الصدرية منذ دقيقتين، وبدأ عمق الضغطات يقلّ. ماذا يفعل الفريق؟",options:[{text:"نستبدلها بشخص آخر عند فحص النظم، بأقصر توقف ممكن",correct:!0},{text:"نترك الممرضة نفسها تواصل حتى يصل طبيب المريض إلى القسم",correct:!1},{text:"نوقف الإنعاش بضع دقائق كي ترتاح الممرضة وتستعيد قوّتها",correct:!1},{text:"نُبطئ معدّل الضغطات كي لا تتعب الممرضة بسرعة",correct:!1}],explanation:"تضعف الضغطات مع تعب المنقذ، وغالبًا دون أن يلاحظ ذلك. ويُستبدل من يجري الضغطات كل دقيقتين، بأقصر توقف ممكن."}],tips:["في بداية كل مناوبة، افحص عربة الإنعاش وجهاز AED أو جهاز إزالة الرجفان في قسمك وفق قائمة التحقّق المعتمدة في مستشفاك.","اعرف مكان زر Code Blue في كل غرفة تعمل فيها، واحفظ رقم الطوارئ الداخلي.","بدّل الشخص الذي يجري الضغطات كل دقيقتين عند فحص النظم، كي تبقى الضغطات قوية.","استخدم التواصل المغلق الحلقة (closed-loop): يكلّف قائد الفريق شخصًا محدّدًا باسمه بمهمة، فيكرّرها ذلك الشخص ويُبلغ عند إنجازها."],activity:{prompt:"أنت فنّي أشعة. مريض على طاولة الأشعة السينية (X-Ray) توقّف فجأة عن الاستجابة ولا تصدر عنه إلا شهقات غير طبيعية (gasping). ومعك ممرض من الغرفة المجاورة. ماذا تفعل؟",options:[{text:"يُعلن أحدنا Code Blue بينما يبدأ الآخر الضغطات الصدرية فورًا، ويُحضَر جهاز AED إلى الطاولة",correct:!0,feedback:"صحيح: الشهقات غير الطبيعية ليست تنفّسًا طبيعيًا، بل علامة على توقّف القلب. أطلق التنبيه وابدأ الإنعاش القلبي الرئوي (CPR) في الوقت نفسه، ثم استخدم AED فور وصوله."},{text:"ننتظر حتى يتحسّن تنفّسه، لأن الشهقات تعني أن المريض ما زال يتنفّس",correct:!1,feedback:"الشهقات ليست تنفّسًا طبيعيًا. والانتظار يُضيّع دقائق، وكل دقيقة تأخير تُقلّل فرصة النجاة."},{text:"نغادر الغرفة معًا للبحث عن طبيب المريض قبل أي إجراء آخر",correct:!1,feedback:"لا يُترك مريض توقّف قلبه وحده أبدًا. أعلن Code Blue من الغرفة وابدأ CPR؛ فالفريق هو الذي يأتي إليك."},{text:"أقضي بضع دقائق في جسّ النبض حتى أتأكّد تمامًا قبل البدء",correct:!1,feedback:"لا يستغرق فحص التنفّس والنبض أكثر من 10 ثوانٍ. وإذا لم تكن متأكّدًا، فابدأ CPR."}]}},{id:3,code:"ORANGE-03",icon:"FireExtinguisher",accent:"#ea580c",category:"الحريق",title:"فئات الحريق ومطافئ الحريق في المستشفى — NFPA 10",subtitle:"فئات الحريق وفق NFPA 10 واختيار المطفأة المناسبة للمرافق الطبية",summary:"للحريق في المستشفى خصائصه: الأكسجين، والكحول، والأجهزة الطبية الكهربائية، وغرف مثل MRI. وتُحدَّد فئات الحريق واختيار المطافئ وفق NFPA 10 (معيار مطافئ الحريق اليدوية)، فيما يضع NFPA 99 (كود مرافق الرعاية الصحية) إجراءات خاصة بالأكسجين وغرفة العمليات. واختيار المطفأة الخاطئة قد يؤذي المريض أو يعطّل أجهزة حيوية. وفي غرفة العمليات ينتشر الحريق بسرعة كبيرة في الجو الغني بالأكسجين، ولذلك فإنّ الاستجابة الصحيحة والسريعة تنقذ الأرواح. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",facts:[{label:"المعيار",value:"NFPA 10 (المطافئ) + NFPA 99"},{label:"فئات الحريق (NFPA)",value:"A · B · C · D · K"},{label:"OEA (الجو الغني بالأكسجين)",value:"O₂ أكثر من 23.5%"},{label:"حرارة القوس الكهربائي (arc)",value:"حتى نحو 19,400°C"}],steps:[{title:"الفئة A — المواد الصلبة العادية",detail:`الورق والشراشف والأقمشة والبلاستيك. وهي شائعة جدًا في المستشفى. المطفأة: الماء أو مسحوق ABC.
• تحترق هذه المواد بسرعة أكبر بكثير بالقرب من الأكسجين.`,critical:!0},{title:"الفئة B — السوائل والغازات القابلة للاشتعال",detail:`الكحول (مثل جل تعقيم اليدين)، والأسيتون، والإيثر. تبلغ نقطة الوميض (flash point) للإيثانول النقي نحو 13°C، وللإيثر نحو 45°C تحت الصفر. المطفأة للكحول والأسيتون والمذيبات القطبية الأخرى: CO₂ أو ABC أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها. الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه.
• لا تصبّ الماء على السوائل القابلة للاشتعال.`,critical:!0},{title:"الفئة C — الأجهزة الكهربائية الموصولة بالتيار",detail:`أجهزة MRI وCT والأشعة السينية (X-Ray) وجهاز التنفس الاصطناعي وجهاز إزالة الرجفان. افصل التيار الكهربائي إذا استطعت ذلك بأمان. المطفأة: CO₂ أو Clean Agent؛ ومسحوق ABC يصلح أيضًا لكنه يلوّث الأجهزة.
• في غرفة MRI المطفأة غير المغناطيسية فقط.`,critical:!0},{title:"الفئة D وبطاريات الليثيوم",detail:`الفئة D هي المعادن القابلة للاشتعال (مثل المغنيسيوم والصوديوم في المختبرات)، وتحتاج إلى مطفأة Class D أو مادة يذكر ملصقها هذا المعدن؛ فالمادة تختلف من معدن لآخر. أمّا بطاريات الليثيوم أيون (Li-ion) في الأجهزة الطبية والكراسي المتحرّكة الكهربائية والهواتف فلا تحتوي على ليثيوم معدني، ولذلك يُوصى لإطفائها بالماء والتبريد. وClass D مخصّصة لبطاريات الليثيوم المعدني (lithium-metal) فقط.
• قد تشتعل بطارية Li-ion مجددًا بعد إطفائها (thermal runaway)؛ فواصل تبريدها ومراقبتها.`,critical:!0},{title:"الفئة K — زيوت المطبخ",detail:`الزيوت والدهون في المطبخ والكافتيريا. مطفأة Wet Chemical (الفئة K في NFPA؛ والفئة F على ملصقات EN 2) فقط.
• الماء على الزيت الساخن يؤدي إلى تطاير الزيت المشتعل.
• مطفأة ABC غير مناسبة لحرائق زيوت المطبخ، لأنّ الزيت يعاود الاشتعال.`},{title:"OEA — الجو الغني بالأكسجين",detail:"وفق NFPA 99، إذا تجاوزت نسبة الأكسجين في الهواء 23.5%، يُعدّ هذا الهواء جوًا غنيًا بالأكسجين (OEA). وفي هذا الجو تشتعل المواد بسهولة وينتشر الحريق بسرعة كبيرة. أبقِ الأسطوانات بعيدة عن مصادر الحرارة في غرفة العمليات وICU. وإذا اندلع حريق على جسم المريض، يوقف طبيب التخدير فورًا تدفّق الأكسجين إلى المريض.",critical:!0}],reference:[{heading:"جدول الاختيار (NFPA 10)",points:["A: الماء أو ABC.","B: السوائل: CO₂ أو ABC أو الرغوة (foam) (الرغوة المقاومة للكحول للكحول والأسيتون)؛ الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا.","C: CO₂ أو Clean Agent؛ وABC مقبول أيضًا لكنه يلوّث الأجهزة.","D: فقط مطفأة Class D أو مادة يذكر ملصقها هذا المعدن.","K: Wet Chemical فقط."]},{heading:"المطافئ بحسب أقسام المستشفى",points:["غرفة العمليات: CO₂ (توصية ASA)، والمحلول الملحي (saline) للحريق على جسم المريض.","ICU: CO₂ أو Clean Agent للأجهزة الكهربائية.","MRI: المطفأة غير المغناطيسية المعلَّمة للاستخدام في MRI فقط.","المختبر: CO₂ أو ABC، وClass D يذكر ملصقها المعدن في أماكن المعادن القابلة للاشتعال، ومحطة غسل العيون (Eyewash) بالقرب منها.","الصيدلية والمخزن: ABC، وتُحفظ السوائل القابلة للاشتعال في خزائن خاصة."]},{heading:"حريق غرفة العمليات — الخطوات الأولى",points:["1. يوقف طبيب التخدير تدفّق جميع غازات المجرى التنفسي (O₂ وN₂O).","2. تُزال الشراشف وكل المواد المشتعلة عن المريض.","3. تُطفأ النار على جسم المريض بالمحلول الملحي (saline) أو بالخنق.","4. إذا استمرت النار: مطفأة CO₂.","5. إذا لم تنطفئ: Code Red، وإخراج المريض، وإغلاق الباب، وإغلاق صمام غازات الغرفة."]}],warnings:["في غرفة العمليات ينتشر الحريق في الجو الغني بالأكسجين خلال ثوانٍ. أوقف أولًا تدفّق الأكسجين إلى المريض من جهاز التخدير، وأزِل المواد المشتعلة، ثم أطفئ النار. لا تُدخل مطفأة حديدية إلى غرفة MRI: فالمغناطيس يجذبها فتتحوّل إلى قذيفة."],realCase:"حالة عملية (مثال تعليمي): في غرفة العمليات، لم يكن محلول تطهير الجلد الكحولي قد جفّ بعد عندما استُخدم جهاز الكيّ الكهربائي (electrocautery)، فاشتعلت الشراشف. فأحضر أحد العاملين مطفأة ABC، فانتشر المسحوق على الجرح المفتوح وعلى المجرى التنفسي للمريض. وكان الإجراء الصحيح: إيقاف الأكسجين، وإزالة الشراشف المشتعلة، والإطفاء بالمحلول الملحي، ثم مطفأة CO₂ عند الحاجة. الدرس المستفاد: يجب أن يجفّ محلول التطهير تمامًا قبل استخدام جهاز الكيّ.",caseStudy:[{prompt:"أنتِ ممرضة غرفة العمليات. في أثناء الجراحة، أشعل جهاز الكيّ محلول التطهير الكحولي، فظهرت النار على صدر المريض. والمريض يتلقّى أكسجينًا بتركيز 100%. ما الخطوة الأولى؟",options:[{text:"أرشّ مطفأة ABC على المريض",correct:!1,feedback:"خطير: فالمسحوق يدخل الجرح والمجرى التنفسي. توصي ASA بمطفأة CO₂، وذلك فقط بعد إيقاف الغاز."},{text:"أصبّ الماء عليها",correct:!1,feedback:"يستطيع المحلول الملحي (saline) إطفاء النار على جسم المريض، لكن ما لم يُوقَف الأكسجين تعاود النار الاشتعال. والخطوة الأولى هي إيقاف الأكسجين."},{text:"أطلب من طبيب التخدير إيقاف تدفّق الأكسجين إلى المريض فورًا",correct:!0,feedback:"صحيح: فمن دون الأكسجين الزائد تضعف النار كثيرًا. ويتمّ هذا الإيقاف من جهاز التخدير، لا بإغلاق صمام المنطقة."},{text:"أبدأ الإخلاء الأفقي",correct:!1,feedback:"المريض على طاولة العمليات؛ أوقفي الأكسجين أولًا ثم أطفئي النار."}]},{prompt:"أُوقف الأكسجين، لكنّ النار ما زالت على الصدر. ما الخطوة الثانية؟",options:[{text:"آخذ مطفأة ABC",correct:!1,feedback:"مسحوق ABC يلوّث الجرح والمجرى التنفسي. وإذا لزمت مطفأة، فاستخدمي CO₂."},{text:"أزيل الشراشف المشتعلة، وأطفئ النار بالمحلول الملحي (saline) أو بالخنق",correct:!0,feedback:"صحيح: وفق إرشادات ASA، إزالة المواد المشتعلة والإطفاء بالمحلول الملحي."},{text:"أُنزل المريض عن الطاولة",correct:!1,feedback:"خطير: يُصاب المريض وتنتشر النار."},{text:"أنتظر فريق Code Red",correct:!1,feedback:"هذا تأخير كبير؛ فالمحلول الملحي والقماش المبلَّل في متناول يدكِ."}]},{prompt:"انطفأت النار. ما الخطوة الثالثة؟",options:[{text:"أواصل الجراحة كما كانت",correct:!1,feedback:"غير صحيح: يجب فحص المريض فحصًا كاملًا وتوثيق الحادث."},{text:"أعلن Code Red، وأفحص المريض بحثًا عن الحروق، وأوثّق الحادث",correct:!0,feedback:"صحيح: إعلان Code Red، وفحص الحروق، وتقرير الحادث (Incident Report)."},{text:"أغادر الغرفة ولا أقول شيئًا",correct:!1,feedback:"تقرير الحادث ضروري لسلامة المرضى وللتعلّم من الحادث."},{text:"أنقل المريض إلى مستشفى آخر لإكمال الجراحة هناك",correct:!1,feedback:"قبل أي نقل، يلزم فحص كامل."}]}],quiz:[{question:"أيّ مطفأة تُستخدم في غرفة MRI؟",options:[{text:"مطفأة ABC العادية الموجودة في ممرّ القسم",correct:!1,feedback:"تنجذب المطفأة الحديدية نحو المغناطيس وتتحوّل إلى قذيفة."},{text:"المطفأة غير المغناطيسية المعلَّمة للاستخدام في MRI",correct:!0,feedback:"صحيح: في غرفة MRI (Zone IV) لا يُسمح إلا بالمعدات غير المغناطيسية."},{text:"ماء في دلو حديدي",correct:!1,feedback:"الدلو الحديدي يتحوّل هو أيضًا إلى قذيفة."},{text:"أيّ مطفأة CO₂، لأن غاز CO₂ لا يترك أيّ أثر",correct:!1,feedback:"لا يجوز أن تدخل الغرفة إلا مطفأة CO₂ غير مغناطيسية (MR Conditional)."}]},{question:"ما المقصود بـ OEA؟",options:[{text:"الفئة D من الحريق",correct:!1,feedback:"غير صحيح؛ الفئة D هي المعادن القابلة للاشتعال."},{text:"هواء تتجاوز فيه نسبة الأكسجين 23.5%",correct:!0,feedback:"صحيح: الجو الغني بالأكسجين (Oxygen-Enriched Atmosphere) وفق NFPA 99."},{text:"أحد معايير NFPA لأنابيب الأكسجين في المستشفيات",correct:!1,feedback:"OEA ليس معيارًا، بل حالة للهواء يعرّفها NFPA 99 بأنها نسبة أكسجين تتجاوز 23.5%."},{text:"جهاز من أجهزة السلامة يقيس مستوى الأكسجين في الغرفة",correct:!1,feedback:"OEA ليس جهازًا، بل هواء تتجاوز فيه نسبة الأكسجين 23.5% وتشتعل فيه المواد بسهولة."}],explanation:"وفق NFPA 99، الجو الغني بالأكسجين (OEA) هو هواء تتجاوز فيه نسبة الأكسجين 23.5%، وفيه تشتعل المواد بسهولة وينتشر الحريق بسرعة كبيرة."},{question:"كيف يُطفأ حريق بطارية الليثيوم أيون (Li-ion) في جهاز طبي؟",options:[{text:"بمطفأة Class D أو الرمل الجاف فقط، لأنّ الماء يسبّب الانفجار دائمًا في أيّ بطارية ليثيوم",correct:!1,feedback:"غير صحيح: هذا ينطبق على بطاريات الليثيوم المعدني. فبطاريات الليثيوم أيون (Li-ion) لا تحتوي على ليثيوم معدني."},{text:"بالماء أو بمطفأة مائية مع تبريد مستمر؛ وClass D لبطاريات الليثيوم المعدني فقط",correct:!0,feedback:"صحيح: يمنع التبريد حدوث الانفلات الحراري (thermal runaway) وعودة الاشتعال."},{text:"بـ CO₂ لإطفاء اللهب، ثم أترك البطارية وحدها لتبرد من تلقاء نفسها",correct:!1,feedback:"يطفئ CO₂ اللهب لكنه لا يبرّد البطارية؛ وقد تعاود الاشتعال."},{text:"بـ ABC، ثم لا أفعل شيئًا",correct:!1,feedback:"لا يبرّد ABC البطارية؛ فيستمر الانفلات الحراري (thermal runaway)."}]},{question:"ما الخطوة الأولى عند نشوب حريق في غرفة العمليات؟",options:[{text:"آخذ المطفأة وأرشّها على موضع الجراحة",correct:!1,feedback:"قبل استخدام المطفأة، أوقف تدفّق الأكسجين."},{text:"إيقاف تدفّق الأكسجين والغازات الأخرى إلى المريض",correct:!0,feedback:"صحيح: وفق ASA، تُوقَف غازات المجرى التنفسي فورًا."},{text:"إخراج المريض من الغرفة قبل أيّ إجراء آخر",correct:!1,feedback:"لاحقًا، إذا لم تتمّ السيطرة على الحريق."},{text:"صبّ الماء على الأجهزة الكهربائية",correct:!1,feedback:"غير صحيح: الماء على الأجهزة الموصولة بالكهرباء خطير."}]},{question:"يبدأ حريق صغير في سلة مهملات في ممر أحد الأقسام. معك المطفأة المناسبة، لكن الدخان ينتشر نحو طريق خروجك الوحيد. ماذا تفعل؟",options:[{text:"لا أستخدم المطفأة: أغادر وأغلق الأبواب وأُعلن Code Red",correct:!0},{text:"أطفئه بسرعة، لأن الحريق صغير والمطفأة مناسبة",correct:!1},{text:"أتقدّم عبر الدخان لأقترب كي يصل الرذاذ إلى قاعدة النار",correct:!1},{text:"أرشّ من مكاني ثم أخرج زحفًا تحت الدخان",correct:!1}],explanation:"يجب أن تكون إجابة كل بنود فحص «نعم/لا» نعم. والدخان الذي يسدّ طريق الخروج يعني لا: غادر، واحتوِ الحريق بإغلاق الأبواب، وأطلق الإنذار."},{question:"يبدأ حريق صغير في مشترك كهربائي (power strip) خلف شاشة مراقبة في ICU، وإجابة كل بنود فحص «نعم/لا» نعم. ما الخيار الصحيح؟",options:[{text:"أفصل التيار إن كان ذلك آمنًا، ثم أستخدم CO₂ أو العامل النظيف (clean agent) وفق الملصق",correct:!0},{text:"أستخدم مطفأة الماء، لأن الماء يبرّد النار أسرع من أي مادة أخرى",correct:!1},{text:"أستخدم الرغوة، لأنها تصلح لكل أنواع الحرائق في أقسام المستشفى",correct:!1},{text:"أرمي منشفة مبلّلة على الشاشة والمشترك الكهربائي الموصولين بالتيار",correct:!1}],explanation:"حريق الأجهزة الموصولة بالتيار هو الفئة C بحروف NFPA. افصل التيار إن استطعت ذلك بأمان، واستخدم CO₂ أو العامل النظيف؛ فالماء والرغوة يوصلان الكهرباء."}],tips:["تعرّف إلى مطافئ قسمك: اقرأ ملصق كل مطفأة لتعرف فئات الحريق التي تغطيها وطريقة استخدامها.","قبل استخدام أي مطفأة، أجرِ فحص «نعم/لا»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وأُطلق الإنذار، وأنت مدرَّب، ولا يسدّ الدخان أو الحرارة طريقك.","إذا كانت مطفأة مفقودة أو محجوبة أو مستعملة، أو أظهر مقياس الضغط أنها غير جاهزة، فأبلغ فورًا فريق السلامة أو الهندسة في مستشفاك.","لا تُدخل أي مطفأة إلى غرفة MRI أبدًا ما لم يذكر ملصقها أنها مخصّصة لغرفة MRI."],activity:{prompt:"تعمل في مطبخ المستشفى. اشتعل الزيت في المقلاة العميقة (fryer). على الجدار مطفأة مسحوق (ABC)، وبجانب المقلاة مطفأة Wet Chemical (الفئة K). وقد أُطلق الإنذار وطريق الخروج خلفك. ماذا تفعل؟",options:[{text:"أُطفئ المقلاة إن كان ذلك آمنًا، وأستخدم مطفأة Wet Chemical وفق ملصقها، وأغادر إذا لم تنطفئ النار فورًا",correct:!0,feedback:"صحيح: حريق زيت الطهي يحتاج إلى مطفأة Wet Chemical (الفئة K؛ والفئة F على ملصقات EN 2). وإطفاء مصدر الحرارة يساعد على منع عودة الاشتعال. وإذا لم تنطفئ النار فورًا، فغادر وأغلق الباب."},{text:"أسكب وعاءً من الماء على المقلاة لتبريد الزيت بسرعة",correct:!1,feedback:"الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل خارج المقلاة. لا تستخدم الماء أبدًا على حريق زيت الطهي."},{text:"أستخدم مطفأة مسحوق ABC المعلّقة على الجدار، لأن ABC تغطي كل الفئات",correct:!1,feedback:"تغطي ABC الفئات A وB وC فقط، لا زيت الطهي. وقد يعود الزيت إلى الاشتعال بعد المسحوق. استخدم مطفأة Wet Chemical."},{text:"أحمل المقلاة إلى الخارج كي تنطفئ النار وحدها في الهواء الطلق",correct:!1,feedback:"نقل وعاء زيت مشتعل قد يسكبه عليك وعلى غيرك وينشر الحريق. اتركه في مكانه."}]}},{id:4,code:"PED-04",icon:"Baby",accent:"#ec4899",category:"طبي",title:"الإنعاش القلبي الرئوي (CPR) للأطفال والرضّع",subtitle:"وحدة العناية المركزة لحديثي الولادة (NICU)، وCode Blue للأطفال، والإجراءات الخاصة",summary:"يختلف CPR للأطفال عنه لدى البالغين في عمق الضغط، وتقنية اليدين، وجرعات الأدوية. ووفق AHA 2025، الرضيع هو من كان عمره أقل من سنة واحدة (باستثناء حديثي الولادة)، والطفل من عمر سنة واحدة حتى البلوغ. وترتيب CPR للرضّع والأطفال هو C-A-B: الضغطات الصدرية، ثم فتح المجرى الهوائي والتنفّس. ومعظم حالات توقّف القلب لدى الأطفال تنشأ عن مشكلات تنفّسية، ولذلك فإنّ التهوية الجيدة بالأكسجين بالغة الأهمية. أمّا حديثو الولادة في غرفة الولادة وفي وحدة العناية المركزة لحديثي الولادة (NICU) فيُعالَجون وفق بروتوكول خاص لإنعاش حديثي الولادة (NRP).",facts:[{label:"الرضيع (أقل من سنة واحدة)",value:"الإبهامان أو كعب اليد · نحو 4 سم · 100–120 ضغطة في الدقيقة"},{label:"الطفل (من سنة واحدة حتى البلوغ)",value:"يد واحدة أو يدان · نحو 5 سم · 100–120 ضغطة في الدقيقة"},{label:"حرارة حديث الولادة",value:"36.5–37.5°C"},{label:"المعيار",value:"AHA PALS 2025 + NRP"}],steps:[{title:"1. التعرّف على الحالة",detail:"الطفل لا يستجيب، ولا يتنفّس أو يقتصر تنفّسه على شهقات غير طبيعية (gasping). افحص النبض لدى الرضيع في باطن العضد (brachial)، ولدى الطفل في الشريان السباتي (carotid) أو الفخذي (femoral)، على ألّا يتجاوز الفحص 10 ثوانٍ.",critical:!0},{title:"2. ترتيب C-A-B وأهمية التنفّس",detail:"وفق AHA، يبدأ CPR للرضّع والأطفال بالضغطات الصدرية، ثم فتح المجرى الهوائي والتنفّس (C-A-B). ولأنّ معظم حالات توقّف القلب لدى الأطفال تنشأ عن قصور التنفّس، يجب البدء مبكرًا بأنفاس فعّالة بكيس التنفس اليدوي (bag-mask) والأكسجين. أبقِ رأس الرضيع في الوضع المحايد (neutral)؛ فإمالة الرأس إلى الخلف أكثر من اللازم تسدّ المجرى الهوائي.",critical:!0},{title:"3. CPR للرضيع (أقل من سنة واحدة)",detail:"ضع الإبهامين على النصف السفلي من عظم القص وأحِط الصدر بيديك (two-thumb encircling)؛ وإذا لم تستطع إحاطة الصدر، فاستخدم كعب يد واحدة. ولم تعد طريقة الإصبعين (two-finger) تُدرَّس. العمق نحو 4 سم (ثلث عمق الصدر). 30:2 بمسعف واحد، و15:2 بمسعفَين.",critical:!0},{title:"4. CPR للطفل (من سنة واحدة حتى البلوغ)",detail:"كعب يد واحدة، أو اليدان للطفل الكبير، على النصف السفلي من عظم القص. العمق نحو 5 سم (ثلث عمق الصدر)، والمعدّل 100–120 ضغطة في الدقيقة. 30:2 بمسعف واحد، و15:2 بمسعفَين.",critical:!0},{title:"5. AED للأطفال",detail:"للأطفال دون 8 سنوات، استخدم لاصقات الأطفال أو مخفّض الجرعة (pediatric attenuator) إن توفّرت؛ وإن لم تتوفّر، فاستخدم لاصقات البالغين. يجب ألّا تتلامس اللاصقتان؛ فإذا كان الصدر صغيرًا، ضع إحداهما على مقدّم الصدر والأخرى على الظهر (anterior-posterior). وحدّ الـ 8 سنوات يخصّ جرعة AED فقط، لا تعريف الطفل."},{title:"6. NICU — إنعاش حديثي الولادة (NRP)",detail:"حافظ على حرارة الجسم ضمن النطاق 36.5–37.5°C. الخطوة الأولى هي التهوية بالضغط الإيجابي (PPV). فإذا بقي معدّل ضربات القلب أقل من 60 بعد 30 ثانية من التهوية الفعّالة: ضغطات صدرية بالإبهامين مع إحاطة الصدر، بعمق نحو ثلث عمق الصدر، وبنسبة 3:1 (90 ضغطة و30 نَفَسًا في الدقيقة) مع أكسجين 100%. وإذا بقي معدّل ضربات القلب أقل من 60 بعد 60 ثانية من الضغطات: Epinephrine 0.01–0.03 mg/kg IV، وتُكرَّر كل 3–5 دقائق عند الحاجة. وفي أثناء الحريق، انقل الرضّع في المهد أو العربة، لا على الأيدي."}],reference:[{heading:"جرعات الأدوية بحسب الوزن (PALS)",points:["Epinephrine: 0.01 mg/kg IV/IO كل 3–5 دقائق (بحدّ أقصى 1 mg).","Amiodarone: 5 mg/kg IV/IO لحالات VF أو pVT المستمرة.","Atropine: 0.02 mg/kg IV/IO لبطء القلب (bradycardia) ذي المنشأ المبهمي (vagal)، بعد الأكسجين والتهوية.","Adenosine: 0.1 mg/kg (بحدّ أقصى 6 mg) لتسرّع القلب فوق البطيني (SVT).","Glucose: 0.5–1 g/kg إذا كان سكر الدم منخفضًا (hypoglycemia)."]},{heading:"علامات الخطر لدى الرضيع",points:["ازرقاق الجلد (cyanosis): تهوية غير كافية.","معدّل ضربات القلب أقل من 60 في الدقيقة مع علامات ضعف التروية الدموية: ابدأ CPR.","الخمول وضعف الاستجابة (lethargy).","بكاء ضعيف أو انعدام البكاء.","انقطاع التنفّس (apnea) أكثر من 20 ثانية."]},{heading:"الحريق في أقسام الأطفال",points:["الحاضنات أجهزة كهربائية تحتوي على الأكسجين؛ وخطر الحريق فيها مرتفع.","لا يستطيع الرضّع الهرب بأنفسهم؛ والإخلاء الأفقي أولًا.","يمكن نقل عدة رضّع معًا في مهد واحد أو عربة واحدة.","لا يُغلق صمام الأكسجين إلا بعد تحويل الرضّع إلى أكسجين محمول وبأمر من المسؤول.","النقل إلى قسم آمن في الطابق نفسه."]}],warnings:["لا تحرّك الرضيع بعنف. أبقِ رأس الرضيع في الوضع المحايد؛ فإمالة الرأس إلى الخلف أكثر من اللازم تسدّ المجرى الهوائي. يجب ألّا تتلامس لاصقتا AED على الصدر الصغير؛ وفي هذه الحالة استخدم الوضعية الأمامية الخلفية (anterior-posterior). لا تعطِ الطفل جرعة Epinephrine الخاصة بالبالغين (1 mg)؛ فالجرعة بحسب الوزن: 0.01 mg/kg."],realCase:"حالة عملية (مثال تعليمي): في وحدة العناية المركزة لحديثي الولادة (NICU)، وعند الساعة 03:12، توقّف تنفّس رضيع عمره 10 أيام (2.3 كغ) مصاب بعدوى رئوية، وتباطأ نبضه. فبدأت ممرضة NICU فورًا التهوية بالضغط الإيجابي (PPV) بالقناع، وأعلنت Code Blue للأطفال. وعند 03:13، بعد 30 ثانية من التهوية الفعّالة، كان معدّل ضربات القلب ما يزال أقل من 60؛ فبدأ الفريق الضغطات الصدرية بالإبهامين، بنسبة 3:1 مع أكسجين 100%. وعند 03:14 كان معدّل ضربات القلب ما يزال أقل من 60، فأُعطي Epinephrine 0.02 mg/kg IV (نحو 0.05 mg). وعند 03:16 تجاوز معدّل ضربات القلب 60 فأُوقفت الضغطات؛ واستمرت التهوية حتى تجاوز معدّل ضربات القلب 100. وبقي الرضيع في NICU بضعة أيام ثم تعافى تمامًا.",caseStudy:[{prompt:"أنتِ ممرضة في وحدة العناية المركّزة للأطفال (PICU). عند الساعة 02:40 يُظهر جهاز المراقبة لدى رضيع عمره شهران بطئًا في القلب (50 ضربة في الدقيقة). الرضيع مزرقّ وأنفاسه ضعيفة، لكنكِ تشعرين بالنبض في العضد. ما الخطوة الأولى؟",options:[{text:"أبدأ الضغطات الصدرية فورًا من دون تهوية",correct:!1,feedback:"لدى الرضيع نبض. ووفق PALS لبطء القلب، افتحي المجرى الهوائي أولًا وأعطي التهوية بالأكسجين؛ فإذا بقي معدّل ضربات القلب أقل من 60، تبدأ الضغطات."},{text:"أفتح المجرى الهوائي، وأعطي التهوية بكيس التنفس اليدوي (bag-mask) والأكسجين، وأطلب المساعدة (Code Blue)",correct:!0,feedback:"صحيح: للرضيع الذي لديه نبض مع بطء القلب، تأتي الأكسجة والتهوية الفعّالة أولًا (PALS). أمّا إذا كان الرضيع بلا نبض، فيبدأ CPR بترتيب C-A-B."},{text:"أحضّر Epinephrine",correct:!1,feedback:"الدواء يأتي لاحقًا؛ الأكسجين والتهوية أولًا."},{text:"أستدعي المصعد لنقل الرضيع",correct:!1,feedback:"النقل في هذه المرحلة خطير؛ ابدئي العلاج في مكانه."}]},{prompt:"بعد التهوية الفعّالة بالأكسجين، ما زال معدّل ضربات قلب الرضيع 40 في الدقيقة، مع علامات ضعف التروية الدموية. ماذا تفعلين؟",options:[{text:"أكتفي بمواصلة التهوية",correct:!1,feedback:"معدّل ضربات قلب أقل من 60 مع ضعف التروية، رغم التهوية الجيدة، يستلزم CPR."},{text:"أبدأ CPR: الإبهامان مع إحاطة الصدر، بعمق نحو 4 سم، وبنسبة 15:2 (مسعفان)",correct:!0,feedback:"صحيح: وفق PALS، نبض أقل من 60 مع نقص التروية (hypoperfusion) = CPR. ونسبة 15:2 لمسعفَين."},{text:"أعطي أنفاسًا قوية جدًا",correct:!1,feedback:"خطير: فالأنفاس القوية تؤذي الرئتين (barotrauma). والمطلوب CPR."},{text:"أنتظر الطبيب",correct:!1,feedback:"ابدئي CPR؛ لا تنتظري الفريق."}]},{prompt:"وصل الفريق. تحوّل نظم الرضيع إلى الرجفان البطيني (VF) وتلزم الصدمة. لا يوجد جهاز إزالة رجفان يدوي، وليس مع AED سوى لاصقات البالغين. ماذا تفعلين؟",options:[{text:"لا أستخدم AED",correct:!1,feedback:"في VF تلزم الصدمة؛ وAED بلاصقات البالغين أفضل من عدم إعطاء الصدمة."},{text:"أضع لاصقات البالغين: واحدة على مقدّم الصدر وأخرى على الظهر (anterior-posterior)",correct:!0,feedback:"صحيح: على الصدر الصغير، تمنع الوضعية الأمامية الخلفية (anterior-posterior) تلامس اللاصقتين."},{text:"أضع اللاصقتين متقاربتين على مقدّم الصدر",correct:!1,feedback:"ستتلامس اللاصقتان ولن تكون الصدمة فعّالة."},{text:"أكتفي بمواصلة CPR",correct:!1,feedback:"في VF لا يكفي CPR وحده؛ فالصدمة ضرورية."}]}],quiz:[{question:"كيف يُجرى CPR للرضيع (أقل من سنة واحدة)؟",options:[{text:"اليدان معًا في منتصف الصدر، بعمق نحو 6 سم",correct:!1,feedback:"هذا عميق جدًا بالنسبة إلى الرضيع."},{text:"الإبهامان مع إحاطة الصدر باليدين (أو كعب يد واحدة)، نحو 4 سم",correct:!0,feedback:"صحيح: وفق AHA 2025؛ لم تعد طريقة الإصبعين تُدرَّس."},{text:"يد واحدة، 5 سم",correct:!1,feedback:"هذا للأطفال من عمر سنة واحدة حتى البلوغ."},{text:"لا يُجرى CPR للرضيع؛ تُعطى أنفاس الإنقاذ فقط حتى وصول المساعدة",correct:!1,feedback:"كل رضيع توقّف قلبه يتلقّى CPR."}]},{question:"ما جرعة Epinephrine للأطفال في توقّف القلب؟",options:[{text:"1 mg IV/IO كل 3–5 دقائق",correct:!1,feedback:"هذه جرعة البالغين؛ وهي خطيرة على الطفل."},{text:"0.01 mg/kg IV/IO",correct:!0,feedback:"صحيح: بحسب الوزن، وبحدّ أقصى 1 mg."},{text:"0.5 mg IV",correct:!1,feedback:"كثيرة جدًا بالنسبة إلى الرضيع."},{text:"0.1 mg/kg IV/IO",correct:!1,feedback:"عشرة أضعاف الجرعة الصحيحة؛ وهذا خطير."}]},{question:"ما ترتيب CPR وفق AHA لدى الرضّع والأطفال الذين توقّفت قلوبهم؟",options:[{text:"B-C-A: أنفاس الإنقاذ أولًا، ثم الضغطات الصدرية، ثم المجرى الهوائي",correct:!1,feedback:"غير صحيح: تعتمد AHA ترتيب C-A-B للرضّع والأطفال. أمّا إنعاش حديثي الولادة (NRP) فمختلف."},{text:"C-A-B: الضغطات الصدرية، ثم المجرى الهوائي والتنفّس",correct:!0,feedback:"صحيح: تأتي الأنفاس بعد 30 (أو 15) ضغطة، وهي بالغة الأهمية."},{text:"Epinephrine أولًا",correct:!1,feedback:"الدواء يأتي لاحقًا."},{text:"AED أولًا، ثم CPR بعد الصدمة الأولى",correct:!1,feedback:"يبدأ CPR فورًا، ويُستخدم AED حين يصل."}]},{question:"عند استخدام AED للرضيع، أيّ لاصقات تُستخدم؟",options:[{text:"لا يُستخدم AED للرضيع أبدًا؛ يُكتفى بـ CPR حتى وصول الإسعاف",correct:!1,feedback:"غير صحيح؛ يُستخدم AED عند الحاجة."},{text:"لاصقات الأطفال أو مخفّض الجرعة؛ وإن لم تتوفّر، فلاصقات البالغين بوضعية anterior-posterior",correct:!0,feedback:"لاصقات الأطفال أو مخفّض الجرعة تُقلّل جرعة AED للرضيع؛ وإن لم تتوفّر، فلاصقات البالغين أمامًا وخلفًا حتى لا تتلامس."},{text:"لاصقات البالغين متقاربة على مقدّم الصدر كما عند البالغين، لكي تصل الصدمة إلى القلب",correct:!1,feedback:"ستتلامس اللاصقتان."},{text:"لاصقات مصنوعة يدويًا",correct:!1,feedback:"ليس هذا ما يعلّمه الدرس: استخدم لاصقات الأطفال أو مخفّض الجرعة، أو لاصقات البالغين بوضعية anterior-posterior."}],explanation:"للأطفال دون 8 سنوات، استخدم لاصقات الأطفال أو مخفّض الجرعة إن توفّرت، وإلا فلاصقات البالغين. وعلى الصدر الصغير ضعها بوضعية anterior-posterior حتى لا تتلامس."},{question:"تجري أنت وزميلك CPR لرضيع عمره 6 أشهر. ما الطريقة الصحيحة؟",options:[{text:"الإبهامان مع إحاطة الصدر، بعمق نحو ثلث عمقه، بنسبة 15:2",correct:!0},{text:"إصبعان على عظم القص، كما كان يُدرَّس في الدورات القديمة",correct:!1},{text:"كعبا راحتي اليدين، بالعمق نفسه المستخدم للبالغين",correct:!1},{text:"ضغطات فقط من دون أنفاس، لأن الرضّع نادرًا ما يحتاجون إليها",correct:!1}],explanation:"مع مسعفَين، يُجرى CPR للرضيع بالإبهامين مع إحاطة الصدر (أو بكعب يد واحدة)، بعمق نحو ثلث عمق الصدر (نحو 4 سم)، وبنسبة 15:2. ولم تعد طريقة الإصبعين تُدرَّس."},{question:"توقّف قلب طفل بعد نوبة ربو (asthma) شديدة. يقول زميلك إن الضغطات وحدها تكفي حتى يصل الفريق، مع أن جهاز bag-mask والأكسجين بجانب السرير. ما الصحيح؟",options:[{text:"نجري الضغطات مع أنفاس فعّالة مبكرة بجهاز bag-mask والأكسجين",correct:!0},{text:"نجري الضغطات فقط، كما يفعل عامة الناس مع البالغين، حتى يصل الفريق",correct:!1},{text:"نعطي الأكسجين بالقناع فقط وننتظر عودة النبض",correct:!1},{text:"لا نعطي الأنفاس إلا بعد أول صدمة من جهاز AED",correct:!1}],explanation:"معظم حالات توقّف القلب عند الأطفال سببها مشكلات التنفّس، ولذلك يحتاج الأطفال إلى الأنفاس بشكل خاص. وعندما يتوفّر جهاز bag-mask والأكسجين، يجري العاملون المدرَّبون الضغطات مع أنفاس فعّالة مبكرة."}],tips:["اعرف مكان معدّات إنعاش الأطفال في قسمك، ومنها أجهزة bag-mask للأطفال والرضّع ولاصقات AED الخاصة بالأطفال.","استخدم جدول الجرعات حسب الوزن أو الأداة التي يعتمدها مستشفاك؛ ولا تحسب جرعة الطفل من الذاكرة تحت الضغط.","تدرّب على CPR للرضّع والأطفال على الدمى (manikin) في تمارين قسمك، كي يصبح وضع اليدين والعمق أمرًا تلقائيًا.","في أثناء الحريق، انقل الرضّع في المهد أو العربة، لا على الأيدي."],activity:{prompt:"أنت ممرض في قسم الأطفال. وجدت طفلًا عمره 4 سنوات في سريره لا يستجيب ولا يتنفّس، وزميلك في الغرفة المجاورة. ماذا تفعل؟",options:[{text:"أنادي زميلي بصوت عالٍ ليُعلن Code Blue ويُحضر AED، وأبدأ CPR فورًا: الضغطات أولًا ثم التنفّس (C-A-B)",correct:!0,feedback:"صحيح: لا تنتظر الفريق. يُجرى CPR للطفل بترتيب C-A-B مع أنفاس فعّالة مبكرة، لأن معظم حالات توقّف القلب عند الأطفال سببها مشكلات التنفّس."},{text:"أعطي أنفاس الإنقاذ فقط وأنتظر الفريق، لأن الأطفال لا يحتاجون إلى الضغطات",correct:!1,feedback:"الطفل الذي لا يستجيب ولا يتنفّس يحتاج إلى CPR كامل: ضغطات وأنفاس. وانتظار الفريق يُضيّع الوقت."},{text:"أهزّ الطفل بقوة ليستيقظ، ثم أنتظر بضع دقائق لأرى هل يستجيب",correct:!1,feedback:"الهزّ العنيف قد يؤذي الطفل، والانتظار يؤخّر CPR. تحقّق من الاستجابة بلطف وابدأ CPR فورًا."},{text:"أترك الطفل وأذهب بنفسي لإحضار AED قبل أن أبدأ أي شيء",correct:!1,feedback:"لا تترك الطفل: اطلب المساعدة وابدأ CPR، وليُحضر شخص آخر جهاز AED."}]}},{id:5,code:"O2-05",icon:"Wind",accent:"#0891b2",category:"السلامة",title:"سلامة الأكسجين",subtitle:"الأسطوانات، وشبكة الغازات الطبية (MGPS)، وخطر الجو الغني بالأكسجين (OEA)",summary:"الأكسجين ينقذ الأرواح، لكنه خطير أيضًا. فالأكسجين لا يحترق بذاته، لكنه يجعل النار أقوى وأسرع بكثير، ويتيح للمواد أن تشتعل عند درجة حرارة أدنى. وتحتوي أسطوانة الأكسجين الممتلئة على ضغط مرتفع (نحو 200 بار في كثير من الأحيان)؛ فإذا انكسر صمامها، تتحوّل الأسطوانة إلى ما يشبه الصاروخ. وتُنظَّم شبكة الغازات الطبية (MGPS) والأسطوانات وتُفحص وفق NFPA 99. وفي غرفة العمليات، يشكّل اجتماع الأكسجين وجهاز الكيّ والمحلول الكحولي خطر حريق رئيسيًا.",facts:[{label:"ضغط الأسطوانة الممتلئة",value:"نحو 200 بار (2,900 psi)"},{label:"حدّ OEA",value:"O₂ أكثر من 23.5% (NFPA 99)"},{label:"لون أسطوانة O₂",value:"أبيض (ISO 32) / أخضر (الولايات المتحدة)"},{label:"معيار MGPS",value:"NFPA 99"}],steps:[{title:"1. حمل الأسطوانات ونقلها",detail:"انقل الأسطوانة دائمًا بعربة مخصّصة، لا باليد ولا على الكتف. ثبّت الأسطوانات بالجدار بسلسلة أو مثبّت خاص كي لا تسقط. افصل الأسطوانات الفارغة عن الممتلئة، وضع عليها علامة «فارغة» (EMPTY) أو «ممتلئة» (FULL).",critical:!0},{title:"2. الزيت والشحم: عدوّا الأكسجين",detail:"لا تترك زيتًا أو شحمًا على صمامات الأكسجين ووصلاته: فذلك يسبّب الاشتعال والانفجار. لا تلمس الصمامات بيدين عليهما كريم أو زيت. وفي غرفة العمليات، يجب أن يجفّ محلول تطهير الجلد الكحولي تمامًا قبل استخدام جهاز الكيّ.",critical:!0},{title:"3. MGPS — شبكة الغازات الطبية",detail:"لكل قسم أو طابق صمام أكسجين خاص بالمنطقة (Zone Valve Box) في الممر. ويُجرى الفحص والصيانة وفق برنامج المستشفى وNFPA 99. وفي أثناء الحريق، لا يُغلق صمام المنطقة إلا بعد تحويل المرضى الموصولين بالأكسجين إلى أسطوانة محمولة أو كيس التنفس اليدوي (bag-mask)، وبأمر من المسؤول السريري أو وفق خطة الحريق.",critical:!0},{title:"4. OEA — التعرّف عليه والحدّ منه",detail:"إذا تجاوزت نسبة الأكسجين في الغرفة 23.5%، فهذا جوّ غني بالأكسجين (OEA). وقد يتجمّع الأكسجين تحت الشراشف وبين الشعر. استخدم أدنى نسبة أكسجين لازمة، واسمح للأكسجين بالخروج من تحت الشراشف، وقلّل الأكسجين بالقرب من جهاز الكيّ والأجهزة الساخنة.",critical:!0},{title:"5. سقوط الأسطوانة وانكسار صمامها",detail:"إذا سقطت الأسطوانة وانكسر صمامها، يندفع الغاز بقوة، وقد تطير الأسطوانة كالصاروخ وتخترق الجدران. لا تحاول الإمساك بها؛ أخلِ المنطقة واحمِ نفسك. والوقاية هي أفضل وسيلة: يجب أن تكون الأسطوانات مثبّتة دائمًا، وأن يكون غطاء الحماية على الصمام في أثناء النقل."},{title:"6. ألوان الغازات الطبية (ISO 32)",detail:"O₂: أبيض. N₂O: أزرق. CO₂: رمادي. الهيليوم: بنّي. الهواء الطبي: أبيض وأسود. وتختلف الألوان في بعض الدول (في الولايات المتحدة O₂ أخضر)، ولذلك اقرأ دائمًا اسم الغاز المكتوب على الأسطوانة. لا تستخدم أسطوانة بلا اسم: فتوصيل غاز خاطئ قد يقتل المريض."}],reference:[{heading:"الأكسجين والنار: ماذا يحدث؟",points:["تحترق النار أسرع وأشدّ حرارة بكثير.","المواد التي يصعب احتراقها عادةً تشتعل بسهولة في الجو الغني بالأكسجين (OEA).","الزيت أو الشحم مع الأكسجين المضغوط يسبّب الاشتعال والانفجار.","تصبح الأقمشة والبلاستيك والشعر شديدة القابلية للاشتعال في الجو الغني بالأكسجين (OEA).","تشتعل المواد عند درجة حرارة أدنى."]},{heading:"الفحص اليومي من قِبل الكوادر",points:["الأسطوانات مثبّتة بسلسلة أو مثبّت خاص.","ضغط الغاز عند صمام المنطقة طبيعي.","علامة «ممتلئة» (FULL) أو «فارغة» (EMPTY) صحيحة.","لا يوجد زيت أو شحم بالقرب منها.","أجهزة إنذار الغاز تعمل."]},{heading:"في أثناء الحريق في غرفة العمليات أو ICU",points:["أولًا: أنقذ المرضى المعرّضين للخطر؛ وصِل المرضى على أجهزة التنفس الاصطناعي بكيس التنفس اليدوي (bag-mask) أو أكسجين محمول.","ثانيًا: انقل المرضى إلى قسم آمن.","ثالثًا: لا تغلق صمام المنطقة إلا بعد ذلك وبأمر من المسؤول السريري أو وفق خطة الحريق.","تُجهَّز أسطوانات احتياطية ممتلئة لكل مريض يحتاج إلى الأكسجين.","تواصل مستمر بين طبيب التخدير والجرّاح والممرضين."]}],warnings:["لا تترك زيتًا أو شحمًا بالقرب من الأكسجين، بما في ذلك كريمات اليدين ومستحضرات الجلد الزيتية. وفي غرفة العمليات، يجب أن يجفّ محلول التطهير الكحولي تمامًا قبل استخدام جهاز الكيّ؛ ففي حالة ChloraPrep لا يقلّ ذلك عن 3 دقائق على الجلد الخالي من الشعر، ويصل إلى ساعة واحدة في المناطق المشعرة. لا تغلق صمام الأكسجين الخاص بالمنطقة قبل نقل المرضى الموصولين بالأكسجين."],realCase:"حالة عملية (مثال تعليمي): كان أحد عمّال المخزن ينقل أسطوانة أكسجين ممتلئة من دون عربة ومن دون غطاء الحماية. فسقطت الأسطوانة عند الباب وانكسر صمامها. واندفع الغاز بضغط مرتفع فطارت الأسطوانة كالصاروخ في الممر واصطدمت بالجدار وأُصيب عدد من العاملين. ولو نُقلت الأسطوانة بعربة مخصّصة ومع غطاء الحماية، لما وقع هذا الحادث.",caseStudy:[{prompt:"أنتِ ممرضة غرفة العمليات. المريض يتلقّى أكسجينًا بتركيز 100%. تلاحظين أنّ محلول التطهير الكحولي ما زال رطبًا على جلد المريض، والجرّاح يقول: «جهّزوا جهاز الكيّ». ماذا تفعلين؟",options:[{text:"أنبّه الجرّاح فورًا وأطلب الانتظار حتى يجفّ المحلول تمامًا (3 دقائق على الأقل في حالة ChloraPrep)",correct:!0,feedback:"صحيح: الكحول وجهاز الكيّ والأكسجين معًا = خطر حريق سريع. ارفعي صوتكِ (Speak Up)."},{text:"أكتفي بخفض الأكسجين إلى 40%",correct:!1,feedback:"هذا وحده لا يكفي: فالمحلول الرطب ما زال قابلًا للاشتعال، ونسبة 40% ما زالت ضمن الجو الغني بالأكسجين (OEA)."},{text:"أوجّه عليه الهواء بمروحة كي يجفّ بسرعة",correct:!1,feedback:"خطير: فالهواء المتحرّك ينشر الأكسجين؛ انتظري الجفاف الطبيعي."},{text:"لا أفعل شيئًا؛ فهذا ليس من عملي",correct:!1,feedback:"سلامة المريض مسؤولية الفريق كله. ارفعي صوتكِ (Speak Up)!"}]},{prompt:"وافق الجرّاح، وبدأ الجراحة بعد الجفاف التام. وبعد مدة، تظهر شعلة صغيرة على صدر المريض. ما الخطوة الأولى؟",options:[{text:"آخذ مطفأة CO₂",correct:!1,feedback:"قبل المطفأة، يجب إيقاف تدفّق الأكسجين إلى المريض."},{text:"أنبّه طبيب التخدير ليوقف تدفّق O₂ إلى المريض، وأزيل الشراشف المشتعلة",correct:!0,feedback:"صحيح: طبيب التخدير هو من يتحكّم في غازات المريض. ويأتي إيقاف الغاز وإزالة المواد المشتعلة قبل المطفأة."},{text:"أستدعي ممرضة أخرى",correct:!1,feedback:"الوقت ضيّق؛ وطبيب التخدير موجود في الغرفة ويستطيع إيقاف الغاز فورًا."},{text:"أُخلي غرفة العمليات",correct:!1,feedback:"المريض على الطاولة؛ أوقفي الأكسجين أولًا ثم أطفئي النار."}]},{prompt:"أُوقف O₂ وصُبّ المحلول الملحي، لكنّ النار ما زالت مستمرة. أيّ مطفأة مناسبة في غرفة العمليات؟",options:[{text:"مطفأة ABC المسحوقية",correct:!1,feedback:"المسحوق يلوّث الجرح والمجرى التنفسي للمريض ويُتلف الأجهزة."},{text:"مطفأة CO₂",correct:!0,feedback:"صحيح: توصي ASA وECRI بمطفأة CO₂ لغرفة العمليات."},{text:"الماء على الأجهزة الكهربائية",correct:!1,feedback:"خطير: فالأجهزة موصولة بالكهرباء."},{text:"أنتظر فريق الإطفاء ولا أفعل شيئًا",correct:!1,feedback:"النار على المريض والوقت ضيّق جدًا. استخدمي CO₂ وأعلني Code Red."}]}],quiz:[{question:"ماذا يفعل الأكسجين بالنار؟",options:[{text:"يُطفئ النار",correct:!1,feedback:"العكس صحيح: فالأكسجين لا يحترق بذاته، لكنه يجعل النار أقوى وأسرع بكثير."},{text:"يجعل النار أقوى وأسرع بكثير",correct:!0,feedback:"صحيح: الأكسجين مادة مؤكسِدة (oxidizer)."},{text:"ليس له أيّ تأثير، لأن الأكسجين لا يحترق بذاته",correct:!1,feedback:"له تأثير كبير."},{text:"يبرّد النار ويُبطئ انتشارها",correct:!1,feedback:"العكس صحيح: فمع زيادة الأكسجين تشتدّ النار حرارةً وسرعةً، وتشتعل المواد عند درجة حرارة أدنى."}],explanation:"لا يحترق الأكسجين بذاته، لكنه بوصفه مادة مؤكسِدة يجعل النار أقوى وأسرع بكثير، ويتيح للمواد أن تشتعل عند درجة حرارة أدنى."},{question:"ماذا يحدث إذا سقطت أسطوانة الأكسجين وانكسر صمامها؟",options:[{text:"مشكلة بسيطة",correct:!1,feedback:"غير صحيح؛ إنه خطر قاتل."},{text:"قد تطير الأسطوانة كالصاروخ وتقتل أشخاصًا",correct:!0,feedback:"صحيح: ولذلك يجب أن تكون الأسطوانات مثبّتة وعليها غطاء الحماية."},{text:"ينخفض الضغط تلقائيًا ولا يوجد خطر",correct:!1,feedback:"غير صحيح؛ فالضغط المرتفع يولّد قوة هائلة."},{text:"يكفي فتح النافذة فقط",correct:!1,feedback:"هذا لا يكفي؛ أخلِ المنطقة."}]},{question:"ماذا يُحدث الزيت أو الشحم مع الأكسجين المضغوط؟",options:[{text:"ليس له أي تأثير",correct:!1,feedback:"غير صحيح؛ هناك خطر الاشتعال والانفجار."},{text:"الاشتعال أو الانفجار",correct:!0,feedback:"صحيح: قد يشتعل الزيت تلقائيًا بالقرب من الأكسجين المضغوط."},{text:"يجفّ الزيت",correct:!1,feedback:"لا يجفّ الزيت أو الشحم قرب الأكسجين المضغوط، بل قد يشتعل وينفجر."},{text:"يتغيّر لون الأسطوانة",correct:!1,feedback:"المسألة ليست في اللون: فتماسّ الزيت أو الشحم مع الأكسجين المضغوط يسبّب الاشتعال والانفجار."}],explanation:"قد يشتعل الزيت أو الشحم وينفجر عند تماسّه مع الأكسجين المضغوط، لذا أبقِ الصمامات والوصلات خالية من الزيت والشحم وكريمات اليدين."},{question:"ما حدّ الجو الغني بالأكسجين (OEA) وفق NFPA 99؟",options:[{text:"O₂ أكثر من 21%",correct:!1,feedback:"يحتوي الهواء العادي على نحو 20.9% من الأكسجين."},{text:"O₂ أكثر من 23.5%",correct:!0,feedback:"صحيح: الجو الغني بالأكسجين (Oxygen-Enriched Atmosphere)."},{text:"O₂ أكثر من 50%",correct:!1,feedback:"غير صحيح؛ يبدأ OEA قبل 50% بكثير."},{text:"O₂ أقل من 19.5%",correct:!1,feedback:"هذا نقص في الأكسجين (oxygen deficiency)، لا OEA."}]},{question:"تسقط أسطوانة أكسجين ممتلئة في الممر وينكسر صمامها، والغاز يندفع بصوت عالٍ. ماذا تفعل؟",options:[{text:"لا أحاول الإمساك بها: أُخلي المنطقة وأحمي نفسي وأُبلغ عنها",correct:!0},{text:"أمسك الأسطوانة وأثبّتها على الأرض حتى ينفد الغاز",correct:!1},{text:"أحاول إعادة تركيب الصمام المكسور بأسرع ما يمكن",correct:!1},{text:"أُعيد الأسطوانة إلى وضعها القائم وأربطها بالجدار بالسلسلة",correct:!1}],explanation:"الأسطوانة ذات الصمام المكسور قد تطير كالصاروخ وتخترق الجدران. لا تقترب منها: أخلِ المنطقة، واحمِ نفسك، وأبلغ وفق خطة مستشفاك."},{question:"يحتاج مريض إلى الأكسجين الآن. في المخزن تجد أسطوانة عليها ملصق «أكسجين» وأسطوانة بيضاء بلا ملصق. أيّهما تأخذ؟",options:[{text:"الأسطوانة التي عليها ملصق الأكسجين؛ فالأسطوانة بلا ملصق لا تُستخدم أبدًا",correct:!0},{text:"البيضاء، لأن اللون الأبيض يعني الأكسجين وفق ISO 32",correct:!1},{text:"الأكثر امتلاءً، بعد أن أفحص مقياسي الضغط في كلتيهما",correct:!1},{text:"التي بلا ملصق، بعد أن أشمّ الغاز قليلًا للتحقّق منه",correct:!1}],explanation:"تختلف الألوان من بلد إلى آخر وقد تكون خاطئة، فاقرأ دائمًا اسم الغاز على الملصق. وتوصيل غاز خاطئ قد يقتل المريض."}],tips:["لا تترك أسطوانة الأكسجين واقفة دون تثبيت ولو للحظة: ثبّتها بالسلسلة، أو ضعها في حاملها، أو أبقِها على عربتها.","اطلب من المرضى الموصولين بالأكسجين وزوّارهم عدم التدخين أو استخدام الولّاعات، وعدم وضع كريمات زيتية على اليدين أو الوجه بالقرب من الأكسجين.","اقرأ دائمًا اسم الغاز على ملصق الأسطوانة قبل توصيلها، ولا تعتمد على اللون.","أغلق صمام الأسطوانة عندما لا يكون الأكسجين قيد الاستخدام، وأبلغ المسؤول فورًا عن أي صوت فحيح (hissing) أو رائحة احتراق قرب أجهزة الأكسجين."],activity:{prompt:"أنت عامل نقل المرضى (porter) وتنقل مريضًا موصولًا بالأكسجين إلى قسم الأشعة (X-Ray). الأسطوانة ملقاة دون تثبيت على السرير بجانب ساقي المريض، وأحد أقاربه دهن يديه للتوّ بكريم لليدين. ماذا تفعل؟",options:[{text:"أثبّت الأسطوانة في حاملها أو على عربة قبل النقل، وأطلب مسح الكريم قبل أن يلمس أحد وصلات الأكسجين",correct:!0,feedback:"صحيح: الأسطوانة غير المثبّتة قد تسقط وينكسر صمامها، والزيت أو الشحم قرب وصلات الأكسجين قد يسبّب الاشتعال. وأبقِ الأكسجين مستمرًا كما وصفه الطبيب."},{text:"أحمل الأسطوانة على كتفي كي لا تتدحرج على السرير",correct:!1,feedback:"لا تُحمل الأسطوانة باليد أو على الكتف أبدًا: انقلها بعربة مخصّصة أو في حاملها."},{text:"أترك كل شيء على حاله، لأن الطريق إلى الأشعة قصير",correct:!1,feedback:"قد تسقط الأسطوانة غير المثبّتة في الطريق وينكسر صمامها، ويبقى الكريم قرب الأكسجين. وقِصر الطريق لا يزيل الخطر."},{text:"أوقف الأكسجين طوال الطريق كي تكون الأسطوانة آمنة",correct:!1,feedback:"لا يُوقف الأكسجين الذي وصفه الطبيب دون أمر سريري، فقد يتضرّر المريض. بدلًا من ذلك، ثبّت الأسطوانة."}]}},{id:6,code:"OR-06",icon:"Stethoscope",accent:"#7c3aed",category:"السلامة",title:"السلامة من الحريق في غرفة العمليات (OR)",subtitle:"مثلث النار في غرفة العمليات ووقفة التحقّق (Time-Out) الخاصة بالحريق",summary:"غرفة العمليات (OR) من أخطر أماكن الحريق في المستشفى، لأنّ أضلاع مثلث النار الثلاثة تجتمع فيها: 1) الأكسجين أو N₂O، 2) المواد القابلة للاحتراق (المحلول الكحولي، والشراشف، والشعر)، 3) مصادر الاشتعال (جهاز الكيّ، والليزر، والمثقاب). وتقع حرائق العمليات أكثر ما تقع في جراحات الرأس والعنق والصدر. ووفق إرشادات AORN وASA، يجب تقييم خطر الحريق قبل كل عملية جراحية.",facts:[{label:"مثلث النار",value:"الأكسجين + المادة القابلة للاحتراق + مصدر الاشتعال"},{label:"الأكسجين المفتوح قرب الرأس",value:"30% أو أقل إذا كان المريض يتحمّل ذلك (APSF)"},{label:"الجراحات عالية الخطورة",value:"الرأس، العنق، الصدر"},{label:"المعيار",value:"AORN + ASA + ECRI"}],steps:[{title:"1. وقفة التحقّق (Time-Out) الخاصة بالحريق قبل الجراحة",detail:"قبل البدء، يطرح الفريق ثلاثة أسئلة: 1) ما مقدار الأكسجين أو N₂O، وهل هو قريب من موضع الجراحة؟ 2) ما مصدر الاشتعال؟ 3) أين توجد المواد القابلة للاحتراق (الكحول، الشراشف)؟ فإذا اجتمعت العناصر الثلاثة، كانت العملية عالية الخطورة وتحتاج إلى خطة خاصة.",critical:!0},{title:"2. تجفيف المحلول الكحولي",detail:"قبل استخدام جهاز الكيّ، يجب أن يجفّ محلول تطهير الجلد الكحولي تمامًا وفق تعليمات الشركة المصنّعة: ففي حالة ChloraPrep لا يقلّ ذلك عن 3 دقائق على الجلد الخالي من الشعر، ويصل إلى ساعة واحدة في المناطق المشعرة. لا تدع المحلول يتجمّع تحت المريض أو بين الشراشف.",critical:!0},{title:"3. التحكّم في الأكسجين",detail:"في جراحات الرأس والعنق، يجب أن يكون الأكسجين المفتوح (بالقناع أو القنية الأنفية) 30% أو أقل إذا كان المريض يتحمّل ذلك. وإذا احتاج المريض إلى أكسجين أعلى، فأمِّن المجرى الهوائي بأنبوب رغامي (ETT) أو قناع حنجري (LMA). وقبل استخدام مصدر الاشتعال قرب المجرى الهوائي، اخفض الأكسجين أو أوقفه وانتظر نحو دقيقة واحدة.",critical:!0},{title:"4. التحكّم في مصادر الاشتعال",detail:"عندما لا يكون جهاز الكيّ قيد الاستخدام، أبقِه في حافظته الواقية (holster)، لا على الشراشف. الليزر: نبّه الفريق قبل استخدامه وأبعد المواد القابلة للاحتراق. لا تترك طرف كابل الضوء (fiber-optic) على الشراشف وهو مشغَّل. ولا تضع الأجهزة الساخنة على المواد القابلة للاحتراق.",critical:!0},{title:"5. إذا اندلع حريق على جسم المريض",detail:"1. توقّف (Stop): أوقف الجراحة وأطلق التنبيه. 2. يوقف طبيب التخدير تدفّق O₂ وN₂O. 3. أزِل الشراشف والمواد المشتعلة، وأطفئ النار بالمحلول الملحي (saline). 4. إذا استمرت النار: مطفأة CO₂. 5. إذا لم تنطفئ: Code Red وإخراج المريض.",critical:!0},{title:"6. حريق المجرى الهوائي (Airway Fire)",detail:"حريق داخل الأنبوب الرغامي (ETT). وفي الوقت نفسه: 1) أوقف تدفّق جميع الغازات وافصل الدارة (circuit)، 2) انزع الأنبوب، 3) اسكب المحلول الملحي في المجرى الهوائي. ثم: 4) أعطِ التهوية بالقناع، ولا تستخدم أكسجينًا إضافيًا حتى تتأكد من عدم بقاء أي نار، 5) افحص المجرى الهوائي بتنظير القصبات (bronchoscopy)."}],reference:[{heading:"مثلث النار في OR",points:["المادة المؤكسِدة: O₂ (ولا سيما في OEA) أو N₂O.","المادة القابلة للاحتراق: الكحول، وChloraPrep، والشراشف، والشاش (gauze)، وشعر المريض.","مصدر الاشتعال: جهاز الكيّ، والليزر، والمثقاب، وكابل الضوء.","إذا غاب أحد الأضلاع الثلاثة، لا يندلع الحريق."]},{heading:"الجراحات عالية الخطورة",points:["فتح القصبة الهوائية (Tracheostomy): أكسجين + أنبوب رغامي (ETT) + جهاز الكيّ.","جراحة العيون بالتخدير الموضعي والأكسجين المفتوح.","ENT (الرأس والعنق): الأكسجين قريب جدًا من موضع العمل.","جراحة الفم: الأكسجين داخل الفم.","الجراحة التجميلية للرأس والوجه: ChloraPrep + جهاز الكيّ."]},{heading:"وقفة التحقّق (Time-Out) الخاصة بالحريق (وفق AORN)",points:["الجرّاح: «ما مقدار الأكسجين؟ وما مصدر الاشتعال؟»","طبيب التخدير: «الأكسجين 21%؛ وأنا مستعد لإيقافه.»","الممرض: «جفّ محلول التطهير تمامًا.»","دوّن النتيجة على لوحة غرفة العمليات.","كرّرها لكل عملية جراحية، لا مرة واحدة فقط."]}],warnings:["وقفة التحقّق (Time-Out) الخاصة بالحريق مسؤولية الفريق كله: الجرّاح وطبيب التخدير والممرض. فإذا لم يكن أحدهم مطمئنًا، لا تبدأ الجراحة حتى يُعالَج الخطر. وفي حريق المجرى الهوائي، يأتي أولًا إيقاف الغازات ونزع الأنبوب الرغامي (ETT)، لا المطفأة."],realCase:"حالة عملية (مثال تعليمي): في عملية استئصال اللوزتين (tonsillectomy) لطفل عمره 7 سنوات، لم يُخفَّض الأكسجين بتركيز 100% قبل استخدام جهاز الكيّ. فأشعل جهاز الكيّ النار قرب المجرى الهوائي واشتعل الأنبوب الرغامي (ETT)، فحدث حريق في المجرى الهوائي (Airway Fire). ولم يوقف الفريق الغازات ولم ينزع الأنبوب، بل أحضر بدلًا من ذلك مطفأة ABC. فأُصيب الطفل بحروق شديدة في المجرى الهوائي والفم. والإجراء الصحيح: إيقاف الغازات ونزع الأنبوب وسكب المحلول الملحي في الوقت نفسه. الدرس المستفاد: خفض الأكسجين قبل استخدام جهاز الكيّ، والتدريب المستمر على بروتوكول حريق المجرى الهوائي.",caseStudy:[{prompt:"أنتِ ممرضة غرفة العمليات. ستبدأ عملية أنف وأذن وحنجرة (ENT) لطفل عمره 6 سنوات. يقول الجرّاح: «لا حاجة إلى وقفة التحقّق (Time-Out) الخاصة بالحريق؛ فهذه عملية روتينية.» ماذا تفعلين؟",options:[{text:"أوافق؛ فالجرّاح خبير",correct:!1,feedback:"غير صحيح: وقفة التحقّق (Time-Out) ضرورية (AORN)، وأنتِ أيضًا مسؤولة عن سلامة المريض."},{text:"أقول باحترام: «وفق الأهداف الوطنية لسلامة المرضى (NPSG)، وقفة التحقّق (Time-Out) ضرورية؛ ولا تستغرق سوى بضع ثوانٍ.»",correct:!0,feedback:"صحيح: ارفعي صوتكِ (Speak Up). فعمليات الأنف والأذن والحنجرة (ENT) التي يُستخدم فيها الأكسجين وجهاز الكيّ عالية الخطورة."},{text:"أذهب فورًا إلى مشرفة التمريض من دون إبلاغ الجرّاح",correct:!1,feedback:"قد يلزم ذلك لاحقًا، لكن تحدّثي أولًا مع الجرّاح مباشرة."},{text:"لا أقول شيئًا وأقوم بعملي",correct:!1,feedback:"الصمت يعرّض المريض للخطر؛ ورفع الصوت (Speak Up) ضروري."}]},{prompt:"أُجريت وقفة التحقّق (Time-Out). وخُفّض الأكسجين إلى 30% ووُضع ChloraPrep. وبعد 30 ثانية يقول الجرّاح: «جهّزوا جهاز الكيّ.» والمحلول ما زال رطبًا. ماذا تفعلين؟",options:[{text:"أوافق لأنّ العمل كثير",correct:!1,feedback:"هناك خطر حريق: يحتاج ChloraPrep إلى 3 دقائق على الأقل ليجفّ تمامًا."},{text:"أطلب الانتظار حتى يجفّ المحلول تمامًا (3 دقائق على الأقل وفق تعليمات الشركة المصنّعة)",correct:!0,feedback:"صحيح: المحلول الكحولي الرطب مادة قابلة للاحتراق."},{text:"أضع مروحة كي يجفّ بسرعة",correct:!1,feedback:"خطير: فالهواء المتحرّك ينشر الأكسجين."},{text:"أعمل بسرعة ولا أنتظر",correct:!1,feedback:"هناك خطر حريق."}]},{prompt:"بدأت الجراحة. وبعد 20 دقيقة تظهر نار داخل الأنبوب الرغامي (ETT). ما الخطوة الأولى؟",options:[{text:"آخذ المطفأة",correct:!1,feedback:"قبل استخدام المطفأة، يجب إيقاف الغازات ونزع الأنبوب الرغامي (ETT)."},{text:"نوقف تدفّق الغازات وننزع الأنبوب الرغامي (ETT) في الوقت نفسه، ثم نسكب المحلول الملحي في المجرى الهوائي",correct:!0,feedback:"صحيح: بروتوكول حريق المجرى الهوائي (ASA)."},{text:"أكتفي بخفض الأكسجين",correct:!1,feedback:"هذا لا يكفي؛ يجب إيقاف الغازات تمامًا ونزع الأنبوب الرغامي (ETT)."},{text:"أنتظر فريق Code Red",correct:!1,feedback:"لا وقت لذلك؛ يجب أن يتصرّف فريق غرفة العمليات فورًا."}]}],quiz:[{question:"من أيّ عناصر ثلاثة يتكوّن مثلث النار في غرفة العمليات؟",options:[{text:"الحرارة، الكحول، النار",correct:!1,feedback:"غير صحيح؛ فالنار نتيجة، وليست ضلعًا من أضلاع المثلث."},{text:"الأكسجين، المواد القابلة للاحتراق، مصدر الاشتعال",correct:!0,feedback:"صحيح: المادة المؤكسِدة (Oxidizer) + المادة القابلة للاحتراق (Fuel) + مصدر الاشتعال (Ignition)."},{text:"الماء، الغازات الطبية، التيار الكهربائي للأجهزة",correct:!1,feedback:"ليست هذه أضلاع المثلث الثلاثة؛ ففي غرفة العمليات هي المادة المؤكسِدة والمواد القابلة للاحتراق ومصدر الاشتعال."},{text:"الطبيب، الممرض، الجهاز",correct:!1,feedback:"هؤلاء هم الفريق لا أضلاع المثلث، لكن وقفة التحقّق (Time-Out) الخاصة بالحريق مسؤولية الفريق كله."}],explanation:"في غرفة العمليات تحتاج النار إلى مادة مؤكسِدة (O₂ أو N₂O)، ومادة قابلة للاحتراق (محلول التطهير، الشراشف، الشعر)، ومصدر اشتعال (جهاز الكيّ، الليزر)؛ وإذا غاب أحد الأضلاع الثلاثة لم تنشأ النار."},{question:"كم يحتاج ChloraPrep من الوقت ليجفّ قبل استخدام جهاز الكيّ؟",options:[{text:"30 ثانية على أيّ جلد، ثم يمكن بدء استخدام جهاز الكيّ",correct:!1,feedback:"هذا قليل جدًا."},{text:"3 دقائق على الأقل على جلد بلا شعر (وحتى ساعة في المناطق المشعرة)",correct:!0,feedback:"صحيح: وفق تعليمات الشركة المصنّعة (ChloraPrep IFU)."},{text:"لا حاجة إلى التجفيف إذا خُفّض الأكسجين إلى أقل من 30%",correct:!1,feedback:"غير صحيح: المحلول الرطب قابل للاحتراق دائمًا."},{text:"لا حاجة إلى الانتظار",correct:!1,feedback:"المحلول الكحولي الرطب مادة قابلة للاحتراق؛ انتظر حتى يجفّ تمامًا قبل استخدام جهاز الكيّ."}],explanation:"يبقى المحلول الكحولي مادة قابلة للاحتراق حتى يجفّ تمامًا. وفي حالة ChloraPrep تشترط الشركة المصنّعة 3 دقائق على الأقل على الجلد الخالي من الشعر، وحتى ساعة واحدة في المناطق المشعرة، قبل استخدام جهاز الكيّ."},{question:"ما الخطوة الأولى في حريق المجرى الهوائي؟",options:[{text:"مطفأة العامل النظيف (Clean Agent) أولًا، ثم إيقاف الغازات",correct:!1,feedback:"لاحقًا، عند الحاجة."},{text:"إيقاف الغازات، وفصل الدارة (circuit)، ونزع ETT",correct:!0,feedback:"صحيح: بروتوكول حريق المجرى الهوائي."},{text:"الاكتفاء بخفض FiO₂ ومواصلة العملية",correct:!1,feedback:"هذا قليل جدًا."},{text:"البدء بـ CPR",correct:!1,feedback:"لا يوقف CPR حريق المجرى الهوائي؛ أوقف الغازات، وافصل الدارة، وانزع الأنبوب الرغامي (ETT)، واسكب المحلول الملحي."}],explanation:"في حريق المجرى الهوائي، أوقف في الوقت نفسه تدفّق جميع الغازات وافصل الدارة (circuit)، وانزع الأنبوب الرغامي (ETT)، واسكب المحلول الملحي في المجرى الهوائي؛ فالمطفأة ليست الخطوة الأولى."},{question:"أيّ عملية جراحية خطر الحريق فيها مرتفع؟",options:[{text:"استئصال الزائدة الدودية (Appendectomy) وعمليات البطن الأخرى",correct:!1,feedback:"خطرها أقل."},{text:"فتح القصبة الهوائية (Tracheostomy) وعمليات الأنف والأذن والحنجرة (ENT)",correct:!0,feedback:"صحيح: الأكسجين وجهاز الكيّ قرب المجرى الهوائي."},{text:"إصلاح الفتق (Hernia repair)",correct:!1,feedback:"خطرها أقل."},{text:"العملية القيصرية (C-section) تحت التخدير النصفي (spinal)",correct:!1,feedback:"خطرها أقل."}]},{question:"تظهر ألسنة لهب على الشراشف في أثناء جراحة في العنق. ما الترتيب الصحيح؟",options:[{text:"التوقّف والتنبيه، ثم إيقاف الغازات، ثم إزالة الشراشف، ثم المحلول الملحي، ثم CO₂ عند الحاجة",correct:!0},{text:"مطفأة CO₂ أولًا، ثم إيقاف الغازات، ثم إبلاغ الفريق بوجود الحريق",correct:!1},{text:"إخراج المريض من الغرفة أولًا، ثم إيقاف الغازات والجراحة",correct:!1},{text:"زيادة التهوية بالأكسجين، ثم سكب المحلول الملحي على الشراشف المشتعلة",correct:!1}],explanation:"في الحريق على جسم المريض: أوقف الجراحة وأطلق التنبيه، ويوقف طبيب التخدير O₂ وN₂O، وأزِل الشراشف والمواد المشتعلة واستخدم المحلول الملحي، ثم مطفأة CO₂ إذا استمرت النار، وCode Red إذا لم تنطفئ."},{question:"سيستخدم الجرّاح جهاز الكيّ قرب المجرى الهوائي في جراحة للرأس والعنق. أيّ إجراء يُزيل ضلعًا من مثلث الحريق؟",options:[{text:"خفض الأكسجين المفتوح أو إيقافه والانتظار قبل الاستخدام",correct:!0},{text:"رفع تبريد الغرفة لتبريد موضع الجراحة",correct:!1},{text:"وضع كمية أكبر من المحلول الكحولي كي يُطهَّر الجلد أفضل",correct:!1},{text:"وضع رأس جهاز الكيّ النشط على الشراشف بين مرات الاستخدام",correct:!1}],explanation:"يحتاج مثلث الحريق إلى الأكسجين والوقود ومصدر الاشتعال. وخفض الأكسجين أو إيقافه والانتظار قبل استخدام مصدر الاشتعال قرب المجرى الهوائي يُزيل ضلع المادة المؤكسِدة."}],tips:["لا تصمت في وقفة التحقّق (Time-Out) الخاصة بالحريق: يحقّ لأي عضو في الفريق إيقاف بدء الجراحة حتى يُعالَج الخطر.","أبقِ جهاز الكيّ في حافظته الواقية (holster) كلما لم يكن قيد الاستخدام، لا على الشراشف.","قبل كل جراحة عالية الخطورة، اعرف مكان المحلول الملحي (saline) ومطفأة CO₂، واجعلهما جاهزين.","رتّب الشراشف بحيث يتمكّن الأكسجين من التسرّب ولا يتجمّع تحتها قرب موضع الجراحة."],activity:{prompt:"أنت ممرض التعقيم (scrub nurse) في جراحة عين تحت التخدير الموضعي. يتلقّى المريض الأكسجين بقناع وجه مفتوح تحت الشراشف. ويطلب الجرّاح استخدام جهاز الكيّ قرب الوجه. ماذا تفعل؟",options:[{text:"أتكلّم وأطلب من طبيب التخدير خفض الأكسجين المفتوح أو إيقافه والانتظار قبل استخدام جهاز الكيّ",correct:!0,feedback:"صحيح: الأكسجين والشراشف وجهاز الكيّ تُكمل مثلث الحريق. وخفض الأكسجين أو إيقافه والانتظار قبل استخدام الكيّ قرب المجرى الهوائي يُزيل أحد أضلاع المثلث."},{text:"لا أقول شيئًا، لأن الأكسجين تحت الشراشف وبعيد عن جهاز الكيّ",correct:!1,feedback:"يتجمّع الأكسجين تحت الشراشف ويُنشئ جوًا غنيًا بالأكسجين (OEA) عند موضع الجراحة. وعلى كل عضو في الفريق أن يتكلّم."},{text:"أطلب زيادة الأكسجين كي يبقى المريض مرتاحًا في أثناء الكيّ",correct:!1,feedback:"زيادة الأكسجين تجعل أي حريق أقوى وأسرع. استخدم أقل كمية أكسجين يحتاج إليها المريض."},{text:"أسكب المحلول الملحي على الشراشف مسبقًا كي لا تشتعل",correct:!1,feedback:"الشراشف المبلّلة لا تُزيل الأكسجين ولا مصدر الاشتعال، وقد يتجمّع السائل تحت المريض. تحكّم بدلًا من ذلك في الأكسجين وجهاز الكيّ."}]}},{id:7,code:"EVAC-07",icon:"DoorOpen",accent:"#9333ea",category:"الطوارئ",title:"إخلاء المستشفى — RACE",subtitle:"خطة الإخلاء للمرضى غير القادرين على الهرب بأنفسهم",summary:"يختلف إخلاء المستشفى عن إخلاء المباني الأخرى: فالمرضى على أجهزة التنفس الاصطناعي وفي NICU وICU لا يستطيعون الخروج فورًا. ووفق NFPA 101 (كود سلامة الأرواح)، يعمل المستشفى على ثلاثة مستويات: 1) الحماية في المكان (Defend in Place)، 2) الإخلاء الأفقي إلى قسم مانع للدخان في الطابق نفسه، 3) الإخلاء العمودي إلى طابق أدنى. والإخلاء الكامل للمبنى هو الملاذ الأخير.",facts:[{label:"المستوى 1 — الحماية في المكان",value:"أغلق الأبواب وكن على أهبة الاستعداد"},{label:"المستوى 2 — الإخلاء الأفقي",value:"إلى قسم آمن في الطابق نفسه"},{label:"المستوى 3 — الإخلاء العمودي",value:"إلى طابق أدنى"},{label:"الإخلاء الكامل",value:"الملاذ الأخير (Last Resort)"}],steps:[{title:"R — Rescue (إنقاذ المرضى)",detail:"انقل أولًا المرضى القريبين من النار والدخان إلى قسم آمن. ثم وفق الخطة: المرضى القادرون على المشي، ثم من هم على الكراسي المتحرّكة، ثم من هم على الأسرّة، وأخيرًا مرضى ICU والمرضى على أجهزة التنفس الاصطناعي، لأنّ نقلهم يحتاج إلى فريق وتحضير. لا تترك المريض وحده.",critical:!0},{title:"A — Alarm (الإنذار)",detail:"اضغط جهاز إنذار الحريق واتصل برقم الطوارئ الداخلي؛ ويُبلغ المستشفى الدفاع المدني (115). ويُعلَن Code Red عبر نظام النداء العام (Public Address)، ويُفعَّل نظام قيادة الحوادث (ICS) ويُبلَّغ جميع العاملين.",critical:!0},{title:"C — Contain (الاحتواء)",detail:"أغلق أبواب الغرف وأبواب الأقسام المانعة للدخان (Smoke Compartment Doors). ولا يُغلق صمام الأكسجين الخاص بالمنطقة إلا بعد تحويل المرضى الموصولين بالأكسجين إلى أسطوانة محمولة أو كيس التنفس اليدوي (bag-mask)، وبأمر من المسؤول. ويتحكّم فريق الهندسة في نظام التهوية (HVAC) وفق خطة الحريق.",critical:!0},{title:"E — Extinguish أو Evacuate (الإطفاء أو الإخلاء)",detail:"إذا كان الحريق صغيرًا (لا يتجاوز حجم سلة المهملات)، وكنت مدرَّبًا، وتمّ إطلاق الإنذار، وكان طريق الخروج خلفك: المطفأة المناسبة؛ وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. وإذا كان كبيرًا: الإخلاء الأفقي. فكل طابق مقسّم بأبواب مانعة للدخان إلى قسمين أو أكثر (Smoke Compartments)؛ وينتقل المرضى من قسم الحريق إلى القسم الآمن."},{title:"الإخلاء الأفقي — ثلاث طرق",detail:`السحب بالشرشف (Sheet Drag): للمريض الراقد على السرير، ويسحبه شخصان.
• الكرسي المتحرّك (Wheelchair): للمرضى غير القادرين على المشي لمسافة طويلة.
• نقل السرير: شخصان، تُفكّ مكابح العجلات، واحد في الأمام وآخر في الخلف.`,critical:!0},{title:"الإخلاء العمودي — أربع طرق",detail:`الحمل على الذراعين (Cradle Carry): للأطفال والرضّع.
• مقعد الشخصين (Two-Person Seat): للمريض الواعي غير القادر على المشي.
• كرسي الدرج (Stair Chair): للمرضى طريحي الفراش، ويحمله شخصان.
• مزلّجة الإخلاء (Evac Sled): لمرضى ICU والمرضى على أجهزة التنفس الاصطناعي، وتحتاج إلى 3–4 أشخاص.`}],reference:[{heading:"ترتيب الإخلاء",points:["1. كل شخص معرّض لخطر مباشر (قريب من النار والدخان).","2. المرضى القادرون على المشي، مع الإرشاد.","3. المرضى على الكراسي المتحرّكة.","4. المرضى طريحو الفراش: بالشرشف أو بالسرير.","5. ICU وأجهزة التنفس الاصطناعي: كيس التنفس اليدوي (bag-mask) و3 أشخاص أو أكثر.","6. رضّع NICU: عدة رضّع معًا في مهد واحد أو عربة واحدة."]},{heading:"ما لا يجوز فعله",points:["لا تستخدم المصعد؛ فقد يتوقف.","لا تنقل المرضى ذوي الحالات الحرجة من دون خطة ومن دون معدات.","لا تترك المريض وحده.","لا تفتح النوافذ من دون سبب.","لا تحمل الأغراض الشخصية والثمينة.","لا تعُد إلى قسم الحريق."]},{heading:"الأقسام المانعة للدخان (Smoke Compartments)",points:["كل طابق مقسّم بجدران وأبواب مانعة للدخان إلى قسمين أو أكثر (NFPA 101).","تُغلق الأبواب المانعة للدخان تلقائيًا عند انطلاق إنذار الحريق.","مساحة كل قسم محدودة وفق NFPA 101.","أحد القسمين هو قسم الحريق، والآخر هو القسم الآمن.","يتّجه الإخلاء الأفقي نحو القسم الآمن."]}],warnings:["لا تستخدم المصعد في أثناء الحريق: فقد يتوقف ويُحتجز الأشخاص بداخله. ولا يُلجأ إلى الإخلاء العمودي إلا عندما لا يكفي الإخلاء الأفقي. لا تعُد إلى قسم الحريق من دون إذن فريق 115 وقائد الحادث."],realCase:"حالة عملية (مثال تعليمي): اندلع حريق في مخزن بالطابق الأول من أحد المستشفيات. وكان هناك 140 مريضًا موزّعين على أربعة طوابق. فُعِّل نظام قيادة الحوادث (ICS) بسرعة. ونُقل معظم المرضى أفقيًا إلى أقسام آمنة في الطابق نفسه، ولم يُنقل عموديًا إلا المرضى القريبون من المخزن. ونُقل أربعة مرضى من ICU على أجهزة التنفس الاصطناعي بكيس التنفس اليدوي (bag-mask) وثلاثة أشخاص لكل مريض. ولم يمت أحد. وكان وراء النجاح سببان: التدريب المستمر على ICS، والأبواب المانعة للدخان التي كانت تعمل جيدًا.",caseStudy:[{prompt:"أنت ممرض في الطابق الثالث في ICU. أُعلن Code Red في غرفة مخزن في نهاية ممر الطابق نفسه. لديك ثمانية مرضى: أربعة في ICU (اثنان منهم على جهاز التنفس الاصطناعي) وأربعة مرضى عاديين. ماذا تفعل أولًا؟",options:[{text:"أنقل جميع المرضى عموديًا إلى الطابق الأول",correct:!1,feedback:"الإخلاء الأفقي أولًا وهو أسرع بكثير؛ والعمودي لا يكون إلا إذا لم يكفِ الأفقي."},{text:"وفق RACE: أنقذ المرضى القريبين من النار، وأجهّز القسم الآمن خلف الأبواب المانعة للدخان في الطابق نفسه، مع إطلاق الإنذار",correct:!0,feedback:"صحيح: الإنقاذ (Rescue) والإخلاء الأفقي. انقل المرضى إلى القسم الآمن."},{text:"أخرج وحدي",correct:!1,feedback:"غير صحيح: حماية المرضى من مسؤوليتك."},{text:"أنتظر فريق 115",correct:!1,feedback:"لا تنتظر؛ فالمرضى معرّضون للخطر."}]},{prompt:"القسم الآخر من الطابق الثالث آمن. ويوجد مريضان على جهاز التنفس الاصطناعي. أيّ المرضى يُنقلون أولًا؟",options:[{text:"المرضى القادرون على المشي، لأنّ نقلهم أسهل",correct:!1,feedback:"غير صحيح: يُقدَّر الخطر أولًا، لا السهولة."},{text:"مرضى ICU على جهاز التنفس الاصطناعي: 3 أشخاص، وكيس التنفس اليدوي (bag-mask)، ومزلّجة الإخلاء (Evac Sled)",correct:!1,feedback:"طريقة نقلهم صحيحة، لكنهم ليسوا الأولوية إذا كان مرضى آخرون أقرب إلى النار."},{text:"المرضى الأقرب إلى الدخان والنار أولًا، ثم وفق ترتيب الخطة",correct:!0,feedback:"صحيح: يبدأ الإنقاذ (Rescue) بالمعرّضين للخطر المباشر."},{text:"جميع المرضى في الوقت نفسه",correct:!1,feedback:"هذا غير ممكن عمليًا؛ فالترتيب ضروري."}]},{prompt:"نُقل جميع المرضى وأنت الآن في القسم الآمن. ووصل فريق 115. ماذا تفعل؟",options:[{text:"أذهب إلى المنزل",correct:!1,feedback:"غير صحيح: يجب أن تُبلغ الفريق وتحمي المرضى."},{text:"أُحصي المرضى وأُبلغ فريق 115 وقائد الحادث: أين كل مريض وما الذي يلزم",correct:!0,feedback:"صحيح: إحصاء المرضى (Accountability) وتقرير موجز للفريق."},{text:"أعود إلى قسم الحريق",correct:!1,feedback:"العودة من دون إذن ممنوعة."},{text:"أنقل المرضى إلى خارج المبنى",correct:!1,feedback:"لا حاجة إلى ذلك إذا كان القسم الآمن الداخلي محميًا."}]}],quiz:[{question:"ما المستوى الأول من مستويات الإخلاء؟",options:[{text:"الإخلاء الكامل للمستشفى",correct:!1,feedback:"هذا هو الملاذ الأخير."},{text:"الحماية في المكان (Defend in Place)",correct:!0,feedback:"صحيح: احمِ أولًا، ثم انقل عند الحاجة."},{text:"الإخلاء العمودي",correct:!1,feedback:"هذا هو المستوى الثالث."},{text:"الإخراج إلى خارج المستشفى",correct:!1,feedback:"هذا هو الملاذ الأخير."}]},{question:"في أثناء الإخلاء، أيّ المرضى يُنقلون أولًا؟",options:[{text:"مرضى ICU، لأن حالتهم هي الأخطر",correct:!1,feedback:"هم ضمن الترتيب، لكنهم ليسوا الأولوية إن لم يكونوا معرّضين لخطر مباشر."},{text:"المرضى المعرّضون لخطر مباشر (القريبون من النار)",correct:!0,feedback:"صحيح: الإنقاذ (Rescue)."},{text:"المرضى القادرون على المشي، لأنهم يخرجون أسرع",correct:!1,feedback:"بعد المعرّضين للخطر المباشر."},{text:"الأغراض الثمينة",correct:!1,feedback:"غير صحيح: الأرواح أولًا."}]},{question:"كيف يُنقل مريض ICU الموصول بجهاز التنفس الاصطناعي؟",options:[{text:"شخص واحد وكرسي متحرّك، مع وضع جهاز التنفس الاصطناعي في حِجر المريض",correct:!1,feedback:"هذا قليل جدًا."},{text:"3 أشخاص، وكيس التنفس اليدوي (bag-mask)، ومزلّجة الإخلاء (Evac Sled) أو السرير",correct:!0,feedback:"صحيح: يلزم فريق."},{text:"بالمصعد فقط، على السرير وجهاز التنفس الاصطناعي يعمل",correct:!1,feedback:"المصعد ممنوع في أثناء الحريق."},{text:"أترك المريض في مكانه",correct:!1,feedback:"لا تترك المريض وحده أبدًا؛ فمرضى التنفس الاصطناعي يُنقلون في آخر الترتيب، لكن بكيس التنفس اليدوي (bag-mask) وفريق من 3 أشخاص."}],explanation:"يحتاج مريض ICU الموصول بجهاز التنفس الاصطناعي إلى فريق: كيس التنفس اليدوي (bag-mask) و3 أشخاص على الأقل، مع مزلّجة الإخلاء (Evac Sled) أو السرير. ولا تترك المريض وحده."},{question:"ما القسم المانع للدخان (Smoke Compartment)؟",options:[{text:"غرفة يتجمّع فيها الدخان ثم تسحبه مراوح الشفط إلى الخارج",correct:!1,feedback:"غير صحيح؛ إنه قسم لمنع انتشار الدخان."},{text:"جزء من الطابق مفصول بجدران وأبواب مانعة للدخان",correct:!0,feedback:"صحيح: في كل طابق قسمان أو أكثر."},{text:"مطفأة للدخان",correct:!1,feedback:"ليس جهازًا، بل جزء من الطابق تحيط به جدران وأبواب مانعة للدخان."},{text:"نظام التهوية الذي يطرد الدخان من المبنى",correct:!1,feedback:"يتحكّم فريق الهندسة في نظام التهوية (HVAC)؛ أما القسم المانع للدخان فجزء من الطابق خلف أبواب مانعة للدخان."}],explanation:"وفق NFPA 101، يُقسَّم كل طابق بجدران وأبواب مانعة للدخان إلى قسمين أو أكثر، لينتقل المرضى أفقيًا من قسم الحريق إلى القسم الآمن."},{question:"وصل المرضى إلى القسم الآمن، ويريد أحد الزوّار العودة إلى الغرفة لإحضار حقيبة. ماذا تقول؟",options:[{text:"لا يعود أحد دون إذن 115 وقائد الحادث",correct:!0},{text:"يمكنه الذهاب إن كان سريعًا وبقي منخفضًا تحت الدخان",correct:!1},{text:"يمكنه الذهاب بعد فتح الأبواب المانعة للدخان لتهوية المكان",correct:!1},{text:"يمكنه الذهاب إذا رافقه أحد العاملين",correct:!1}],explanation:"قد ينتشر الدخان والنار بسرعة، ويجب أن تبقى الأبواب المانعة للدخان مغلقة. ولا يعود أحد إلى قسم الحريق دون إذن فريق 115 وقائد الحادث."},{question:"اكتمل الإخلاء الأفقي، لكن الدخان بدأ يدخل القسم الآمن أيضًا. ما الخطوة التالية؟",options:[{text:"الإخلاء العمودي عبر الدرج، بأمر من قائد الحادث",correct:!0},{text:"جمع الجميع عند المصاعد وانتظار وصولها",correct:!1},{text:"العودة إلى القسم الأول، فربما انطفأت النار الآن",correct:!1},{text:"فتح كل النوافذ وإبقاء الجميع في أماكنهم",correct:!1}],explanation:"عندما لا يكفي الإخلاء الأفقي، يُنقل المرضى عموديًا عبر الدرج إلى طابق أدنى، وفق أوامر قائد الحادث. ولا تُستخدم المصاعد."}],tips:["اعرف أماكن أبواب الأقسام المانعة للدخان في وحدتك، وأيّ قسم هو الآمن لكل جزء من الطابق.","احتفظ بقائمة محدّثة للمرضى الذين يحتاجون إلى مساعدة في النقل: الموصولين بجهاز التنفس الاصطناعي أو بالأكسجين، أو على الأسرّة أو الكراسي المتحرّكة.","اعرف أماكن معدّات الإخلاء (Evac Sled وStair Chair والأسطوانات المحمولة وأجهزة bag-mask) وتدرّب عليها في التمارين.","في القسم الآمن، عُدّ مرضاك وفق القائمة، وإذا نقص أحد فأبلغ المسؤول فورًا."],activity:{prompt:"أنت المسؤول عن التمريض في قسم الجراحة. يخرج دخان من غرفة الشراشف في قسمك، وصدر الأمر بالإخلاء الأفقي. مرضاك: اثنان يستطيعان المشي، وواحد على كرسي متحرّك، وواحد على سرير موصول بالأكسجين. ويقترح زميل إنزال الجميع بمصعد الأسرّة. ماذا تفعل؟",options:[{text:"أنقل المرضى عبر الأبواب المانعة للدخان إلى القسم الآمن في الطابق نفسه، الأقرب إلى الدخان أولًا، ومريض الأكسجين بأسطوانة محمولة",correct:!0,feedback:"صحيح: الأمر هو الإخلاء الأفقي إلى قسم آمن في الطابق نفسه، بدءًا بالمعرّضين لخطر مباشر. ويُنقل مريض الأكسجين بأسطوانة محمولة."},{text:"أستخدم مصعد الأسرّة، لأنه أسرع طريقة لنقل مريض السرير",correct:!1,feedback:"لا تُستخدم المصاعد في أثناء الحريق: فقد تتوقّف في طابق الحريق أو يدخلها الدخان."},{text:"أنقل المرضى القادرين على المشي وأترك مريض الأكسجين في سريره والباب مغلق",correct:!1,feedback:"لا تترك مريضًا وحده أبدًا. يُنقل مريض السرير بسريره أو بالشرشف، موصولًا بأسطوانة محمولة."},{text:"أنزل بالجميع مباشرة عبر الدرج إلى الطابق الأرضي",correct:!1,feedback:"لا يُلجأ إلى الإخلاء العمودي إلا عندما لا يكفي الإخلاء الأفقي، وبأمر من قائد الحادث."}]}},{id:8,code:"ELEV-08",icon:"ArrowUpDown",accent:"#64748b",category:"السلامة",title:"قواعد المصاعد في المستشفى",subtitle:"الاستخدام، والاحتجاز داخل المصعد، والحظر في أثناء الحريق",summary:"المصاعد في المستشفى مهمة لنقل المرضى والمعدات، لكنّ لها مخاطرها. ووفق ASME A17.1 وNFPA 101، تتّجه المصاعد في أثناء الحريق تلقائيًا إلى الطابق المحدّد، ولا يستخدمها إلا فريق الإطفاء (115) بمفتاح خاص (Firefighter Service Mode). والاحتجاز داخل المصعد لا يعرّض الحياة للخطر عمومًا إذا حافظ الأشخاص على هدوئهم وطلبوا المساعدة بالطريقة الصحيحة؛ فالهواء متوفّر داخل المصعد.",facts:[{label:"الاستخدام في أثناء الحريق",value:"ممنوع (NFPA 101)"},{label:"وضع خدمة رجال الإطفاء (Firefighter Service Mode)",value:"فريق 115 فقط"},{label:"عند الاحتجاز",value:"حافظ على هدوئك: الهواء متوفّر"},{label:"الإنذار وهاتف الطوارئ",value:"إلزامي (ASME A17.1)"}],steps:[{title:"1. الاستخدام العادي",detail:"الأولوية للمرضى على الأسرّة والكراسي المتحرّكة. لكل مريض على سرير موظفان اثنان. لا تحمّل المصعد أكثر من الوزن المكتوب على لوحته."},{title:"2. في أثناء الحريق — ممنوع",detail:"عند إعلان Code Red، تتّجه المصاعد تلقائيًا إلى الطابق المحدّد (Phase I Recall). وبعد ذلك لا يستطيع استخدامها إلا فريق 115 بمفتاح خاص (Phase II). ويستخدم العاملون والزوّار سلالم الطوارئ.",critical:!0},{title:"3. الاحتجاز — الخطوات الأولى",detail:"حافظ على هدوئك؛ فالهواء متوفّر داخل المصعد. وإذا كان معك مريض، فقيّم حالته أولًا (Code Blue عند الحاجة). ثم اضغط زر الإنذار واطلب المساعدة عبر هاتف المصعد.",critical:!0},{title:"4. هاتف المصعد",detail:"يجب أن يكون في كل مصعد نظام اتصال للطوارئ (ASME A17.1) يستجيب على مدار 24 ساعة: فريق الصيانة أو الأمن. قل: أيّ مصعد، وبين أيّ طابقين، وكم عدد الأشخاص، وهل هناك مصاب.",critical:!0},{title:"5. المحظورات في أثناء الاحتجاز",detail:`لا تفتح الباب بالقوة: فقد تسقط في بئر المصعد.
• لا تخرج من فتحة سقف المصعد: خطر قاتل.
• لا تستسلم للذعر (panic)؛ فالهواء لن ينفد.
• احتفظ ببطارية هاتفك للاتصالات الضرورية.`,critical:!0},{title:"6. الإنقاذ من المصعد",detail:"يتولّاه فقط فريق الصيانة المدرَّب أو فريق 115، لا العاملون ولا الزوّار. الإجراء: 1) يُنزَل المصعد إلى أقرب طابق، 2) يُفتح الباب بمفتاح خاص، 3) يخرج الأشخاص بأمان، 4) يُفحص المصعد قبل إعادة تشغيله."}],reference:[{heading:"المرحلتان الأولى والثانية (Phase I وPhase II)",points:["المرحلة الأولى (Phase I — Recall): في أثناء الحريق يتّجه المصعد تلقائيًا إلى الطابق المحدّد.","المرحلة الثانية (Phase II — Service): فريق 115 فقط بمفتاح خاص.","للعاملين والزوّار: ممنوع منعًا باتًا.","استخدم سلالم الطوارئ فقط."]},{heading:"أزرار المصعد وأجهزته",points:["زر الإنذار (Alarm): جرس الإنذار.","زر الهاتف (Phone): هاتف طوارئ يعمل على مدار 24 ساعة.","زر الإيقاف (Stop): عند الضرورة فقط ووفق التعليمات.","زر إبقاء الباب مفتوحًا (Door Hold): لتحميل الأسرّة ونقلها فقط.","مفتاح خدمة الإطفاء (Fire Service Key): فريق 115 فقط."]},{heading:"نقل المرضى ذوي الحالات الخاصة",points:["ICU وجهاز التنفس الاصطناعي: نقّالة، وكيس التنفس اليدوي (bag-mask)، وبطارية احتياطية.","مرضى الإصابات (Trauma): نقّالة خاصة وشخصان.","المرضى ذوو الوزن الزائد جدًا (Bariatric): المصعد الكبير المخصّص.","السرير المتحرّك (Stretcher): شخصان مع تثبيت مكابح العجلات.","الكرسي المتحرّك: يكفي شخص واحد."]}],warnings:["لا تستخدم المصعد في أثناء الحريق: فقد يتوقف في طابق الحريق أو يدخل الدخان إلى بئره. واستدعاء المصاعد في المرحلة الأولى (Phase I Recall) تلقائي. وإذا احتُجزت داخل المصعد، فحافظ على هدوئك، واستخدم زر الإنذار وهاتف المصعد، ولا تفتح الباب بالقوة."],realCase:"حالة عملية (مثال تعليمي): كان ثلاثة موظفين مع مريض عمره 75 عامًا على سرير داخل المصعد عند الساعة 22:30. فانقطعت الكهرباء وتوقّف المصعد بين الطابقين الثاني والثالث. فضغط أحد الموظفين زر الإنذار فورًا وأبلغ فريق الصيانة عبر هاتف المصعد. وكان المريض مصابًا بداء السكري؛ فكان الموظفون يتحقّقون من حالته ومن سكر الدم كل 5 دقائق. ووصل فريق الصيانة بعد 22 دقيقة وخرج الجميع بسلام. ولو فُتح الباب بالقوة، لكان هناك خطر السقوط في بئر المصعد.",caseStudy:[{prompt:"أنت ممرض داخل المصعد مع مريض عمره 80 عامًا على سرير. توقّف المصعد وانقطعت الكهرباء، لكنّ إنارة الطوارئ (UPS) تعمل. ماذا تفعل أولًا؟",options:[{text:"أفتح الباب بالقوة",correct:!1,feedback:"خطير: فقد تسقط في بئر المصعد."},{text:"أقيّم حالة المريض: هل هو واعٍ؟ وكيف حال المجرى الهوائي والتنفّس والدوران (ABC)؟",correct:!0,feedback:"صحيح: سلامة المريض أولًا."},{text:"أضغط زر الإنذار فورًا ولا أفحص المريض",correct:!1,feedback:"الإنذار مهم ويأتي مبكرًا، لكنّ تقييمًا سريعًا للمريض يأتي أولًا."},{text:"أخرج من فتحة سقف المصعد",correct:!1,feedback:"خطر قاتل."}]},{prompt:"المريض واعٍ وهادئ وABC طبيعية. ما الخطوة الثانية؟",options:[{text:"أضغط زر الإنذار وأطلب المساعدة عبر هاتف المصعد",correct:!0,feedback:"صحيح: زر الإنذار (Alarm) وهاتف الطوارئ (Phone). ويستجيب فريق الصيانة على مدار 24 ساعة."},{text:"لا أفعل شيئًا وأنتظر",correct:!1,feedback:"من دون إنذار لن يعلم أحد أنك محتجز."},{text:"أكتفي بالاتصال بأحد أصدقائي من هاتفي الشخصي",correct:!1,feedback:"هاتف المصعد متصل مباشرة بفريق الصيانة وهو الأفضل."},{text:"أضغط أزرار الطوابق",correct:!1,feedback:"لا يعمل المصعد من دون كهرباء؛ فلا فائدة من ذلك."}]},{prompt:"يقول فريق الصيانة: «سنصل بعد 15 دقيقة.» وما زال المريض بحالة طبيعية. ماذا تفعل حتى وصول الفريق؟",options:[{text:"أخرج من فتحة سقف المصعد",correct:!1,feedback:"خطر قاتل."},{text:"أفتح الباب بالقوة",correct:!1,feedback:"غير صحيح: هناك خطر السقوط."},{text:"أفحص المريض كل 5 دقائق (العلامات الحيوية)، وأتحدّث معه وأطمئنه",correct:!0,feedback:"صحيح: المراقبة والدعم النفسي."},{text:"أتحدّث بهاتفي دون توقف حتى تنفد البطارية",correct:!1,feedback:"احتفظ بالبطارية؛ فهاتف المصعد أهم."}]}],quiz:[{question:"في أثناء الحريق، المصعد…؟",options:[{text:"استخدمه لتسريع إخلاء المرضى طريحي الفراش",correct:!1,feedback:"غير صحيح: ممنوع."},{text:"ممنوع؛ ولا يستخدمه إلا فريق 115",correct:!0,feedback:"صحيح: NFPA 101."},{text:"للمرضى فقط",correct:!1,feedback:"ولا للمرضى أيضًا: ففي أثناء الحريق لا يستخدم المصاعد إلا فريق 115."},{text:"مسموح به إلى أن يُعلَن Code Red رسميًا",correct:!1,feedback:"يسري المنع طوال الحريق، لا بعد الإعلان فقط؛ ويستخدم العاملون والزوّار سلالم الطوارئ."}],explanation:"في أثناء الحريق تتّجه المصاعد تلقائيًا إلى الطابق المحدّد (Phase I)، ولا يستخدمها إلا فريق 115 بمفتاح خاص (Phase II). ويستخدم العاملون والزوّار سلالم الطوارئ."},{question:"ما الخطوة الأولى عند الاحتجاز داخل المصعد؟",options:[{text:"فتح الباب بالقوة",correct:!1,feedback:"خطر قاتل."},{text:"الخروج من فتحة سقف المصعد",correct:!1,feedback:"خطر قاتل."},{text:"تقييم المريض، ثم إطلاق الإنذار",correct:!0,feedback:"صحيح: ABC أولًا."},{text:"الخوف والذعر",correct:!1,feedback:"الذعر لا يفيد، والهواء لن ينفد؛ قيّم حالة المريض ثم استخدم زر الإنذار والهاتف."}],explanation:"الهواء متوفّر داخل المصعد، فحافظ على هدوئك: قيّم حالة المريض الذي معك أولًا (Code Blue عند الحاجة)، ثم اضغط زر الإنذار واستخدم هاتف المصعد."},{question:"ما المقصود بـ Phase I Recall؟",options:[{text:"يستخدم فريق 115 المصعد بمفتاح خاص للوصول إلى طابق الحريق",correct:!1,feedback:"هذه هي المرحلة الثانية (Phase II)."},{text:"اتّجاه المصعد تلقائيًا إلى الطابق المحدّد في أثناء الحريق",correct:!0,feedback:"صحيح: إنه تلقائي."},{text:"إنقاذ المحتجزين داخل المصعد عند انقطاع الكهرباء",correct:!1,feedback:"يتولّى الإنقاذ من المصعد فريق الصيانة المدرَّب أو فريق 115؛ أما Phase I فهو الاستدعاء التلقائي."},{text:"تدريب العاملين",correct:!1,feedback:"ليست Phase I تدريبًا، بل اتّجاه المصعد تلقائيًا إلى الطابق المحدّد في أثناء الحريق."}],explanation:"الاستدعاء في المرحلة الأولى (Phase I Recall) تلقائي: ففي أثناء الحريق يتّجه المصعد إلى الطابق المحدّد. أما المرحلة الثانية (Phase II) فهي استخدام فريق 115 للمصعد بمفتاح خاص."},{question:"الهاتف داخل المصعد…؟",options:[{text:"غير ضروري",correct:!1,feedback:"غير صحيح: إنه إلزامي (ASME A17.1)."},{text:"إلزامي ويستجيب على مدار 24 ساعة",correct:!0,feedback:"يجب أن يكون في كل مصعد هاتف طوارئ (ASME A17.1) يُجاب على مدار 24 ساعة من فريق الصيانة أو الأمن."},{text:"إلزامي، لكنه لا يستجيب إلا في أوقات الدوام",correct:!1,feedback:"يجب أن يُجاب على مدار 24 ساعة لا في أوقات الدوام فقط، فالاحتجاز قد يحدث في أيّ وقت."},{text:"لفريق الصيانة فقط للاتصال بغرفة التحكّم",correct:!1,feedback:"إنه للجميع."}],explanation:"يشترط ASME A17.1 وجود نظام اتصال للطوارئ في كل مصعد يستجيب على مدار 24 ساعة، من فريق الصيانة أو الأمن."},{question:"يُعلَن Code Red وأنت تنتظر المصعد مع مريض على كرسي متحرّك. يصل المصعد وتنفتح أبوابه. ماذا تفعل؟",options:[{text:"لا أستخدمه: أتّبع خطة الإخلاء عبر الدرج أو إلى القسم الآمن",correct:!0},{text:"أستخدمه بسرعة قبل أن يبدأ الاستدعاء، لأنه وصل بالفعل",correct:!1},{text:"أستخدمه للنزول طابقًا واحدًا فقط، ثم أنتقل إلى الدرج",correct:!1},{text:"أستخدمه لكنني أضغط زر فتح الباب طوال الطريق",correct:!1}],explanation:"في أثناء Code Red تُستدعى المصاعد تلقائيًا ولا يستخدمها إلا فريق 115. وقد يتوقّف المصعد في طابق الحريق أو يدخله الدخان. استخدم الدرج وخطة الإخلاء."},{question:"أنت وزميل ومريض محتجزون في المصعد. يقول فريق الصيانة إنه في الطريق. ويريد زميلك فتح الأبواب لأن المصعد يبدو محاذيًا لأحد الطوابق. ما الصحيح؟",options:[{text:"أبقِ الأبواب مغلقة: لا يفتحها إلا فريق الصيانة أو 115 بمفتاح خاص",correct:!0},{text:"افتحها، لأن المصعد يبدو محاذيًا للطابق في الخارج",correct:!1},{text:"افتحها قليلًا ليدخل مزيد من الهواء النقي",correct:!1},{text:"افتحها إذا بدأ المريض يشعر بالخوف أو الضيق",correct:!1}],explanation:"قد يتحرّك المصعد دون إنذار، وقد تُسقط فجوةٌ شخصًا في بئر المصعد. ولا يفتح الأبواب إلا فريق الصيانة المدرَّب أو فريق 115 بمفتاح خاص."}],tips:["اقرأ لوحة الحمولة في المصعد ولا تحمّله فوق طاقته بالأسرّة والعاملين والأجهزة.","اعرف مكان زر الإنذار وهاتف الطوارئ في المصاعد التي تستخدمها مع المرضى.","عند إعلان Code Red، لا تنتظر المصعد: استخدم درج الخروج واتّبع خطة الإخلاء في قسمك.","قبل نقل مريض موصول بالأكسجين في المصعد، تأكّد من أن الأسطوانة المحمولة فيها أكسجين كافٍ لتأخير محتمل."],activity:{prompt:"تنقل مريضًا موصولًا بالأكسجين في المصعد. يتوقّف المصعد بين طابقين وتعمل إنارة الطوارئ. المريض خائف، والأسطوانة المحمولة هي المصدر الوحيد للأكسجين. ماذا تفعل؟",options:[{text:"أقيّم حالة المريض والأكسجين، ثم أستخدم زر الإنذار وهاتف المصعد وأُبلغ أن المريض موصول بالأكسجين",correct:!0,feedback:"صحيح: قيّم حالة المريض أولًا (Code Blue عند الحاجة)، ثم اطلب المساعدة. اذكر المصعد والطابقين وعدد الأشخاص وحالة المريض بما فيها الأكسجين، كي يعرف المستجيبون مدى الاستعجال."},{text:"أفتح الباب بالقوة بيديّ كي نتسلّق إلى الطابق الأعلى",correct:!1,feedback:"فتح الباب بالقوة قد يُسقطك في بئر المصعد. لا يفتح الباب إلا فريق الصيانة المدرَّب أو فريق 115."},{text:"أخرج من فتحة سقف المصعد لأبحث عن المساعدة",correct:!1,feedback:"الخروج من فتحة سقف المصعد خطر قاتل. ابقَ داخل المصعد واستخدم زر الإنذار والهاتف."},{text:"أنتظر بصمت ولا أتصل بأحد، لأحافظ على بطارية هاتفي",correct:!1,feedback:"زر الإنذار وهاتف المصعد موجودان لاستخدامهما فورًا. والحفاظ على بطارية هاتفك لا يعني عدم طلب المساعدة."}]}},{id:9,code:"SHOCK-09",icon:"Zap",accent:"#eab308",category:"السلامة",title:"الصعق الكهربائي وLOTO",subtitle:"الإقفال والوسم (Lockout/Tagout)، والاستجابة للصعق الكهربائي، والصعق الكبير (Macroshock) والصعق الدقيق (Microshock)",summary:"في المستشفى مئات الأجهزة الكهربائية: أجهزة المراقبة، وأجهزة التنفس الاصطناعي، والمضخّات، وأجهزة إزالة الرجفان، وMRI. والتيار الذي يقارب 50 mA ويمرّ عبر الجلد (Macroshock) قد يكون قاتلًا. أمّا المرضى الذين تصل إلى قلوبهم مباشرةً قثاطير (catheters) أو أسلاك منظّم ضربات القلب (pacemaker)، فهم حسّاسون حتى لتيار أقل بكثير (Microshock)؛ ولذلك فإنّ الحدّ المسموح به لتيار التسرّب (leakage current) في الأجهزة المتصلة بالقلب هو 10 μA. ووفق NFPA 99 وOSHA 1910.147، يلزم الإقفال والوسم (LOTO) عند أي صيانة لجهاز كهربائي.",facts:[{label:"الصعق الكبير الخطير (Macroshock)",value:"نحو 50 mA عبر الجلد"},{label:"حدّ تيار التسرّب",value:"10 μA (للأجهزة المتصلة بالقلب)"},{label:"حماية الأماكن الرطبة",value:"IPS أو GFCI (NFPA 99)"},{label:"معيار LOTO",value:"OSHA 1910.147"}],steps:[{title:"1. الصعق الكبير (Macroshock) والصعق الدقيق (Microshock)",detail:"الصعق الكبير (Macroshock): يمرّ التيار عبر الجلد؛ ونحو 50 mA قد يُدخل القلب في الرجفان البطيني (VF). الصعق الدقيق (Microshock): يصل التيار مباشرةً إلى القلب عبر قثطار أو سلك منظّم ضربات القلب (pacemaker)؛ وتيار ضئيل جدًا (نحو 100 μA) قد يُحدث VF، ولذلك فإنّ حدّ الأمان هو 10 μA. ويوجد هذا الخطر في ICU وCCU.",critical:!0},{title:"2. LOTO — الإقفال والوسم",detail:"ست خطوات: 1) التحضير، 2) إيقاف تشغيل الجهاز، 3) عزله عن مصدر الكهرباء، 4) وضع القفل وبطاقة «ممنوع التشغيل» (Do Not Operate)، 5) تفريغ الطاقة المخزّنة (مثل المكثّفات)، 6) التحقّق من أنّ الجهاز لا يعمل (Try). ولكل موظف قفل ومفتاح خاصّان به: مفتاح واحد لشخص واحد.",critical:!0},{title:"3. الصعق الكهربائي — ما لا تفعله أولًا",detail:"لا تلمس المصاب بالصعق الكهربائي ما لم يُفصل التيار الكهربائي؛ فالكهرباء ستصيبك أنت أيضًا. افصل التيار أولًا: من قاطع الدائرة (Circuit Breaker) أو بنزع القابس. وإذا لم تستطع، فأبعده عن مصدر الكهرباء بأداة جافة غير موصلة للكهرباء (خشب أو بلاستيك)، لا بأداة معدنية.",critical:!0},{title:"4. بعد الصعق الكهربائي — العلاج",detail:"قيّم ABC. وإذا توقّف القلب: CPR وAED. أجرِ تخطيط القلب (ECG) لكل المصابين بالصعق الكهربائي. وتلزم مراقبة القلب (24 ساعة عمومًا) لمن فقدوا الوعي، أو كان تخطيط قلبهم غير طبيعي، أو ظهرت لديهم أعراض قلبية، أو تعرّضوا لصعق كهربائي عالي الجهد. وللحروق الكهربائية موضع دخول وموضع خروج للتيار (Entry/Exit): افحص كليهما.",critical:!0},{title:"5. أنواع الدوائر الكهربائية في المستشفى",detail:"Normal: الكهرباء العادية (220–230 فولت). ولنظام الكهرباء الأساسية (Essential Electrical System) ثلاثة فروع: Life Safety وCritical Branch (ICU، OR، المختبر) اللذان تعود إليهما الكهرباء من المولّد خلال 10 ثوانٍ (NFPA 99 وNFPA 110، Type 10)، وEquipment Branch الذي يُوصل لاحقًا بتأخير تلقائي. ولأهمّ الأجهزة أيضًا UPS.",critical:!0},{title:"6. حماية الأماكن الرطبة: IPS وGFCI وRCD",detail:"وفق NFPA 99، تحتاج أماكن العمل الرطبة (wet procedure locations)، مثل بعض غرف العمليات، إلى حماية خاصة: نظام الطاقة المعزول (Isolated Power System)، أو قاطع التسرّب الأرضي (GFCI) إذا كان قطع الكهرباء لا يشكّل خطرًا على المريض. ويفصل قاطع التسرّب الأرضي الأمريكي الكهرباء عند نحو 4–6 mA؛ أمّا قاطع التيار المتبقّي (RCD) في نظام IEC فعمومًا عند 30 mA أو 10 mA. افحصه دوريًا بزر الاختبار «TEST»."}],reference:[{heading:"علامات الصعق الكهربائي",points:["حروق في موضعَي دخول التيار وخروجه (افحص كليهما).","اضطراب نظم القلب (arrhythmia).","انحلال العضلات المخطّطة (Rhabdomyolysis).","متلازمة الحيّز (Compartment syndrome).","علامات عصبية: اضطراب الوعي، والاختلاج (seizure)، والخدر.","أضرار داخلية غير ظاهرة: فحوص الدم (CK، troponin، K+)."]},{heading:"LOTO — الأدوات والإجراءات",points:["قفل LOTO الخاص.","البطاقة (Tag): «ممنوع التشغيل» (Do Not Operate)، والاسم، والتاريخ.","مفتاح واحد لشخص واحد (غير مشترك).","سجلّ LOTO: أيّ جهاز، ومن، ومتى.","التجربة (Try): تأكد من أنّ الكهرباء فُصلت فعلًا.","تجاوز LOTO (Bypass) ممنوع ويُعدّ مخالفة قانونية."]},{heading:"حماية المرضى ذوي الخطورة العالية",points:["ICU وCCU ومنظّم ضربات القلب المؤقت: خطر الصعق الدقيق (Microshock).","يجب أن تكون الأجهزة الطبية مؤرَّضة (grounded) وأن تُفحص دوريًا.","الأماكن الرطبة: IPS أو GFCI وفق NFPA 99.","جهاز إزالة الرجفان: للعاملين المدرَّبين فقط.","MRI: خط 5 غاوس (Gauss)؛ ولا معادن مغناطيسية بالقرب منه.","لا تلمس أسلاك منظّم ضربات القلب الخارجية بيدين مبلّلتين."]}],warnings:["لا تلمس المصاب بالصعق الكهربائي ما لم يُفصل التيار الكهربائي؛ وإلّا أُصبت أنت أيضًا بالصعق. وفي ICU، قد يؤدي تيار ضئيل جدًا يمرّ عبر قثطار أو سلك منظّم ضربات القلب إلى توقّف القلب. وتجاوز LOTO يعرّض أرواح العاملين للخطر ويُعدّ مخالفة قانونية."],realCase:"حالة عملية (مثال تعليمي): بدأ فنّي بإصلاح مضخة IV في ICU من دون LOTO، لظنّه أنّ الكهرباء مفصولة. وعندما لمسها، تعرّض لصعق كهربائي بجهد 220 فولت ودخل قلبه في VF. ففصل موظف قريب الكهرباء أولًا بنزع القابس (ولو تعذّر ذلك، لأبعده عن الجهاز بعصا بلاستيكية جافة)، ثم بدأ CPR؛ ووصل AED خلال 45 ثانية، وبعد صدمتين عاد قلبه إلى العمل (ROSC). وبعد بضعة أيام في ICU تعافى تمامًا. الدرس المستفاد: LOTO والتحقّق من فصل الكهرباء (Try) في كل مرة.",caseStudy:[{prompt:"أنتِ ممرضة في ICU. سقط أحد عمّال الكهرباء على الأرض بالقرب من مضخة IV، والسلك الكهربائي في يده. ماذا تفعلين أولًا؟",options:[{text:"أسحبه بيديّ",correct:!1,feedback:"خطر قاتل: فالكهرباء ستصيبكِ أنتِ أيضًا."},{text:"أفصل الكهرباء من قاطع الدائرة (Circuit Breaker) في الطابق أو من القابس",correct:!0,feedback:"صحيح: تُفصل الكهرباء أولًا دائمًا."},{text:"أبدأ CPR فورًا",correct:!1,feedback:"لمسه خطير ما لم تُفصل الكهرباء."},{text:"أصبّ عليه الماء ليبرد",correct:!1,feedback:"الماء والكهرباء معًا: خطر قاتل."}]},{prompt:"فُصلت الكهرباء. والعامل فاقد للوعي. ما الخطوة الثانية؟",options:[{text:"أقيّم ABC، وأعلن Code Blue، وأبدأ CPR عند الحاجة",correct:!0,feedback:"صحيح: توقّف القلب بعد الصعق الكهربائي شائع."},{text:"أستخدم جهاز AED فورًا من دون تقييم",correct:!1,feedback:"قيّمي التنفّس والنبض أولًا وأعلني Code Blue؛ ثم استخدمي جهاز AED حين يصل."},{text:"أستدعي عمّال الكهرباء",correct:!1,feedback:"لاحقًا؛ المصاب أولًا."},{text:"أفحص حرق موضع دخول التيار",correct:!1,feedback:"لاحقًا؛ ABC أولًا."}]},{prompt:"بعد CPR، عاد قلب العامل إلى العمل (ROSC) وهو واعٍ. وأول تخطيط للقلب (ECG) طبيعي. ماذا تفعلين بعد ذلك؟",options:[{text:"أرسله إلى المنزل",correct:!1,feedback:"غير صحيح: لقد أُصيب بتوقّف القلب ويحتاج إلى مراقبة دقيقة."},{text:"النقل إلى ICU، ومراقبة القلب (24 ساعة عمومًا)، وفحوص الدم (CK، Troponin، K+)",correct:!0,feedback:"صحيح: بعد توقّف القلب، هناك خطر اضطراب النظم وانحلال العضلات المخطّطة (Rhabdomyolysis)."},{text:"أكتفي بفحص حروق موضعَي دخول التيار وخروجه (entry/exit)",correct:!1,feedback:"هذا لا يكفي؛ يلزم فحص شامل."},{text:"لا أفعل شيئًا؛ ROSC يكفي",correct:!1,feedback:"غير صحيح؛ فالمرحلة التي تلي ROSC بالغة الأهمية."}]}],quiz:[{question:"لماذا يُعدّ الصعق الدقيق (Microshock) خطيرًا في ICU؟",options:[{text:"لأنه لا يحدث إلا عند 50 mA، وهو المستوى الذي يُحَسّ عبر الجلد",correct:!1,feedback:"هذا هو الصعق الكبير (Macroshock) عبر الجلد."},{text:"لأنّ التيار يصل مباشرةً إلى القلب؛ فنحو 100 μA قد يُحدث VF، وحدّ الأمان هو 10 μA",correct:!0,feedback:"صحيح: الخطر على المرضى الموصولين بقثاطير ومنظّمات ضربات القلب."},{text:"لأنّ الجهد 220 فولت",correct:!1,feedback:"الخطر مرتبط بالتيار الذي يمرّ عبر القلب، لا بالجهد وحده."},{text:"لأن التيار يتجاوز دائمًا 1 أمبير، وهذا يكفي لحرق عضلة القلب من الداخل",correct:!1,feedback:"غير صحيح؛ فتيار ضئيل جدًا يكفي."}]},{question:"ما الخطوات الست لـ LOTO؟",options:[{text:"التحضير، والإيقاف، والعزل، والإقفال والوسم، وتفريغ الطاقة المخزّنة، والتحقّق (Try)",correct:!0,feedback:"صحيح: OSHA 1910.147."},{text:"التحضير، والإقفال والوسم، وبدء العمل، ثم التحقّق وتفريغ الطاقة المخزّنة بعد العمل فقط",correct:!1,feedback:"الترتيب خاطئ: الإيقاف والعزل وتفريغ الطاقة المخزّنة والتحقّق كلها تسبق بدء العمل."},{text:"القفل فقط، لأن القفل وحده يُبقي المعدات مطفأة",correct:!1,feedback:"الوسم والتحقّق ضروريان أيضًا."},{text:"الوسم فقط",correct:!1,feedback:"القفل ضروري أيضًا."}]},{question:"شخص أُصيب بصعق كهربائي؛ ما الخطوة الأولى؟",options:[{text:"أمسك بيده لأسحبه بعيدًا",correct:!1,feedback:"ستصيبك الكهرباء أنت أيضًا."},{text:"أفصل التيار الكهربائي",correct:!0,feedback:"صحيح: دائمًا أولًا."},{text:"CPR فورًا",correct:!1,feedback:"بعد فصل الكهرباء."},{text:"أسكب عليه الماء",correct:!1,feedback:"خطير: الماء ينقل الكهرباء."}]},{question:"بعد الصعق الكهربائي، من يحتاج إلى مراقبة القلب؟",options:[{text:"الجميع، لمدة ساعة واحدة فقط",correct:!1,feedback:"تُحدَّد مدة المراقبة بحسب خطورة حالة كل شخص، لا برقم ثابت."},{text:"ECG للجميع؛ ومراقبة (24 ساعة عمومًا) بعد فقد الوعي، أو ECG غير طبيعي، أو أعراض قلبية، أو صعق عالي الجهد",correct:!0,feedback:"صحيح: في الصعق منخفض الجهد دون أعراض ومع تخطيط قلب (ECG) طبيعي، لا تلزم عمومًا مراقبة طويلة."},{text:"ECG لمن لديه حروق فقط؛ ومراقبة 5 ساعات لكل الآخرين، أيًّا كان الجهد أو الأعراض أو نتيجة أول ECG",correct:!1,feedback:"غير صحيح: تخطيط القلب (ECG) للجميع، وتُحدَّد مدة المراقبة بحسب الخطورة لا برقم ثابت."},{text:"لا يلزم أي فحص، ولا حتى ECG",correct:!1,feedback:"غير صحيح: تخطيط القلب (ECG) ضروري لكل المصابين بالصعق الكهربائي."}]},{question:"أوقف فنّي الهندسة الطبية الحيوية مضخة التسريب (infusion pump) ونزع قابسها ووضع قفله وبطاقته. ماذا يجب أن يفعل قبل فتح هيكل الجهاز؟",options:[{text:"يفرّغ الطاقة المخزّنة ويحاول تشغيل المضخة ليتأكد أنها لا تعمل",correct:!0,feedback:"صحيح: تفريغ الطاقة المخزّنة والتحقّق (Try) هما آخر خطوتين في LOTO قبل بدء أي عمل."},{text:"يسلّم مفتاحه لزميل كي تُكمل المناوبة التالية الإصلاح",correct:!1,feedback:"غير صحيح: مفتاح واحد لشخص واحد؛ ويحتفظ كل موظف بقفله ومفتاحه."},{text:"ينزع البطاقة كي يرى موظفو القسم أن المضخة قيد الإصلاح",correct:!1,feedback:"غير صحيح: تبقى البطاقة مع القفل؛ فهي التي تخبر الآخرين بألّا يشغّلوا الجهاز."},{text:"يبدأ فورًا، لأن القفل وحده يثبت أن التيار مفصول",correct:!1,feedback:"غير صحيح: القفل لا يثبت شيئًا؛ تُفرَّغ الطاقة المخزّنة ويُختبر الجهاز أولًا."}],explanation:"وفق OSHA 1910.147، لا يبدأ العمل إلا بعد الإيقاف والعزل والإقفال والوسم وتفريغ الطاقة المخزّنة والتحقّق من أن الجهاز لا يعمل."},{question:"سقط زميل قرب مكتب التمريض وهو يلمس كابل تمديد تالفًا يتطاير منه الشرر. أيّ تصرّف خاطئ؟",options:[{text:"سحبه من ذراعه بعيدًا عن الكابل، لأن ذلك أسرع من البحث عن القاطع",correct:!0,feedback:"هذا هو التصرّف الخاطئ: لمسه قبل فصل التيار يجعلك جزءًا من الدائرة أيضًا."},{text:"فصل القاطع أو نزع القابس، إذا أمكن الوصول إليه بأمان",correct:!1,feedback:"هذا صحيح: فصل التيار هو الخطوة الأولى دائمًا."},{text:"استخدام أداة جافة من الخشب أو البلاستيك لإبعاد الكابل إذا تعذّر فصل التيار",correct:!1,feedback:"هذا صحيح عندما يتعذّر فصل التيار؛ ولا تُستخدم أداة معدنية أبدًا."},{text:"استدعاء فريق Code Blue في أثناء فصل التيار",correct:!1,feedback:"هذا صحيح: كثيرًا ما يتبع توقّفُ القلب الصعقَ الكهربائي، لذا تُطلب المساعدة مبكرًا."}],explanation:"لا تلمس المصاب بالصعق الكهربائي قبل فصل التيار. افصل التيار أولًا، أو أبعده عن المصدر بأداة جافة من الخشب أو البلاستيك، واطلب المساعدة."}],tips:["اعرف مكان قواطع الدائرة (Circuit Breaker) الخاصة بقسمك، وأبقِ الطريق إليها خاليًا.","قبل استخدام أي جهاز، انظر إلى القابس والكابل والهيكل؛ وأوقف عن الاستخدام كل جهاز تلف كابله أو انسكب عليه سائل، وضع عليه بطاقة وأبلغ قسم الهندسة الطبية الحيوية (Biomedical Engineering).","لا تلمس الأسلاك الخارجية لمنظّم ضربات القلب (pacemaker) أو وصلات القثطار بيدين مبلّلتين، أو وأنت تلمس جهازًا آخر.","لا تنزع أبدًا قفل LOTO أو بطاقته الخاصة بشخص آخر، ولا تشغّل جهازًا عليه بطاقة؛ فلا ينزع القفل إلا من وضعه."],activity:{prompt:"في أثناء المناوبة الليلية يستدعيك عامل النظافة إلى الممر: أحد مرافقي مريض ممدّد على أرضية مبلّلة قرب مقبس جداري، وما زال يمسك كابل مدفأة كهربائية. ماذا تفعل؟",options:[{text:"أُبعد الجميع، وأفصل التيار من القاطع أو القابس دون لمسه أو لمس الماء، وأطلب المساعدة، ثم أقيّم ABC",correct:!0,feedback:"صحيح: يُفصل التيار أولًا من دون لمس المصاب أو الأرضية المبلّلة؛ وبعد ذلك فقط يصبح تقييمه آمنًا وبدء CPR إذا لزم."},{text:"أسحبه من ملابسه، لأن القماش لا يوصل الكهرباء",correct:!1,feedback:"خطير: الملابس والأرضية المبلّلة توصل التيار إليك؛ لا تلمسه قبل فصل التيار."},{text:"أبدأ ضغطات الصدر فورًا، لأن كل ثانية مهمة في توقّف القلب",correct:!1,feedback:"ليس بعد: ما دام التيار موصولًا فإن لمسه يجعلك جزءًا من الدائرة؛ افصل التيار أولًا، ثم قيّم وابدأ CPR إذا لزم."},{text:"أنتظر الكهربائي من بعيد قبل أن أفعل أي شيء",correct:!1,feedback:"بطيء جدًا: إذا أمكن الوصول إلى القاطع أو القابس بأمان، فافصل التيار بنفسك واطلب المساعدة في الوقت نفسه؛ فقد يكون قلبه متوقّفًا."}]}},{id:10,code:"HAZ-10",icon:"Biohazard",accent:"#16a34a",category:"السلامة",title:"النفايات الطبية الخطرة",subtitle:"النفايات المُعدية، والأدوات الحادة (Sharps)، والنفايات السامّة للخلايا (Cytotoxic)، ومعيار OSHA للأمراض المنقولة بالدم",summary:"وفق منظمة الصحة العالمية (WHO)، نحو 85% من نفايات المستشفيات نفايات عامة غير خطرة، ونحو 15% نفايات خطرة: مُعدية أو سامّة أو كيميائية أو مشعّة. ووفق معيار OSHA للعوامل الممرضة المنقولة بالدم (29 CFR 1910.1030) وإرشادات WHO، يجب فرز النفايات فرزًا صحيحًا في موضع إنتاجها. وقد يؤدي الخطأ في الفرز إلى 1) عدوى مثل HIV وHBV وHCV، 2) مخالفة قانونية، 3) ضرر بيئي. ووخز الإبرة (Needlestick) من أكثر المخاطر شيوعًا بين العاملين في الرعاية الصحية.",facts:[{label:"النفايات الخطرة",value:"نحو 15% (WHO)"},{label:"النفايات العامة",value:"نحو 85% (WHO)"},{label:"العلاج الوقائي (PEP) لفيروس HIV",value:"في أسرع وقت ممكن، وحتى 72 ساعة"},{label:"المعيار",value:"OSHA 29 CFR 1910.1030"}],steps:[{title:"فئات النفايات وفرزها",detail:`النفايات المُعدية: الدم وسوائل الجسم ومزارع المختبر.
• الأدوات الحادة (Sharps): الإبر والمشارط والزجاج المكسور، في حاويات صلبة.
• النفايات السامّة للخلايا (Cytotoxic): أدوية علاج السرطان (chemo).
• الأدوية منتهية الصلاحية (Pharmaceutical).
• الكيميائية: الفورمالين (Formalin) والزئبق.
• المشعّة: وفق أنظمة خاصة.
• النفايات العامة غير الخطرة.
وتتبع ألوان الأكياس والحاويات الترميز المعتمد لدى وزارة الصحة والمستشفى.`,critical:!0},{title:"معدات الوقاية الشخصية (PPE) اللازمة للعمل",detail:"قفازات النتريل (Nitrile) بسبب حساسية اللاتكس (Latex)، والكمامة (جراحية أو N95 بحسب الخطورة)، والنظارات الواقية أو واقي الوجه (Face Shield)، ورداء واقٍ للاستعمال مرة واحدة، وأحذية مغلقة. وللأدوية السامّة للخلايا (Cytotoxic): زوجان من قفازات العلاج الكيميائي (chemo) الخاصة ورداء العلاج الكيميائي.",critical:!0},{title:"وخز الإبرة (Needlestick) — الخطوات الفورية",detail:"1. اغسل موضع الإصابة فورًا بالماء والصابون (لا بالكحول ولا بمحلول الكلور المبيِّض). 2. اترك الدم يخرج من تلقاء نفسه، لكن لا تعصر الجرح بقوة ولا تمصّه. 3. أبلغ فورًا مسؤولك وقسم صحة العاملين (Occupational Health). 4. إذا لزم العلاج الوقائي بعد التعرّض (PEP) لفيروس HIV، فابدأه في أسرع وقت ممكن، ويُفضّل خلال ساعات قليلة، وليس بعد 72 ساعة؛ ومدة العلاج 28 يومًا. 5. فحوص HIV وHBV وHCV في البداية، ثم وفق جدول قسم صحة العاملين.",critical:!0},{title:"انسكاب المواد الخطرة — خمس خطوات",detail:"1. أبعد الأشخاص عن المنطقة. 2. ارتدِ PPE. 3. اقرأ صحيفة بيانات السلامة (SDS) الخاصة بالمادة. 4. استخدم عُدّة الانسكاب (Spill Kit)، وفيها مادة ماصّة ومطهّرة. 5. بعد التنظيف، جدّد هواء المنطقة واكتب التقرير. ولانسكاب الأدوية السامّة للخلايا (Cytotoxic): فريق الصيدلية المختص وفق البروتوكول.",critical:!0},{title:"حاوية الأدوات الحادة (Sharps Container)",detail:"حاوية صلبة لا تستطيع الإبرة ثقبها. عندما يمتلئ ثلاثة أرباعها، أغلقها واستبدلها، ولا تملأها أكثر من ذلك. لا تُعِد غطاء الإبرة إليها (Recapping ممنوع). ويجب أن تكون الحاوية قريبة من مكان العمل وعلى ارتفاع مناسب."},{title:"الأدوية السامّة للخلايا (Cytotoxic) لعلاج السرطان",detail:"هذه الأدوية خطرة على العاملين أيضًا. معيار USP 800: زوجان من قفازات العلاج الكيميائي (chemo، ASTM D6978)، ورداء العلاج الكيميائي، وعند وجود خطر رذاذ أو غبار: حماية العينين والوجه وN95. وعُدّة انسكاب (Spill Kit) خاصة بأدوية العلاج الكيميائي. ويجب الإبلاغ عن كل تعرّض (exposure)."}],reference:[{heading:"ألوان النفايات (نموذج WHO)",points:["تختلف الألوان من بلد إلى آخر؛ فالتزم بترميز وزارة الصحة ومستشفاك.","أصفر: النفايات المُعدية.","أصفر مع علامة الأدوات الحادة (Sharps): حاويات صلبة لها.","بنّي: النفايات الكيميائية والدوائية.","النفايات السامّة للخلايا (Cytotoxic): علامة خاصة (بنفسجية في كثير من الأحيان).","المشعّة: علامة الإشعاع وحاوية خاصة.","أسود: النفايات العامة غير الخطرة."]},{heading:"وخز الإبرة (Needlestick) — الخطوات الأولى",points:["الغسل الفوري بالماء والصابون.","لا تعصر الجرح بقوة ولا تمصّه.","الإبلاغ الفوري إلى قسم صحة العاملين (Occupational Health).","العلاج الوقائي بعد التعرّض (PEP) لفيروس HIV: في أسرع وقت ممكن، وحتى 72 ساعة، لمدة 28 يومًا.","فحوص HIV وHBV وHCV في البداية.","فحوص المتابعة وفق جدول قسم صحة العاملين (Occupational Health)."]},{heading:"PPE بحسب مستوى الخطورة",points:["الاحتياطات القياسية (Standard): القفازات، والكمامة والنظارات عند وجود خطر الرذاذ.","احتياطات التلامس (Contact): + رداء واقٍ (gown).","احتياطات الرذاذ (Droplet): + كمامة جراحية.","احتياطات الانتقال الهوائي (Airborne): + N95 وغرفة الضغط السلبي.","الأدوية السامّة للخلايا (Cytotoxic): + زوجان من القفازات ورداء العلاج الكيميائي (chemo).","BSL-3: + N95 أو جهاز التنفس المزوّد بمروحة (PAPR) بحسب تقييم المخاطر."]}],warnings:["لا تُعِد غطاء الإبرة إليها (Recapping)؛ فهذا من أكثر أسباب وخز الإبر شيوعًا. لا تملأ حاوية الأدوات الحادة (Sharps) أكثر من ثلاثة أرباعها. ولا يُنظَّف انسكاب الأدوية السامّة للخلايا (Cytotoxic) إلا بفريق مدرَّب وعُدّة انسكاب (Spill Kit) خاصة. وافرز النفايات وفق ترميز الألوان المعتمد في المستشفى."],realCase:"حالة عملية (مثال تعليمي): أعاد ممرض غطاء الإبرة بعد سحب الدم، فوخزت الإبرة إصبعه. وكان المريض مصابًا بفيروس التهاب الكبد C (HCV-positive). فغسل الممرض موضع الإصابة فورًا بالماء والصابون، وأبلغ قسم صحة العاملين (Occupational Health) خلال أول 45 دقيقة. ولا يوجد علاج وقائي بعد التعرّض (PEP) لفيروس HCV، ولذلك أُجريت فحوص المتابعة. فكان الفحص الأول سلبيًا، لكنّ فحصًا لاحقًا جاء إيجابيًا. فأُعطي العلاج المضادّ للفيروسات (DAA) وشُفي الممرض. الدرس المستفاد: إعادة غطاء الإبرة (Recapping) ممنوعة، والإبلاغ الفوري يضمن بدء المتابعة.",caseStudy:[{prompt:"أنت ممرض. بعد سحب الدم، وبسبب العجلة والعادة، تعيد غطاء الإبرة فتخز الإبرة إصبعك. ما الخطوة الأولى؟",options:[{text:"لا أفعل شيئًا؛ فالجرح صغير",correct:!1,feedback:"خطير: تعرّض لفيروسات HIV وHBV وHCV."},{text:"أغسل الجرح بالكحول",correct:!1,feedback:"المطلوب الماء والصابون، لا الكحول."},{text:"أغسل الجرح فورًا بالماء والصابون وأترك الدم يخرج من تلقاء نفسه، دون عصر",correct:!0,feedback:"صحيح: هذه الخطوة الأولى. ثم الإبلاغ الفوري، حتى يُبدأ العلاج الوقائي بعد التعرّض (PEP) في أسرع وقت ممكن إذا لزم."},{text:"أعيد غطاء الإبرة وأرميها في حاوية الأدوات الحادة (Sharps)",correct:!1,feedback:"إعادة غطاء الإبرة (Recapping) ممنوعة."}]},{prompt:"غُسل الجرح. ما الخطوة الثانية؟",options:[{text:"أذهب إلى المنزل",correct:!1,feedback:"غير صحيح: يلزم التقييم والمتابعة."},{text:"أُبلغ قسم صحة العاملين (Occupational Health) فورًا، وأكتب التقرير، ويُطلب فحص HIV وHBV وHCV للمريض المصدر (Source Patient)",correct:!0,feedback:"صحيح: يتيح التقييم الفوري بدء العلاج الوقائي (PEP) في أسرع وقت ممكن إذا لزم."},{text:"أضع قطعة قماش عليه وأواصل العمل",correct:!1,feedback:"الإبلاغ ضروري."},{text:"أنتظر حتى الأسبوع القادم",correct:!1,feedback:"متأخر جدًا: لا يُوصى عمومًا بالعلاج الوقائي (PEP) بعد 72 ساعة."}]},{prompt:"المريض مصاب بفيروس HIV (HIV-positive). ويوصي قسم صحة العاملين (Occupational Health) بالعلاج الوقائي بعد التعرّض (PEP). ماذا تفعل؟",options:[{text:"أرفض لأنّ الجرح صغير",correct:!1,feedback:"خطر HIV قائم؛ والعلاج الوقائي (PEP) يقلّل الخطر تقليلًا واضحًا."},{text:"أقبل العلاج الوقائي (PEP) وأتناوله كاملًا لمدة 28 يومًا، وأُجري فحوص المتابعة",correct:!0,feedback:"صحيح: العلاج الوقائي (PEP) والمتابعة وفق إرشادات CDC وUSPHS."},{text:"أتناول العلاج الوقائي (PEP) لمدة أسبوع واحد فقط",correct:!1,feedback:"يلزم إكمال المدة كاملة 28 يومًا."},{text:"أوقف العلاج الوقائي (PEP) قبل ظهور نتائج الفحوص",correct:!1,feedback:"غير صحيح: يستمر العلاج الوقائي (PEP) وفق قرار الطبيب."}]}],quiz:[{question:"متى تُغلق حاوية الأدوات الحادة (Sharps) وتُستبدل؟",options:[{text:"عندما تمتلئ تمامًا حتى الحافة",correct:!1,feedback:"خطير: تبرز الإبر من الحاوية."},{text:"عندما يمتلئ ثلاثة أرباعها",correct:!0,feedback:"صحيح: وفق إرشادات منظمة الصحة العالمية (WHO)."},{text:"عندما يمتلئ نصفها",correct:!1,feedback:"هذا مبكر جدًا، فتُستهلك الحاويات دون حاجة."},{text:"في أي وقت تريده",correct:!1,feedback:"التعليمات تقول: ثلاثة أرباع."}]},{question:"لماذا تُمنع إعادة غطاء الإبرة (Recapping)؟",options:[{text:"لأنه يستغرق وقتًا طويلًا في المناوبات المزدحمة",correct:!1,feedback:"السبب هو الخطر، لا الوقت."},{text:"لأنه من أكثر أسباب وخز الإبر شيوعًا",correct:!0,feedback:"صحيح: لا تُعِد غطاء الإبرة إليها."},{text:"لأنه مكلف",correct:!1,feedback:"ليست الكلفة هي السبب: فإعادة غطاء الإبرة من أكثر أسباب وخز الإبر شيوعًا."},{text:"لأنه يُتلف رأس الإبرة ويُضعف فعاليتها",correct:!1,feedback:"غير صحيح؛ السبب هو سلامة العاملين."}],explanation:"تُمنع إعادة غطاء الإبرة (Recapping) لأنها من أكثر أسباب وخز الإبر شيوعًا؛ ضع الإبر المستعملة مباشرةً في حاوية الأدوات الحادة (Sharps) الصلبة."},{question:"متى يُبدأ العلاج الوقائي (PEP) لفيروس HIV بعد التعرّض؟",options:[{text:"خلال أول ساعتين فقط بعد التعرّض؛ ولا فائدة منه بعد ذلك",correct:!1,feedback:"غير صحيح: كلما كان أبكر كان أفضل، لكن يمكن بدء العلاج الوقائي (PEP) حتى 72 ساعة."},{text:"في أسرع وقت ممكن، ويُفضّل خلال ساعات قليلة، وحتى 72 ساعة",correct:!0,feedback:"صحيح: وفق إرشادات USPHS 2025."},{text:"بعد أسبوع",correct:!1,feedback:"متأخر جدًا."},{text:"التوقيت غير مهم",correct:!1,feedback:"غير صحيح: فكل تأخير يُنقص الفعالية."}]},{question:"أيّ قفازات تُستخدم مع الأدوية السامّة للخلايا (Cytotoxic)؟",options:[{text:"زوج واحد من قفازات الفحص السميكة من اللاتكس (Latex)",correct:!1,feedback:"اللاتكس (Latex) يسبّب الحساسية، وزوج واحد لا يكفي."},{text:"زوجان من قفازات العلاج الكيميائي (ASTM D6978)",correct:!0,feedback:"صحيح: USP 800."},{text:"من دون قفازات",correct:!1,feedback:"خطير."},{text:"زوجان من قفازات الفينيل (Vinyl) تُبدَّل كل 30 دقيقة",correct:!1,feedback:"قد تنفذ الأدوية عبر قفازات الفينيل (Vinyl)."}]},{question:"بينما يربط عامل النظافة كيس النفايات العامة الأسود، يرى إبرة بارزة من البلاستيك. ما التصرّف الصحيح؟",options:[{text:"لا يلمس الإبرة، ويعزل الكيس ويبلّغ المسؤول عنه",correct:!0,feedback:"صحيح: وجود إبرة في النفايات العامة خطأ في الفرز؛ والتعامل معها باليد يعرّض لخطر الوخز."},{text:"يسحب الإبرة باليد ويرميها في أقرب حاوية للأدوات الحادة",correct:!1,feedback:"غير صحيح: سحب الإبرة باليد هو بالضبط ما يسبّب إصابات الوخز."},{text:"يدفع الإبرة إلى الداخل ويربط الكيس بإحكام أكبر كي لا يُوخز أحد",correct:!1,feedback:"غير صحيح: دفعها باليد يعرّضه للوخز الآن، وتبقى الإبرة خطرًا على عمّال النفايات لاحقًا."},{text:"يتركها، لأن الكيس يذهب إلى النفايات العامة ولا يفتحه أحد",correct:!1,feedback:"غير صحيح: يتعامل الحمّالون وعمّال النفايات مع الكيس؛ وقد تجرحهم إبرة مخفية."}],explanation:"تُفرز النفايات في موضع نشوئها. والإبرة في الكيس العام خطر على كل من يحمل الكيس: لا تلمسها، واعزل الكيس وأبلغ."},{question:"ينشقّ كيس نفايات العلاج الكيميائي (chemo) على أرضية قسم الأورام. ماذا تفعل؟",options:[{text:"أُبعد الناس وأستدعي الفريق المدرَّب مع عُدّة انسكاب العلاج الكيميائي المخصّصة",correct:!0,feedback:"صحيح: لا ينظّف انسكاب المواد السامّة للخلايا إلا فريق مدرَّب بعُدّة انسكاب مخصّصة."},{text:"أمسحه بسرعة بمناديل ورقية مرتديًا زوجًا واحدًا من القفازات",correct:!1,feedback:"غير صحيح: الأدوية السامّة للخلايا خطرة على العاملين أيضًا؛ والقفازات والمناديل العادية لا تحميك."},{text:"أمسحه بممسحة القسم المعتادة ومطهّر، ثم أعيد الممسحة إلى مكانها",correct:!1,feedback:"غير صحيح: تنشر الممسحة الدواء في أرجاء القسم وتلوّث المكان التالي الذي تلمسه."},{text:"أغطّيه بشرشف وأتركه لعمّال النظافة في آخر المناوبة",correct:!1,feedback:"غير صحيح: قد يدوس عليه الناس، ويتعرّض عمّال النظافة غير المدرَّبين للخطر."}],explanation:"الأدوية السامّة للخلايا خطرة على العاملين أيضًا. ولا ينظّف انسكابها إلا فريق مدرَّب بمعدات وقاية خاصة وعُدّة انسكاب العلاج الكيميائي، ويُبلَّغ عن كل تعرّض."}],tips:["ضع حاوية الأدوات الحادة (Sharps) في متناول يدك حيث تستخدم الإبرة، كي لا تحمل إبرة مستعملة عبر الغرفة أبدًا.","انظر إلى خط الامتلاء قبل كل استخدام؛ وعند ثلاثة أرباعه أغلق الحاوية واطلب حاوية جديدة.","قرّر الكيس المناسب قبل أن ترمي النفايات، وفق ترميز الألوان في مستشفاك؛ فالكيس الخطأ لا يمكن فرزه بأمان لاحقًا.","اعرف مكان عُدّة الانسكاب (Spill Kit) في قسمك، وكيف تصل إلى قسم الصحة المهنية (Occupational Health) في كل مناوبة."],activity:{prompt:"وخزت ممرضة إصبعها بإبرة مستعملة بعد إعطاء حقنة. تقول إنها وخزة صغيرة فقط، وتريد إنهاء جولة الأدوية قبل أي شيء. بماذا تنصحها؟",options:[{text:"تغسلها الآن بالماء والصابون وتبلّغ فورًا المشرف وقسم الصحة المهنية",correct:!0,feedback:"صحيح: الغسل والإبلاغ الفوري يتيحان لقسم الصحة المهنية تقييم الخطر مبكرًا؛ وإذا لزم PEP فكلما بدأ أبكر كان أفضل."},{text:"تعصر إصبعها بقوة وتنظّفه بالكحول، ثم تُنهي الجولة",correct:!1,feedback:"غير صحيح: لا عصر بقوة ولا كحول؛ تغسل بالماء والصابون وتبلّغ دون تأخير."},{text:"تُنهي الجولة أولًا، وتبلّغ في آخر المناوبة إذا شعرت بتوعّك",correct:!1,feedback:"غير صحيح: العدوى بعد وخز الإبرة لا تُظهر أعراضًا في البداية؛ وتأخير الإبلاغ يؤخّر PEP إن كان لازمًا."},{text:"تبلّغ فقط إذا جاءت نتيجة فحص دم المريض إيجابية لاحقًا",correct:!1,feedback:"غير صحيح: يُبلَّغ عن كل تعرّض فورًا؛ وانتظار النتائج قد يؤخّر بدء PEP إلى ما بعد الوقت الذي يفيد فيه."}]}},{id:11,code:"LAB-11",icon:"Microscope",accent:"#0d9488",category:"السلامة",title:"السلامة في المختبر",subtitle:"مستويات BSL، وانسكاب المواد، وغسل العيون (Eyewash)، وخزانة الأبخرة (Fume Hood)",summary:"تحتوي مختبرات المستشفى على مواد خطرة: كيميائية (أحماض، وقواعد، ومذيبات)، وبيولوجية (بكتيريا، وفيروسات، وفطريات)، وفيزيائية (زجاج، وضغط، وحرارة). ووفق CDC BMBL (Biosafety in Microbiological and Biomedical Laboratories) وOSHA 29 CFR 1910.1450، هناك أربعة مستويات للسلامة الحيوية (BSL). وتعمل معظم المختبرات السريرية في المستشفيات بمستوى BSL-2، وبعض الأعمال (مثل مزرعة TB) تحتاج إلى BSL-3. ويُعدّ تطاير المواد إلى العينين خطرًا مهمًا، ولذلك يجب أن تكون محطة غسل العيون (Eyewash) قريبة وخالية من العوائق (ANSI Z358.1).",facts:[{label:"مستويات BSL",value:"أربعة مستويات (من BSL-1 إلى BSL-4)"},{label:"المختبر السريري",value:"BSL-2 عمومًا؛ وبعض الأعمال BSL-3"},{label:"الوصول إلى محطة غسل العيون",value:"خلال 10 ثوانٍ (ANSI Z358.1)"},{label:"مدة غسل العينين",value:"15 دقيقة على الأقل"}],steps:[{title:"مستويات BSL الأربعة",detail:"BSL-1: مواد لا تسبّب المرض لدى البشر الأصحّاء (مثل E. coli K-12). BSL-2: خطورة متوسطة (Salmonella، HBV، HIV)؛ ومعظم المختبرات السريرية. BSL-3: مواد خطرة تنتقل عبر الهواء (مزرعة TB ومزرعة SARS-CoV-2). BSL-4: أشدّ المواد فتكًا (Ebola، Marburg). ولكل مستوى PPE ومعدات حماية خاصة به.",critical:!0},{title:"PPE للعمل",detail:"في الحالات العادية: قفازات النتريل (Nitrile)، ومعطف المختبر (Lab Coat)، ونظارات واقية. وعند وجود خطر الرذاذ: + واقي الوجه (Face Shield). وإذا تولّد الهباء الجوي (aerosol): العمل داخل خزانة السلامة الحيوية (Biosafety Cabinet)، وN95 أو جهاز التنفس المزوّد بمروحة (PAPR) بحسب تقييم المخاطر. وللأدوية السامّة للخلايا (Cytotoxic): زوجان من القفازات ورداء العلاج الكيميائي (chemo).",critical:!0},{title:"خزانة الأبخرة (Fume Hood) — الاستخدام الصحيح",detail:"أبقِ الواجهة الزجاجية (sash) عند الارتفاع المعلَّم، لا مفتوحة بالكامل. افحص مؤشّر تدفّق الهواء قبل العمل؛ وسرعة الهواء عند واجهة خزانة الأبخرة (hood) تبلغ عمومًا نحو 0.4–0.6 m/s. ضع المواد على عمق 15 سم على الأقل داخل الخزانة. وتُفحص الخزانة وتُعتمد سنويًا. والخزانة ليست مكانًا لتخزين المواد؛ بل للعمل فقط.",critical:!0},{title:"الانسكاب الكيميائي",detail:"1. أبعد الأشخاص عن المنطقة. 2. ارتدِ PPE (نظارات مضادّة للرذاذ وقفازات مقاومة للأحماض). 3. اقرأ صحيفة بيانات السلامة (SDS). 4. عُدّة الانسكاب (Spill Kit): للأحماض بيكربونات الصوديوم (Sodium Bicarbonate)؛ وللقواعد حمض الستريك (Citric Acid)؛ وللمذيبات مادة ماصّة أو الكربون المنشّط (Activated Carbon). 5. الزئبق (Mercury): عُدّة الزئبق (Mercury Kit) الخاصة فقط؛ لا تنظّفه بالمكنسة أو بالمكنسة الكهربائية (Vacuum). 6. اكتب التقرير وجدّد هواء المنطقة.",critical:!0},{title:"محطة غسل العيون (Eyewash) ودش الطوارئ (Safety Shower)",detail:"يجب الوصول إلى محطة غسل العيون (Eyewash) خلال 10 ثوانٍ (نحو 17 مترًا)، في الطابق نفسه ومن دون عوائق (ANSI Z358.1). اغسل العينين بالماء 15 دقيقة على الأقل، وكلتيهما إذا أصابهما الرذاذ معًا، وافتح الجفنين. دش الطوارئ (Safety Shower): حدّ الوصول نفسه و15 دقيقة على الأقل. شغّل محطة غسل العيون والدش أسبوعيًا لتجديد الماء والتأكد من أنهما يعملان.",critical:!0},{title:"الزجاج المكسور والأدوات الحادة",detail:"لا تجمع الزجاج المكسور بيديك؛ استخدم ملقطًا أو مكنسة ومجرفة. يوضع الزجاج المكسور في حاوية الزجاج الخاصة، وماصّات باستور (Pasteur pipettes) والإبر في حاوية الأدوات الحادة (Sharps). ولا ترمِ الزجاج المكسور مع النفايات العامة."}],reference:[{heading:"BSL في مختبر المستشفى",points:["BSL-2: HIV، HBV، HCV، Salmonella.","PPE: القفازات ومعطف المختبر (Lab Coat) والنظارات الواقية.","معدات الحماية: خزانة السلامة الحيوية من الفئة الثانية (BSC Class II).","القواعد: يُمنع الأكل والشرب ووضع مستحضرات التجميل في المختبر.","BSL-3: مزرعة السل (TB)، وفطر الهستوبلازما (Histoplasma).","PPE: + حماية تنفّسية (N95 أو PAPR) وغرفة الضغط السلبي."]},{heading:"المخاطر الكيميائية",points:["القابلة للاشتعال: الإيثانول (Ethanol)، الأسيتون (Acetone)، الإيثر (Ether).","الأحماض: HCl، H₂SO₄، حمض الأسيتيك (Acetic Acid).","القواعد: NaOH، KOH، الأمونيا (Ammonia).","السامّة: الزئبق، السيانيد (Cyanide)، الفورمالديهايد (Formaldehyde).","النشطة كيميائيًا (Reactive): الصوديوم (Sodium)، البيروكسيدات (Peroxides).","المؤكسِدة: محلول الكلور المبيِّض (Bleach)، بيروكسيد الهيدروجين (Hydrogen Peroxide)."]},{heading:"غسل العيون (Eyewash) — 15 دقيقة",points:["الرذاذ الكيميائي: 15 دقيقة على الأقل.","قد تحتاج القواعد القوية إلى غسل أطول؛ راجع صحيفة بيانات السلامة (SDS) وأبلغ الطبيب.","انزع العدسات اللاصقة في أثناء الغسل إذا كان نزعها سهلًا.","افتح الجفنين حتى يصل الماء إلى العين كلها.","اغسل العينين كلتيهما إذا أصابهما الرذاذ معًا.","بعد ذلك: قسم صحة العاملين (Occupational Health) وطبيب العيون."]}],warnings:["يُمنع الأكل والشرب ووضع مستحضرات التجميل في المختبر. لا تنظّف الزئبق (Mercury) بالمكنسة أو بالمكنسة الكهربائية (Vacuum)؛ استخدم عُدّة الزئبق (Mercury Kit) الخاصة فقط. افحص محطة غسل العيون (Eyewash) أسبوعيًا. ولا تعمل خزانة الأبخرة (Fume Hood) كما ينبغي إذا كانت الواجهة الزجاجية مفتوحة بالكامل؛ اعمل عند الارتفاع المعلَّم."],realCase:"حالة عملية (مثال تعليمي): كان فنّي مختبر يعمل بحمض H₂SO₄ بتركيز 98% من دون نظارات واقية. فسقطت الزجاجة وتطاير الحمض إلى عينه. فاقتاده أحد زملائه فورًا إلى محطة غسل العيون (Eyewash)، وغُسلت عيناه بالماء 15 دقيقة مع فتح الجفنين. ووصل فريق صحة العاملين (Occupational Health) بعد 20 دقيقة، وفحصه طبيب العيون بعد ساعة. وبعد أسبوعين من العلاج تعافت عينه. الدرس المستفاد: النظارات الواقية ضرورية عند العمل بالأحماض، ويجب أن تكون محطة غسل العيون قريبة وخالية من العوائق.",caseStudy:[{prompt:"أنت فنّي مختبر. في أثناء تشغيل جهاز الطرد المركزي (Centrifuge) ينكسر أنبوب وينتشر الدم داخل الجهاز. ترتدي القفازات، لكنك لا ترتدي رداء الحماية. ما الخطوة الأولى؟",options:[{text:"أفتح الجهاز فورًا وأنظّفه",correct:!1,feedback:"يلزم PPE كامل، وهناك خطر الهباء الجوي (aerosol)."},{text:"أوقف جهاز الطرد المركزي (Centrifuge) وأُبقي غطاءه مغلقًا، وأنتظر 30 دقيقة، وأرتدي PPE كاملًا وأجهّز عُدّة الانسكاب (Spill Kit)",correct:!0,feedback:"صحيح: وفق إرشادات السلامة الحيوية، يتيح الانتظار 30 دقيقة للهباء الجوي (aerosol) أن يترسّب."},{text:"أفتح غطاء جهاز الطرد المركزي (Centrifuge) لأرى ما حدث",correct:!1,feedback:"خطير: ينتشر الهباء الجوي (aerosol)."},{text:"لا أفعل شيئًا",correct:!1,feedback:"خطير ويُعدّ مخالفة."}]},{prompt:"بعد 30 دقيقة، فُتح جهاز الطرد المركزي (Centrifuge)، وعُدّة الانسكاب (Spill Kit) جاهزة. ما الخطوة الثانية؟",options:[{text:"التنظيف بمحلول كلور مبيِّض (bleach) مخفّف بنسبة 1:10 (أو مطهّر معتمد)",correct:!0,feedback:"صحيح: محلول الكلور المبيِّض (bleach) بنسبة 1:10 لانسكاب الدم."},{text:"التنظيف بالماء فقط",correct:!1,feedback:"من دون مطهّر يبقى الخطر قائمًا."},{text:"بالفرشاة فقط",correct:!1,feedback:"المطهّر ضروري."},{text:"أوقف العمل وأتركه لشخص آخر",correct:!1,feedback:"أنت مدرَّب ومستعد؛ أكمل العمل على الوجه الصحيح."}]},{prompt:"انتهى التنظيف. ما الخطوة الثالثة؟",options:[{text:"أكتب تقرير الحادث (Incident Report) وأفحص نفسي وPPE الخاصة بي",correct:!0,feedback:"صحيح: التوثيق وفحص النفس بحثًا عن أي تعرّض."},{text:"لا أفعل شيئًا؛ فالتنظيف يكفي",correct:!1,feedback:"تقرير الحادث ضروري."},{text:"أغادر المختبر",correct:!1,feedback:"ليس قبل كتابة التقرير."},{text:"أبدأ فورًا بأنبوب آخر",correct:!1,feedback:"ليس قبل فحص الجهاز."}]}],quiz:[{question:"بأيّ مستوى BSL يعمل المختبر السريري في المستشفى عمومًا؟",options:[{text:"BSL-1 لجميع العيّنات الروتينية للمرضى",correct:!1,feedback:"BSL-1 للمواد غير الخطرة (مثل E. coli K-12)."},{text:"BSL-2، وبعض الأعمال BSL-3",correct:!0,feedback:"صحيح: HIV وHBV في BSL-2؛ ومزرعة TB في BSL-3."},{text:"BSL-4 لكل الأعمال على عيّنات الدم",correct:!1,feedback:"BSL-4 لفيروس إيبولا (Ebola)، ويقتصر على مختبرات متخصّصة."},{text:"BSL-0",correct:!1,feedback:"لا يوجد مستوى كهذا."}]},{question:"ما مدة غسل العينين بعد الرذاذ الكيميائي؟",options:[{text:"دقيقتان",correct:!1,feedback:"قليلة جدًا."},{text:"15 دقيقة على الأقل",correct:!0,feedback:"صحيح: ANSI Z358.1."},{text:"5 دقائق",correct:!1,feedback:"قليلة."},{text:"حتى يزول الألم",correct:!1,feedback:"غير صحيح؛ 15 دقيقة على الأقل."}]},{question:"انسكاب الزئبق (Mercury)؛ ماذا تستخدم؟",options:[{text:"المكنسة العادية لجمع القطرات",correct:!1,feedback:"غير صحيح: تتناثر قطرات الزئبق وتتحوّل إلى بخار."},{text:"عُدّة الزئبق الخاصة (Mercury Kit)",correct:!0,feedback:"صحيح: مثل مسحوق الكبريت (Sulfur) أو الزنك (Zinc) الذي يرتبط بالزئبق."},{text:"الماء والصابون",correct:!1,feedback:"لا يجدي نفعًا."},{text:"المكنسة الكهربائية (Vacuum cleaner)",correct:!1,feedback:"خطير: يتحوّل الزئبق إلى بخار وينتشر."}]},{question:"بعد انكسار أنبوب داخل جهاز الطرد المركزي (Centrifuge)، كم تنتظر قبل فتحه؟",options:[{text:"أفتحه فورًا",correct:!1,feedback:"خطر الهباء الجوي (aerosol)."},{text:"30 دقيقة",correct:!0,feedback:"صحيح: يترسّب الهباء الجوي (aerosol)."},{text:"5 دقائق",correct:!1,feedback:"قليلة."},{text:"24 ساعة",correct:!1,feedback:"كثيرة جدًا."}]},{question:"بينما تعمل في خزانة الأبخرة (Fume Hood)، يُظهر مؤشّر تدفّق الهواء تدفّقًا منخفضًا. ماذا تفعل؟",options:[{text:"أوقف العمل، وأغلق الأوعية، وأخفض الواجهة الزجاجية وأبلّغ عن الخزانة",correct:!0,feedback:"صحيح: مع انخفاض التدفّق لم تعد الخزانة تحميك؛ توقّف وأبلغ."},{text:"أرفع الواجهة الزجاجية بالكامل ليدخل هواء أكثر إلى الخزانة",correct:!1,feedback:"غير صحيح: الواجهة المفتوحة بالكامل تجعل الخزانة تعمل بشكل أسوأ لا أفضل."},{text:"أتابع العمل، لأن الخزانة اجتازت فحصها السنوي",correct:!1,feedback:"غير صحيح: المؤشّر يبيّن حالة الخزانة الآن؛ والفحص السابق لا يحميك اليوم."},{text:"أنقل العمل خارج الخزانة وأُنهيه على الطاولة المكشوفة",correct:!1,feedback:"غير صحيح: لا يُنقل عمل يحتاج إلى خزانة أبخرة إلى طاولة مكشوفة أبدًا، حيث تصل إليك الأبخرة مباشرة."}],explanation:"لا تحمي خزانة الأبخرة إلا إذا كان تدفّق الهواء سليمًا والواجهة عند الارتفاع المعلَّم. مؤشّر تدفّق منخفض = توقّف وإبلاغ."},{question:"ينكسر كأس زجاجي (beaker) على طاولة العمل. كيف تُجمع القطع؟",options:[{text:"بالملقط أو بالمكنسة والمجرفة، في الحاوية المخصّصة للزجاج المكسور",correct:!0,feedback:"صحيح: لا يُجمع الزجاج المكسور باليد، بل يوضع في حاوية الزجاج المخصّصة."},{text:"ألتقط القطع الكبيرة بحذر باليد مع ارتداء القفازات",correct:!1,feedback:"غير صحيح: قد يخترق الزجاج القفاز؛ استخدم الملقط أو المكنسة والمجرفة."},{text:"ألفّ القطع بالورق وأضعها في سلة النفايات العامة",correct:!1,feedback:"غير صحيح: لا يوضع الزجاج المكسور في النفايات العامة؛ فهو يجرح عمّال النفايات."},{text:"أكنسها تحت الطاولة وأتركها لعمّال النظافة",correct:!1,feedback:"غير صحيح: القطع المخفية تجرح شخصًا آخر لاحقًا؛ اجمعها فورًا وبالطريقة الصحيحة."}],explanation:"يُجمع الزجاج المكسور بالملقط أو بالمكنسة والمجرفة ويوضع في حاوية الزجاج المخصّصة؛ أما ماصّات باستور (Pasteur pipettes) والإبر ففي حاوية الأدوات الحادة."}],tips:["قبل بدء العمل، تأكّد أن الطريق إلى محطة غسل العيون (Eyewash) ودشّ الطوارئ (Safety Shower) خالٍ.","اقرأ صحيفة بيانات السلامة (SDS) للمادة الكيميائية قبل استخدامها أول مرة، واحفظها حيث يجدها الفريق.","ضع ملصقًا على كل وعاء، حتى المحلول الذي حضّرته للتو، يبيّن محتواه والتاريخ.","كُل واشرب واسترح في غرفة الموظفين فقط، لا عند طاولة العمل أبدًا."],activity:{prompt:"يتعرّض فنّي في أثناء تحضير كاشف (reagent) لرذاذ قاعدة قوية (strong base) في إحدى عينيه. يتألّم ويقول إنه سيشطفها عند المغسلة ويتابع العمل. ماذا تفعل؟",options:[{text:"آخذه إلى محطة غسل العيون وأشطف 15 دقيقة على الأقل مع إبقاء جفنيه مفتوحين",correct:!0,feedback:"صحيح: يبدأ الشطف فورًا ويستمر 15 دقيقة على الأقل؛ وقد تحتاج القواعد القوية إلى مدة أطول، لذا تحدّد SDS والطبيب الخطوة التالية."},{text:"أتركه يشطف عند المغسلة لوقت قصير ونرى هل يخفّ الألم",correct:!1,feedback:"غير صحيح: الشطف القصير لا يكفي، والألم ليس مقياسًا؛ اشطف عند محطة غسل العيون 15 دقيقة على الأقل."},{text:"أمسح العين بمنديل نظيف لإزالة المادة قبل الشطف",correct:!1,feedback:"غير صحيح: المسح أو الفرك يدفع المادة إلى داخل العين ويؤخّر الشطف."},{text:"أبحث في SDS أولًا، ثم أقرّر هل يحتاج إلى الشطف",correct:!1,feedback:"غير صحيح: الشطف أولًا ولا يحتمل الانتظار؛ ويمكن لزميل قراءة SDS في أثناء الشطف."}]}},{id:12,code:"INF-12",icon:"ShieldPlus",accent:"#0e7490",category:"السلامة",title:"مكافحة العدوى",subtitle:"اللحظات الخمس لمنظمة WHO، واحتياطات العزل، والوقاية من العدوى المرتبطة بالرعاية الصحية (HAI)",summary:"تشكّل حالات العدوى المرتبطة بالرعاية الصحية في المستشفى (HAI) خطرًا كبيرًا على المرضى. ووفق تقرير منظمة الصحة العالمية (WHO) لعام 2022، من بين كل 100 مريض في مستشفيات الرعاية الحادة، يُصاب نحو 7 في البلدان مرتفعة الدخل و15 في البلدان منخفضة ومتوسطة الدخل بعدوى HAI واحدة على الأقل؛ ويمكن الوقاية من نسبة تصل إلى 70% منها بنظافة اليدين وإجراءات الوقاية من العدوى ومكافحتها (IPC) الأخرى. ووفق اللحظات الخمس لمنظمة WHO والاحتياطات القياسية (Standard Precautions) لدى CDC، فإنّ نظافة اليدين هي أبسط الوسائل وأكثرها فعالية.",facts:[{label:"HAI (WHO 2022)",value:"7 من كل 100 (الدخل المرتفع) · 15 من كل 100 (الدخل المنخفض والمتوسط)"},{label:"الوقاية عبر مكافحة العدوى (IPC)",value:"حتى 70% (WHO)"},{label:"المعيار",value:"لحظات WHO الخمس + CDC"},{label:"مدة تنظيف اليدين",value:"الماء والصابون 40–60 ثانية · الكحول 20–30 ثانية"}],steps:[{title:"اللحظات الخمس لمنظمة WHO لنظافة اليدين",detail:"1. قبل ملامسة المريض. 2. قبل أي إجراء نظيف أو معقّم (aseptic). 3. بعد التعرّض للدم أو سوائل الجسم. 4. بعد ملامسة المريض. 5. بعد ملامسة محيط المريض.",critical:!0},{title:"تقنية تنظيف اليدين",detail:"الماء والصابون: 40–60 ثانية (عندما تكون اليدان متّسختين بوضوح). الجل الكحولي: 20–30 ثانية. خطوات منظمة الصحة العالمية (WHO): راحتا اليدين معًا، وظهر اليدين، وما بين الأصابع، وظهر الأصابع، والإبهامان، وأطراف الأصابع والأظافر، والرسغان.",critical:!0},{title:"احتياطات العزل (Isolation Precautions)",detail:"الاحتياطات القياسية (Standard): لجميع المرضى. احتياطات التلامس (Contact)، مثل MRSA وC. difficile وVRE: رداء واقٍ وقفازات. احتياطات الرذاذ (Droplet)، مثل الإنفلونزا والنكاف: كمامة جراحية. احتياطات الانتقال الهوائي (Airborne)، مثل السل (TB) والحصبة وجدري الماء: N95 وغرفة العزل ذات الضغط السلبي (AIIR) مع إغلاق الباب.",critical:!0},{title:"PPE — ترتيب الارتداء والخلع",detail:"الارتداء (Don): 1) الرداء الواقي، 2) الكمامة أو N95، 3) النظارات الواقية أو واقي الوجه (Face Shield)، 4) القفازات. الخلع (Doff): 1) القفازات، 2) النظارات الواقية، 3) الرداء الواقي، 4) الكمامة أو N95 (تُخلع N95 خارج الغرفة). نظّف يديك بعد خلع كل PPE، وكذلك بين الخطوات إذا تلوّثت يداك.",critical:!0},{title:"الكائنات الدقيقة المقاومة للأدوية المتعدّدة (MDRO)",detail:"MRSA: المكوّرات العنقودية (Staphylococcus) المقاومة لـ Methicillin. VRE: المكوّرات المعوية (Enterococcus) المقاومة لـ Vancomycin. CRE: بكتيريا مقاومة لـ Carbapenem، وهو من آخر خطوط المضادّات الحيوية. المطثية العسيرة (C. difficile): أبواغها لا يقتلها الكحول؛ ويلزم الماء والصابون. والاستخدام الرشيد للمضادّات الحيوية (Antibiotic Stewardship) يمنع ظهور هذه الكائنات.",critical:!0},{title:"الترصّد وتفشّي العدوى (Outbreak)",detail:"يجب أن يكون لكل قسم ممرض لمكافحة العدوى. وأنواع العدوى الرئيسية الأربعة: CLABSI (عدوى مجرى الدم عبر القثطار المركزي)، وCAUTI (عدوى المسالك البولية عبر القثطار البولي)، وVAP (التهاب الرئة لدى المرضى على أجهزة التنفس الاصطناعي)، وSSI (عدوى موضع الجراحة). وإذا تجاوزت الحالات المستوى المعتاد أو ظهرت عدة حالات مترابطة، فأبلغ فريق مكافحة العدوى فورًا. ويرفع المستشفى تقريره وفق بروتوكوله إلى المديرية العامة للصحة في دهوك ووزارة الصحة في إقليم كوردستان."}],reference:[{heading:"اللحظات الخمس لمنظمة WHO — للتذكير",points:["1. قبل ملامسة المريض.","2. قبل الإجراء النظيف (aseptic).","3. بعد التعرّض لسوائل الجسم.","4. بعد ملامسة المريض.","5. بعد ملامسة محيط المريض.","للتذكير: مرتان «قبل» وثلاث مرات «بعد»."]},{heading:"علامات العزل على الباب",points:["تختلف ألوان العلامات وأشكالها من مستشفى إلى آخر؛ فالتزم بخطة الوقاية من العدوى ومكافحتها (IPC) في مستشفاك.","الاحتياطات القياسية (Standard): لجميع المرضى، ولا تحتاج إلى علامة.","احتياطات التلامس (Contact): رداء واقٍ وقفازات.","احتياطات الرذاذ (Droplet): كمامة جراحية.","احتياطات الانتقال الهوائي (Airborne): N95 وغرفة الضغط السلبي (AIIR).","العزل الوقائي (Protective): حماية المرضى ضعيفي المناعة."]},{heading:"المطثية العسيرة (C. difficile) — خصائص",points:["الجل الكحولي لا يقتل الأبواغ؛ ويلزم الماء والصابون.","تنظيف الأسطح بمحلول الكلور المبيِّض (bleach) أو بمطهّرات قاتلة للأبواغ.","احتياطات التلامس (Contact Precautions) وفق خطة المستشفى (حتى 48 ساعة على الأقل بعد توقّف الإسهال).","غرفة مفردة (Single Room) بمرحاض خاص.","PPE: رداء واقٍ وقفازات دائمًا.","معدات مخصّصة للمريض (مثل السمّاعة الطبية)."]}],warnings:["الجل الكحولي لا يقتل أبواغ المطثية العسيرة (C. difficile)؛ ويلزم الماء والصابون. وقد تبقى الأبواغ أشهرًا على الأسطح والمعدات؛ فاستخدم محلول الكلور المبيِّض (bleach) أو مطهّرات قاتلة للأبواغ. ويحتاج غسل اليدين إلى 40–60 ثانية، لا 10 ثوانٍ. والخلع الخاطئ لـ PPE يؤدي إلى تلوّث الموظف نفسه."],realCase:"حالة عملية (مثال تعليمي): في قسم الأورام (Oncology) بأحد المستشفيات، أُصيب أربعة مرضى بعدوى المطثية العسيرة (C. difficile) خلال أسبوعين. فتحقّقت ممرضة مكافحة العدوى ووجدت أنّ العاملين كانوا يستخدمون الجل الكحولي فقط لا الماء والصابون، وأنّ الأسطح لم تكن تُنظَّف بمطهّر مناسب. فتحرّك فريق مكافحة العدوى فورًا: تحقيق، وإعادة تدريب، وتنظيف بمحلول الكلور المبيِّض (bleach)، ومراقبة مستمرة، ورفع تقرير إلى مديرية الصحة وفق البروتوكول. وتوقّف التفشّي خلال شهر. الدرس المستفاد: يجب أن يعرف العاملون جيدًا خصائص المطثية العسيرة واللحظات الخمس لمنظمة WHO.",caseStudy:[{prompt:"أنتِ ممرضة في ICU. يصل مريض يُشتبه بإصابته بالسل (TB)، وغرفة الضغط السلبي في القسم معطّلة. ماذا تفعلين؟",options:[{text:"أضع المريض في غرفة عادية والباب مفتوح",correct:!1,feedback:"هناك خطر انتشار العدوى عبر الهواء إلى القسم كله."},{text:"أكتفي بارتداء N95 وأبدأ العمل",correct:!1,feedback:"PPE وحدها لا تكفي؛ فالمريض يحتاج إلى غرفة ضغط سلبي."},{text:"أضع كمامة جراحية على المريض، وأضعه في غرفة مفردة مع إغلاق الباب، وأُبلغ مكافحة العدوى فورًا لنقله إلى غرفة الضغط السلبي",correct:!0,feedback:"صحيح: يحتاج مريض السل (TB) إلى غرفة العزل الهوائي (AIIR)."},{text:"أترك الباب مفتوحًا لتجديد الهواء",correct:!1,feedback:"هناك خطر انتشار العدوى عبر الهواء."}]},{prompt:"غرفة الضغط السلبي جاهزة. وأنتِ على وشك الدخول. ماذا تفعلين قبل الدخول؟",options:[{text:"أدخل فورًا",correct:!1,feedback:"PPE أولًا."},{text:"أرتدي PPE بالترتيب الصحيح: الرداء الواقي، ثم N95، ثم النظارات الواقية، ثم القفازات",correct:!0,feedback:"صحيح: تُرتدى N95 قبل الدخول ويُجرى فحص إحكام الكمامة (fit-check)."},{text:"أرتدي N95 بعد الدخول",correct:!1,feedback:"غير صحيح: يجب ارتداء N95 قبل الدخول."},{text:"كمامة جراحية فقط",correct:!1,feedback:"يحتاج مريض السل (TB) إلى N95."}]},{prompt:"انتهى العمل وأنتِ على وشك الخروج. ما الترتيب الصحيح لخلع PPE؟",options:[{text:"القفازات، ثم النظارات الواقية، ثم الرداء الواقي، ثم N95 خارج الغرفة",correct:!0,feedback:"صحيح: تُخلع N95 خارج الغرفة ثم تُنظَّف اليدان."},{text:"N95، ثم الرداء الواقي، ثم النظارات الواقية، ثم القفازات",correct:!1,feedback:"تُخلع N95 أخيرًا وفي الخارج."},{text:"أخلعها كلها معًا بسرعة",correct:!1,feedback:"هناك خطر تلويث نفسك."},{text:"أخلع القفازات فقط، ولا حاجة إلى خلع البقية",correct:!1,feedback:"يجب خلع كل PPE على الوجه الصحيح."}]}],quiz:[{question:"ما اللحظة الأولى من اللحظات الخمس لمنظمة WHO؟",options:[{text:"بعد ملامسة المريض",correct:!1,feedback:"هذه هي اللحظة الرابعة."},{text:"قبل ملامسة المريض",correct:!0,feedback:"تأتي نظافة اليدين قبل ملامسة المريض؛ واللحظات الخمس مرتان «قبل» وثلاث مرات «بعد»."},{text:"قبل الأكل",correct:!1,feedback:"هذه ليست من اللحظات الخمس لمنظمة WHO."},{text:"بعد مغادرة المستشفى",correct:!1,feedback:"ليست من اللحظات الخمس؛ فجميعها مرتبطة بالمريض أو الإجراء النظيف أو سوائل الجسم أو محيط المريض."}],explanation:"اللحظات الخمس لمنظمة WHO مرتان «قبل» وثلاث مرات «بعد»: اللحظة الأولى قبل ملامسة المريض، والرابعة بعد ملامسته."},{question:"في حالة عدوى المطثية العسيرة (C. difficile)، بماذا تُنظَّف اليدان؟",options:[{text:"الجل الكحولي",correct:!1,feedback:"لا يقتل الأبواغ."},{text:"الماء والصابون",correct:!0,feedback:"صحيح: يزيل الأبواغ بالفرك والغسل."},{text:"كلاهما سواء",correct:!1,feedback:"الجل الكحولي لا يكفي هنا."},{text:"لا حاجة إلى ذلك",correct:!1,feedback:"خطير."}]},{question:"ماذا يتطلّب العزل الهوائي (Airborne Isolation) لمريض السل (TB)؟",options:[{text:"كمامة جراحية وغرفة فردية عادية",correct:!1,feedback:"هذا لا يكفي."},{text:"N95 وغرفة الضغط السلبي",correct:!0,feedback:"ينتقل السل (TB) عبر الهواء، لذا يحتاج إلى N95 وغرفة العزل ذات الضغط السلبي (AIIR) مع إغلاق الباب."},{text:"N95 فقط",correct:!1,feedback:"الغرفة الخاصة ضرورية أيضًا."},{text:"لا حاجة إلى أي PPE",correct:!1,feedback:"خطير."}],explanation:"يتطلّب السل (TB) احتياطات الانتقال الهوائي: N95 وغرفة العزل ذات الضغط السلبي (AIIR) مع إغلاق الباب. أما الكمامة الجراحية فلاحتياطات الرذاذ."},{question:"في ترتيب خلع PPE، ما الذي يُخلع أولًا؟",options:[{text:"القفازات",correct:!0,feedback:"صحيح: القفازات هي الأكثر تلوّثًا."},{text:"الكمامة",correct:!1,feedback:"تُخلع الكمامة أخيرًا."},{text:"الرداء الواقي",correct:!1,feedback:"لاحقًا."},{text:"النظارات الواقية",correct:!1,feedback:"لاحقًا."}]},{question:"أفرغتَ كيس البول الخاص بالقثطار وخلعت قفازيك. مهمّتك التالية هي الخط الوريدي (IV line) للمريض نفسه. ماذا تفعل أولًا؟",options:[{text:"أنظّف يديّ، لأن خلع القفازات لا يُغني عن نظافة اليدين",correct:!0,feedback:"صحيح: تجتمع هنا لحظتان من اللحظات الخمس: بعد التعرّض لسوائل الجسم وقبل إجراء نظيف."},{text:"أنتقل مباشرة إلى الخط الوريدي، لأن القفازات أبقت يديّ نظيفتين",correct:!1,feedback:"غير صحيح: قد تكون في القفازات ثقوب دقيقة، وتتلوّث اليدان في أثناء خلعها."},{text:"أرتدي زوجًا جديدًا من القفازات فورًا، من دون تنظيف يديّ",correct:!1,feedback:"غير صحيح: القفازات الجديدة فوق يدين ملوّثتين تنقل الجراثيم إلى الخط الوريدي."},{text:"أمسح القفازات نفسها بالكحول وأرتديها من جديد",correct:!1,feedback:"غير صحيح: القفازات للاستعمال مرة واحدة؛ لا تُنظَّف ولا يُعاد استخدامها."}],explanation:"القفازات لا تُغني عن نظافة اليدين. نظّف يديك بعد خلعها، ولا سيما بعد التعرّض لسوائل الجسم وقبل أي إجراء نظيف."},{question:"أُدخل مريض إلى قسم عام، ويُشتبه الآن في إصابته بالسل (TB). ما الذي يُفعل؟",options:[{text:"يُنقل إلى غرفة عزل هوائي (AIIR) مع إغلاق الباب، ويرتدي العاملون N95",correct:!0,feedback:"صحيح: ينتقل السل عبر الهواء؛ فتلزم احتياطات الانتقال الهوائي."},{text:"يبقى في الغرفة المشتركة ونعطي العاملين كمامات جراحية",correct:!1,feedback:"غير صحيح: الكمامة الجراحية لا تحمي العاملين من السل، ويبقى المرضى الآخرون في الغرفة معرّضين للخطر."},{text:"احتياطات التلامس فقط: رداء واقٍ وقفازات عند السرير",correct:!1,feedback:"غير صحيح: الرداء والقفازات لا تحمي من مرض ينتقل عبر الهواء."},{text:"يبقى في مكانه حتى تصدر نتيجة المزرعة",correct:!1,feedback:"غير صحيح: تبدأ الاحتياطات عند الاشتباه لا بعد النتيجة؛ والانتظار يعرّض العاملين والمرضى للخطر."}],explanation:"ينتقل السل عبر الهواء: N95 وغرفة الضغط السلبي (AIIR) مع إغلاق الباب، منذ لحظة الاشتباه."}],tips:["ضع الجل الكحولي في موضع رعاية المريض، كي تستغرق نظافة اليدين ثواني لا مشوارًا إلى المغسلة.","اقرأ لافتة العزل قبل الدخول، وارتدِ PPE خارج الغرفة.","نظّف المعدات المشتركة مثل السمّاعة الطبية وكُمّ قياس ضغط الدم بين مريض وآخر.","اخلع قفازيك ونظّف يديك قبل لمس الحاسوب أو الهاتف أو ملف المريض."],activity:{prompt:"أنت على وشك دخول الغرفة المفردة لمريض مصاب بـ C. difficile لسحب عيّنة دم. ماذا تفعل؟",options:[{text:"رداء واقٍ وقفازات قبل الدخول، وماء وصابون لليدين بعد الخروج",correct:!0,feedback:"صحيح: احتياطات التلامس، والماء والصابون لأن الجل الكحولي لا يقتل الأبواغ."},{text:"قفازات فقط، والجل الكحولي على اليدين بعد الخروج من الغرفة",correct:!1,feedback:"غير صحيح: الرداء الواقي لازم أيضًا، والجل الكحولي لا يقتل أبواغ C. difficile."},{text:"كمامة جراحية وجل كحولي، لأن الإسهال ينتشر بالرذاذ",correct:!1,feedback:"غير صحيح: ينتقل C. difficile بالتلامس؛ والمطلوب رداء واقٍ وقفازات وماء وصابون."},{text:"قناع N95 وطلب نقل المريض إلى غرفة ضغط سلبي",correct:!1,feedback:"غير صحيح: احتياطات الانتقال الهوائي لأمراض مثل السل (TB)؛ أما C. difficile فيحتاج إلى احتياطات التلامس والماء والصابون."}]}},{id:13,code:"MED-13",icon:"Pill",accent:"#d97706",category:"طبي",title:"سلامة الأدوية — الحقوق الخمسة (5 Rights)",subtitle:"IPSG 3، والتأق، والتحقّق بالباركود (Barcode)",summary:"الأخطاء الدوائية من الأسباب الرئيسية للضرر في المستشفيات، ومعظمها يمكن الوقاية منه؛ وتقدّر منظمة الصحة العالمية (WHO) كلفتها عالميًا بنحو 42 مليار دولار سنويًا. ووفق الأهداف الدولية لسلامة المرضى (JCI IPSG 3) وISMP، فإنّ الحقوق الخمسة أساسية لكنها غير كافية: إذ يلزم استخدام مُعرِّفين اثنين (identifiers)، والباركود، والتحقّق المزدوج المستقل للأدوية عالية الخطورة. ومن الأخطاء الشائعة: الجرعة الخاطئة (مثل خطأ العشرة أضعاف)، والمريض الخطأ، والطريق الخطأ (IV بدلًا من PO).",facts:[{label:"كلفة الأخطاء الدوائية",value:"نحو 42 مليار دولار سنويًا (WHO)"},{label:"الأدوية عالية الخطورة",value:"Insulin، Heparin، Opioids، KCl"},{label:"المعيار",value:"JCI IPSG 3 + ISMP"},{label:"التأق (البالغون)",value:"Epinephrine 0.3–0.5 mg IM"}],steps:[{title:"الحقوق الخمسة — الأساس",detail:`1. المريض الصحيح (مُعرِّفان اثنان: الاسم وتاريخ الميلاد، أو رقم السجل الطبي MRN). 2. الدواء الصحيح. 3. الجرعة الصحيحة. 4. الطريق الصحيح (IV/IM/PO/SC). 5. الوقت الصحيح.
• الخمسة كلها لازمة، لا بعضها فقط.`,critical:!0},{title:"حقوق إضافية",detail:"6. التوثيق الصحيح. 7. السبب الصحيح. 8. مراقبة استجابة المريض (Right Response). وقد أضافت إرشادات كثيرة هذه الحقوق. وللأدوية عالية الخطورة: التحقّق المزدوج المستقل (Independent Double-Check).",critical:!0},{title:"التأق — الخطوة الأولى",detail:"اسأل عن الحساسية قبل أي دواء. العلامات: احمرار الجلد، والشرى (hives)، وضيق التنفّس، والصرير التنفّسي (stridor)، وانخفاض ضغط الدم. العلاج: Epinephrine 0.3–0.5 mg IM (1 mg/mL) فورًا، في الجهة الأمامية الخارجية من الفخذ (Vastus lateralis). ولا يُعطى Epinephrine IV عمومًا إلا في توقّف القلب أو من قِبل المختصّين. واطلب المساعدة (Code Blue).",critical:!0},{title:"الأدوية عالية الخطورة — التحقّق المزدوج",detail:"Insulin، وHeparin ومضادّات التخثّر، والمواد الأفيونية (Opioids) مثل Morphine وFentanyl، وKCl المركّز (Concentrated)، وأدوية العلاج الكيميائي (Chemotherapy). وتحتاج جميعها إلى تحقّق مزدوج مستقل من قِبل موظفَين اثنين وإلى الباركود.",critical:!0},{title:"إعطاء الدواء بالباركود (BCMA)",detail:"BCMA: إعطاء الأدوية بالتحقّق من الباركود (Barcode Medication Administration). امسح ضوئيًا: 1) سوار يد المريض، 2) الدواء، 3) ويتحقّق النظام من التطابق. وقد أظهرت الدراسات أنّ BCMA يقلّل أخطاء إعطاء الأدوية تقليلًا واضحًا. ولا يجوز تجاوز BCMA (Bypass) من دون سبب رسمي موثّق.",critical:!0},{title:"الأدوية المتشابهة (LASA)",detail:"أدوية متشابهة في الاسم أو الشكل (Look-Alike Sound-Alike): Hydromorphone وMorphine، وHeparin وHespan، وVincristine وVinblastine، وHumalog وHumulin. ويوصي ISMP بالكتابة بالأحرف الكبيرة (Tall Man Lettering)، مثل hydroMORPHONE وmorphine. لا تعمل اعتمادًا على الذاكرة: اقرأ، وتحقّق، وامسح ضوئيًا."}],reference:[{heading:"قائمة التحقّق من الحقوق",points:["R1: مُعرِّفان اثنان (لا رقم الغرفة أو السرير).","R2: الدواء مطابق لسجلّ إعطاء الأدوية (MAR).","R3: الجرعة مطابقة (ml، mg، units).","R4: الطريق مطابق (IV/IM/PO).","R5: الوقت مطابق (الساعة وعدد المرات).","R6: التوثيق في سجلّ إعطاء الأدوية (MAR).","R7: التحقّق من الحساسية.","R8: مراقبة الاستجابة بعد إعطاء الدواء."]},{heading:"بروتوكول التأق",points:["أولًا: Epinephrine 0.3–0.5 mg IM في الفخذ.","إعلان Code Blue وطلب المساعدة.","خط وريدي (IV) وسوائل وريدية.","ABC والأكسجين.","مضادّات الهيستامين (Antihistamine) والستيرويدات (Steroid) علاجًا إضافيًا فقط، لا بديلًا عن Epinephrine.","كرّر Epinephrine IM كل 5–15 دقيقة عند الحاجة.","المراقبة لعدة ساعات بحسب شدّة الحالة."]},{heading:"الأخطاء الشائعة",points:["1. الجرعة الخاطئة (مثل خطأ العشرة أضعاف).","2. المريض الخطأ.","3. الطريق الخطأ (IV بدلًا من PO).","4. الوقت الخطأ.","5. التداخلات الدوائية.","6. إغفال الحساسية.","7. الخلط بين الأدوية المتشابهة في الاسم أو الشكل (LASA).","8. أخطاء الأوامر الشفهية (Verbal Order).","9. أخطاء حساب الجرعة.","10. تجاوز التحقّق بالباركود (BCMA)."]}],warnings:["لا تقبل أمرًا شفهيًا (Verbal Order) من دون إعادة قراءته (Read-Back): 1) اكتبه، 2) أعِد قراءته على الطبيب، 3) احصل على تأكيده. ويجب ألّا يوجد KCl المركّز (Concentrated) في أقسام المرضى؛ بل المحاليل الجاهزة (Premixed) فقط. ولا يُعطى KCl أبدًا بطريقة الحقن الوريدي السريع (IV Push): فهو قاتل. ويُمنع تجاوز الباركود من دون سبب رسمي."],realCase:"حالة عملية (مثال تعليمي): كان لدى ممرض مريضان: أحدهما يحتاج إلى KCl IV بالتسريب البطيء (infusion) (وفق البروتوكول، عبر الأوردة الطرفية بما لا يتجاوز عمومًا 10 mEq في الساعة)، والآخر يحتاج إلى محلول ملحي (Saline) فقط. وبسبب العجلة ومن دون مسح الباركود، أُعطي KCl المركّز بطريقة الحقن الوريدي السريع (IV Push). وبعد وقت قصير دخل قلب المريض في الرجفان البطيني (VF)، فأُعلن Code Blue وبدأ CPR واستُخدم AED؛ وبعد 4 دقائق عاد القلب إلى العمل (ROSC). وتبيّن من التحقيق: تجاوز التحقّق بالباركود (BCMA)، وغياب التحقّق المزدوج، ووجود KCl المركّز في القسم. ومنذ ذلك الحين سُحب KCl المركّز من الأقسام وأصبح التحقّق بالباركود شرطًا إلزاميًا لا يمكن تجاوزه (Hard Stop).",caseStudy:[{prompt:"أنتِ ممرضة في ICU. يقول الطبيب شفهيًا: «أعطِ KCl 20 mEq IV لمريض الغرفة 302.» ماذا تفعلين؟",options:[{text:"أعطي الدواء فورًا؛ فالطبيب خبير",correct:!1,feedback:"غير صحيح: الأمر الشفهي يحتاج إلى إعادة القراءة (Read-Back) وفق JCI."},{text:"أكتبه وأعيد قراءته: «KCl 20 mEq IV بالتسريب البطيء (infusion) لمريض الغرفة 302، صحيح؟» وأطلب تسجيل الأمر في النظام",correct:!0,feedback:"صحيح: الكتابة، وإعادة القراءة (Read-Back)، والتأكيد."},{text:"أرفض؛ فجميع الأوامر الشفهية ممنوعة",correct:!1,feedback:"غير صحيح: الأمر الشفهي ليس ممنوعًا، لكنّ إعادة القراءة (Read-Back) ضرورية."},{text:"لا أفعل شيئًا حتى يظهر الأمر في النظام",correct:!1,feedback:"قد يُلحق التأخير الضرر بالمريض؛ قومي بإعادة القراءة (Read-Back)."}]},{prompt:"أكّد الطبيب الأمر. تذهبين إلى خزانة الأدوية (Pyxis). لا يوجد KCl 20 mEq جاهز (Premixed)، بل KCl 40 mEq مركّز فقط. ماذا تفعلين؟",options:[{text:"أعطي نصف KCl المركّز بطريقة الحقن الوريدي السريع (IV Push)",correct:!1,feedback:"غير صحيح: لا يُعطى KCl المركّز أبدًا بطريقة الحقن الوريدي السريع (IV Push)."},{text:"أتصل بالصيدلية وأطلب KCl جاهزًا (Premixed)",correct:!0,feedback:"صحيح: المحاليل الجاهزة فقط وبالتسريب البطيء."},{text:"أعطيه بالحقن الوريدي السريع (IV Push) لأنه أسرع",correct:!1,feedback:"قاتل: يؤدي إلى الرجفان البطيني (VF)."},{text:"أعطيه عن طريق الفم (PO)",correct:!1,feedback:"لا يجوز تغيير الطريق من دون أمر جديد."}]},{prompt:"أرسلت الصيدلية KCl 20 mEq/100 mL جاهزًا. وفي الغرفة 302 مريضان: أحدهما مستيقظ والآخر نائم. ما الخطوة الأولى؟",options:[{text:"أبدأ التسريب؛ فالغرفة صحيحة",correct:!1,feedback:"رقم الغرفة ليس مُعرِّفًا؛ ويلزم مُعرِّفان اثنان."},{text:"أمسح سوار اليد ضوئيًا وأتحقّق من المُعرِّفين (الاسم وتاريخ الميلاد)",correct:!0,feedback:"صحيح: IPSG 1 والتحقّق بالباركود (BCMA)."},{text:"أسأل المريض الآخر عمّن يحتاج إلى الدواء",correct:!1,feedback:"هذا ليس تحديدًا صحيحًا لهوية المريض."},{text:"أكتفي بقراءة سجلّ إعطاء الأدوية (MAR)",correct:!1,feedback:"السوار والباركود ضروريان أيضًا."}]}],quiz:[{question:"KCl الوريدي — ما الذي لا يُفعل أبدًا؟",options:[{text:"إعطاء المحلول الجاهز (Premixed) من الصيدلية",correct:!1,feedback:"المحلول الجاهز بالتسريب البطيء هو الطريقة الصحيحة."},{text:"الحقن الوريدي السريع (IV push)، ولا سيما KCl المركّز",correct:!0,feedback:"صحيح: إنه قاتل."},{text:"التسريب البطيء بمضخة التسريب (infusion pump)",correct:!1,feedback:"التسريب البطيء للمحلول الجاهز وفق البروتوكول آمن."},{text:"عن طريق الفم (PO)",correct:!1,feedback:"قد يكون الإعطاء عن طريق الفم آمنًا إذا وُجد أمر بذلك."}]},{question:"في التأق، ما الدواء الأول؟",options:[{text:"البينادريل (Benadryl) عن طريق الفم",correct:!1,feedback:"بطيء جدًا؛ Epinephrine أولًا."},{text:"الإبينفرين (Epinephrine) 0.3–0.5 mg في العضل (IM)",correct:!0,feedback:"صحيح: في الفخذ (Vastus lateralis)."},{text:"السوائل الوريدية (IV fluids): لتر واحد من المحلول الملحي بسرعة",correct:!1,feedback:"لاحقًا؛ Epinephrine أولًا."},{text:"O₂ فقط بالقناع، 15 لترًا في الدقيقة",correct:!1,feedback:"من دون Epinephrine تكون حياة المريض في خطر."}]},{question:"ما المُعرِّفان الاثنان اللازمان؟",options:[{text:"الاسم فقط",correct:!1,feedback:"مُعرِّف واحد لا يكفي."},{text:"الاسم وتاريخ الميلاد أو MRN",correct:!0,feedback:"صحيح: IPSG 1."},{text:"الاسم ورقم الغرفة المكتوب على الباب",correct:!1,feedback:"رقم الغرفة ليس مُعرِّفًا."},{text:"رقم السرير",correct:!1,feedback:"خطير؛ فالمرضى يُنقلون."}]},{question:"الأمر الشفهي (Verbal Order): هل تلزم إعادة القراءة (Read-Back)؟",options:[{text:"غير لازم",correct:!1,feedback:"بل هي لازمة: لا تقبل أمرًا شفهيًا أبدًا دون كتابته وإعادة قراءته والحصول على التأكيد."},{text:"لازم: الكتابة، وإعادة القراءة، والتأكيد (JCI)",correct:!0,feedback:"كتابة الأمر وإعادة قراءته على الطبيب والحصول على تأكيده يمنع أخطاء الأوامر الشفهية (JCI)."},{text:"للأدوية عالية الخطورة فقط، مثل الإنسولين والهيبارين",correct:!1,feedback:"لازم لجميع الأوامر الشفهية."},{text:"في ICU فقط، حيث تتغيّر الأوامر أكثر",correct:!1,feedback:"لازم في جميع الأقسام."}],explanation:"لا تقبل أمرًا شفهيًا أبدًا دون إعادة قراءته (Read-Back): اكتبه، وأعِد قراءته على الطبيب، واحصل على تأكيده. وينطبق ذلك على كل أمر شفهي في جميع الأقسام."},{question:"مريضان باسمين متشابهين في الغرفة نفسها. أيّ تحقّق يمنع خطأ المريض؟",options:[{text:"الاسم وتاريخ الميلاد أو MRN، مطابَقة مع سوار المعصم",correct:!0,feedback:"صحيح: مُعرِّفان اثنان مطابَقان مع السوار، لا رقم السرير أو الغرفة."},{text:"رقم السرير ورقم الغرفة المكتوب على الباب",correct:!1,feedback:"غير صحيح: ينتقل المرضى بين الأسرّة؛ ورقم السرير أو الغرفة ليس مُعرِّفًا."},{text:"نطق اسم المريض وانتظار أن يقول «نعم»",correct:!1,feedback:"غير صحيح: قد يقول المريض المشوّش أو ضعيف السمع «نعم»؛ اطلب منه أن يذكر اسمه وتاريخ ميلاده وطابقهما مع السوار."},{text:"التشخيص المكتوب على الملف عند طرف السرير",correct:!1,feedback:"غير صحيح: قد يكون لمريضين التشخيص نفسه؛ فالتشخيص ليس مُعرِّفًا."}],explanation:"الحق الأول (المريض الصحيح) يتطلّب مُعرِّفَين: الاسم وتاريخ الميلاد أو MRN، يُطابَقان مع السوار عند السرير."},{question:"تطلب منك زميلة ذاهبة إلى الاستراحة أن تعطي مريضها محقنة بلا ملصق حضّرتها بنفسها. ماذا تفعل؟",options:[{text:"أعتذر، لأنني لا أستطيع التحقّق من محقنة بلا ملصق لم أحضّرها",correct:!0,feedback:"صحيح: من دون ملصق لا يُعرف أيّ دواء وأيّ جرعة؛ فلا يمكن التحقّق من حقوق الدواء والجرعة والطريق."},{text:"أعطيها، لأنها ممرضة ذات خبرة وتعرف المريض",correct:!1,feedback:"غير صحيح: الخبرة لا تُغني عن التحقّق؛ ستعطي دواءً مجهولًا."},{text:"أعطيها بعد سؤال المريض عن اسمه، لأن ذلك يؤكّد هوية المريض",correct:!1,feedback:"غير صحيح: المريض حقّ واحد من الحقوق الخمسة؛ ويبقى الدواء والجرعة في المحقنة مجهولين."},{text:"أعطيها وأوقّع في السجل باسمها كي يكون الوقت صحيحًا",correct:!1,feedback:"غير صحيح: يجب أن يكون التوثيق صادقًا؛ فلا يوقّع كل شخص إلا على ما فعله بنفسه."}],explanation:"لا يُعطى دواء بلا ملصق: إذ لا يمكن التحقّق من حقوق الدواء والجرعة والطريق، ويجب أن يوثّق كلٌّ ما فعله بنفسه."}],tips:["طابق المُعرِّفَين مع سوار المعصم (wristband) عند السرير في كل مرة، حتى مع مريض تعرفه جيدًا.","اسأل عن الحساسية قبل كل دواء جديد، وتحقّق من تطابق الجواب مع السجل.","إذا بدا أمر أو جرعة غير مألوفين، فتوقّف وتحقّق مع الطبيب الواصف أو الصيدلي قبل الإعطاء.","اقرأ الملصق كاملًا وامسحه ضوئيًا؛ ولا تختر الدواء أبدًا بلون غطائه أو مكانه في الدرج."],activity:{prompt:"في مناوبة مزدحمة، لا يقرأ ماسح الباركود سوار معصم المريض قبل إعطاء دواء عالي الخطورة. يقترح زميل إعطاءه الآن والمسح لاحقًا. ماذا تفعل؟",options:[{text:"لا أتجاوزه: أستبدل السوار وأمسحه قبل الإعطاء",correct:!0,feedback:"صحيح: لا يُسمح بتجاوز BCMA من دون سبب رسمي موثّق، ويحتاج الدواء عالي الخطورة دائمًا إلى تحقّق مزدوج مستقل. وإذا تعذّر المسح فاتّبع الإجراء الموثّق في مستشفاك."},{text:"أعطيه الآن وأمسح السوار لاحقًا عندما يعمل الماسح من جديد",correct:!1,feedback:"غير صحيح: المسح بعد الإعطاء لا يمنع الخطأ؛ يجب أن يسبق التحقّقُ الإعطاء."},{text:"أمسح بدلًا منه سوارًا احتياطيًا محفوظًا في مكتب التمريض",correct:!1,feedback:"غير صحيح: السوار غير الموجود على يد المريض لا يثبت شيئًا عمّن يتلقّى الدواء."},{text:"أتحقّق من رقم السرير في الملف فقط وأعطيه كما في الأمر",correct:!1,feedback:"غير صحيح: رقم السرير ليس مُعرِّفًا؛ يلزم مُعرِّفان اثنان."}]}},{id:14,code:"ICS-14",icon:"ClipboardList",accent:"#a855f7",category:"الطوارئ",title:"نظام قيادة الحوادث (ICS) ورموز الطوارئ في المستشفى",subtitle:"HICS، ورموز الألوان، والفرز الطبي للمصابين (Triage)",summary:"نظام قيادة الحوادث (ICS) أسلوب موحّد لإدارة الكوارث. وتستخدم المستشفيات نظام HICS (Hospital Incident Command System). ورموز الألوان وسيلة للإنذار الداخلي السريع، غير أنّ معنى بعض الرموز يختلف من مستشفى إلى آخر، ولذلك يجب على كل موظف أن يعرف قائمة الرموز المعتمدة في مستشفاه. ووفق اللجنة المشتركة (Joint Commission) وNIMS، يجب أن تكون لدى المستشفى خطة عمليات الطوارئ (EOP)، وأن يُجري تمارين طوارئ مرتين في السنة على الأقل.",facts:[{label:"المعيار",value:"HICS + NIMS"},{label:"تمارين الطوارئ",value:"مرتان في السنة على الأقل"},{label:"رموز المستشفى",value:"وفق القائمة المعتمدة في مستشفاك"},{label:"الفرز الطبي (Triage)",value:"START (للبالغين) + JumpSTART (للأطفال)"}],steps:[{title:"HICS — الأقسام الرئيسية الخمسة",detail:"1. القيادة (Command): قائد الحادث. 2. العمليات (Operations): علاج المرضى، والبنية التحتية، والأمن. 3. التخطيط (Planning): الوضع الراهن، والتوثيق، والموارد. 4. الإمداد (Logistics): المستلزمات، والاتصالات، والطعام. 5. المالية والإدارة (Finance/Administration): الوقت، والمشتريات، والتعويضات. ولكل قسم رئيس (Section Chief).",critical:!0},{title:"رموز الألوان (أمثلة)",detail:`Code Red: حريق.
• Code Blue: توقّف القلب أو التنفّس.
• Code Black: تهديد بوجود متفجّرات.
• Code Orange: مواد خطرة (HazMat).
• Code Yellow: كارثة أو وصول أعداد كبيرة من المصابين (MCI).
• Code Green: إخلاء.
• Code Gray أو Violet: شخص عنيف.
• Code Pink: اختطاف رضيع.
• Code Brown: أحوال جوية قاسية.
ويختلف معنى الرموز بين المستشفيات؛ فالتزم بالقائمة المعتمدة في مستشفاك.`,critical:!0},{title:"الفرز الطبي بطريقة START (START Triage) — للبالغين",detail:`الفرز البسيط والعلاج السريع (Simple Triage And Rapid Treatment). أربع فئات:
• الأخضر (Minor): يستطيع المشي.
• الأصفر (Delayed): إصابة خطيرة لكنه يستطيع الانتظار.
• الأحمر (Immediate): خطر على الحياة، علاج فوري.
• الأسود (Expectant/Deceased): متوفّى أو لا فرصة له في النجاة.
يُفرز كل مصاب في غضون نحو 30–60 ثانية. إذا لم يتنفّس: افتح المجرى الهوائي؛ فإن بدأ التنفّس: أحمر؛ وإلّا: أسود. RPM (التنفّس والتروية والحالة الذهنية): تنفّس أكثر من 30 في الدقيقة = أحمر؛ غياب نبض الرسغ أو زمن امتلاء الشعيرات (capillary refill) أكثر من ثانيتين = أحمر؛ عدم القدرة على تنفيذ الأوامر البسيطة = أحمر؛ وإلّا: أصفر.`,critical:!0},{title:"JumpSTART — للأطفال (نحو 1–8 سنوات)",detail:"إذا لم يتنفّس الطفل: افتح المجرى الهوائي؛ فإن بدأ التنفّس: أحمر. وإذا بقي لا يتنفّس: افحص النبض المحيطي (peripheral pulse)؛ فإن غاب: أسود. وإن وُجد النبض: أعطِ 5 أنفاس إنقاذية؛ فإن بدأ التنفّس: أحمر؛ وإلّا: أسود. وإذا كان الطفل يتنفّس: معدّل تنفّس أقل من 15 أو أكثر من 45 في الدقيقة = أحمر. وإذا كان بين 15–45، فافحص النبض المحيطي: غيابه = أحمر. ثم مقياس الوعي AVPU: P غير الملائمة أو U = أحمر؛ وA أو V أو P الملائمة = أصفر.",critical:!0},{title:"EOP — خطة عمليات الطوارئ",detail:"ستة مجالات مهمة: 1) الاتصالات، 2) الموارد والمستلزمات، 3) السلامة والأمن، 4) أدوار العاملين، 5) الخدمات الأساسية (الماء، والكهرباء، والغاز)، 6) علاج المرضى. ويُجرى تحليل المخاطر (Hazard Vulnerability Analysis) سنويًا. ويُجرى تمرينان للطوارئ على الأقل في السنة، وتُجرى تمارين الحريق بصورة منفصلة وفق NFPA 101.",critical:!0},{title:"الاتصالات في أثناء الكوارث الكبرى",detail:"أولًا: هاتف المستشفى وجهاز النداء (pager). ثانيًا: الهاتف المحمول واللاسلكي. ثالثًا: موظفون مكلَّفون بنقل الرسائل (Runners). احتياطيًا: الهاتف الفضائي (Satellite). ويوصي NIMS باستخدام اللغة الواضحة (Plain Language)؛ وكثير من المستشفيات تُطلق التنبيهات بلغة واضحة بدلًا من الرموز."}],reference:[{heading:"نموذج لرموز المستشفى",points:["الأحمر (Red): حريق.","الأزرق (Blue): توقّف القلب أو التنفّس.","الأسود (Black): تهديد بوجود متفجّرات.","البرتقالي (Orange): مواد خطرة.","الأصفر (Yellow): كارثة أو حادث إصابات جماعية (MCI).","الأخضر (Green): إخلاء.","الرمادي (Gray): شخص عنيف.","البنفسجي (Violet): شخص عنيف (في بعض المستشفيات).","الوردي (Pink): اختطاف رضيع.","البنّي (Brown): أحوال جوية قاسية.","الفضّي (Silver): شخص مسلّح (في بعض المستشفيات).","يختلف معنى الرموز؛ فاعرف القائمة المعتمدة في مستشفاك."]},{heading:"فئات الفرز الطبي بطريقة START",points:["الأخضر: إصابات طفيفة، ويستطيع المشي.","الأصفر: إصابات خطيرة لكنها مستقرة، ويمكنه الانتظار.","الأحمر: خطر على الحياة، علاج فوري.","الأسود: متوفّى أو ميؤوس من نجاته (Expectant).","ثبّت بطاقة الفرز (Triage Tag) على المصاب.","أعِد الفرز (Re-Triage) بانتظام وكلما تغيّرت الحالة."]},{heading:"أدوار HICS",points:["قائد الحادث (Incident Commander).","مسؤول الإعلام العام (PIO).","مسؤول الاتصال الخارجي (Liaison Officer).","مسؤول السلامة (Safety Officer).","رئيس قسم العمليات (Operations).","رئيس قسم التخطيط (Planning).","رئيس قسم الإمداد (Logistics).","رئيس قسم المالية والإدارة (Finance/Admin)."]}],warnings:["خارج المستشفى ومع الجمهور، استخدم اللغة الواضحة لا الرموز. وفي الداخل، لا تستخدم إلا الرموز الواردة في القائمة المعتمدة في مستشفاك. JumpSTART للأطفال من عمر 1–8 سنوات تقريبًا؛ وSTART للبالغين. وفي JumpSTART، معدّل تنفّس أقل من 15 أو أكثر من 45 = أحمر (Immediate)، لا أسود. لا تنزع بطاقة الفرز عن المصاب."],realCase:"حالة عملية (مثال تعليمي للتدريب): وقع انفجار سيارة بالقرب من أحد المستشفيات، ووصل 42 مصابًا خلال أول 10 دقائق. فأُعلن Code Yellow وفُعِّل HICS؛ وعُيِّن قائد الحادث خلال أول دقيقتين. وأُجري الفرز الطبي بطريقة START في قسم الطوارئ: 8 في الفئة الحمراء، و12 في الصفراء، و15 في الخضراء، و7 في السوداء. وأوقف المستشفى العمليات الجراحية غير العاجلة، وأخرج المرضى المستقرّين، وفتح أماكن إضافية (Surge Capacity). ونجا 35 مصابًا. الدرس المستفاد: تمارين HICS المنتظمة، وإعادة الفرز (Re-Triage) المستمرة.",caseStudy:[{prompt:"أنتِ ممرضة في قسم الطوارئ (ER). يصل إشعار: انفجار سيارة، وسيصل 30 مصابًا أو أكثر. ماذا تفعلين أولًا؟",options:[{text:"أبدأ فورًا بعلاج أول مصاب يصل",correct:!1,feedback:"من دون فرز طبي (Triage) وتنظيم، تُستخدم الموارد على نحو خاطئ."},{text:"أعلن Code Yellow، ويُفعَّل ICS، وأجهّز بطاقات الفرز الطبي (START Triage)",correct:!0,feedback:"صحيح: بروتوكول الإصابات الجماعية (MCI)."},{text:"أغلق الباب حتى يكتمل الفريق",correct:!1,feedback:"يبقى المصابون من دون علاج."},{text:"أنتظر الطبيب",correct:!1,feedback:"لا وقت للانتظار؛ يجب أن تتحرّكي."}]},{prompt:"المصاب الأول: 35 عامًا، واعٍ، يستطيع المشي، ينزف نزفًا قليلًا من كتفه، ومعدّل تنفّسه 20 في الدقيقة. أيّ لون؟",options:[{text:"أحمر",correct:!1,feedback:"هو واعٍ ويستطيع المشي؛ فليس أحمر."},{text:"أخضر (Walking wounded)",correct:!0,feedback:"صحيح: في START يُصنَّف كل من يستطيع المشي أخضر في البداية، ثم يُعاد فرزه (Re-Triage)."},{text:"أصفر",correct:!1,feedback:"من يستطيع المشي يُصنَّف أخضر في البداية، لا أصفر."},{text:"أسود",correct:!1,feedback:"غير صحيح: إنه واعٍ."}]},{prompt:"المصاب الثاني: 22 عامًا، فاقد للوعي ولا يتنفّس. فتحتِ المجرى الهوائي (repositioning)، لكنه ما زال لا يتنفّس. أيّ لون في START؟",options:[{text:"أحمر (Immediate)",correct:!1,feedback:"في START، إذا بدأ التنفّس بعد فتح المجرى الهوائي يُصنَّف أحمر؛ لكنّ هذا المصاب ما زال لا يتنفّس."},{text:"أسود (Expectant/Deceased)",correct:!0,feedback:"صحيح: في حادث الإصابات الجماعية (MCI)، إذا لم يتنفّس المصاب بعد فتح المجرى الهوائي، يُصنَّف أسود. ولا يُجرى CPR في أثناء الفرز (Triage)، حتى تبقى الموارد لمن لديهم فرصة في النجاة."},{text:"أصفر",correct:!1,feedback:"الأصفر إصابة خطيرة تحتمل الانتظار؛ أما المصاب الذي لا يتنفّس بعد فتح المجرى الهوائي فيُصنَّف أسود."},{text:"CPR فورًا",correct:!1,feedback:"في حادث الإصابات الجماعية (MCI) يأتي الفرز (Triage) أولًا؛ فـ CPR يستنزف الموارد على حساب المصابين الآخرين."}]}],quiz:[{question:"ماذا يعني Code Pink عمومًا؟",options:[{text:"حريق",correct:!1,feedback:"هذا هو Code Red."},{text:"اختطاف رضيع",correct:!0,feedback:"في القائمة النموذجية يعني Code Pink اختطاف رضيع؛ وتختلف المعاني، فاعرف قائمة مستشفاك."},{text:"توقّف القلب",correct:!1,feedback:"هذا هو Code Blue."},{text:"تحذير من طقس سيّئ",correct:!1,feedback:"ليس Code Pink رمزًا للأحوال الجوية؛ ففي القائمة النموذجية يعني اختطاف رضيع."}],explanation:"في قائمة الرموز النموذجية يعني Code Pink اختطاف رضيع. ويختلف معنى الرموز بين المستشفيات، لذا يجب أن يعرف كل موظف قائمة مستشفاه."},{question:"ماذا يعني اللون الأسود في الفرز الطبي بطريقة START (START Triage)؟",options:[{text:"إصابات طفيفة",correct:!1,feedback:"هذا هو الأخضر."},{text:"متوفّى أو Expectant",correct:!0,feedback:"الأسود يعني متوفّى أو بلا فرصة في النجاة، كانعدام التنفّس بعد فتح المجرى الهوائي."},{text:"خطر على الحياة، يُعالَج أولًا",correct:!1,feedback:"هذا هو الأحمر."},{text:"مستقر",correct:!1,feedback:"هذا هو الأصفر."}],explanation:"في START يعني الأسود متوفّى أو Expectant (لا فرصة له في النجاة)، كالمصاب الذي لا يتنفّس رغم فتح المجرى الهوائي."},{question:"ما القسم الرئيسي في HICS؟",options:[{text:"العمليات (Operations)",correct:!1,feedback:"يعمل تحت القيادة."},{text:"القيادة (Command)",correct:!0,feedback:"صحيح: قائد الحادث على رأس الهيكل."},{text:"اللوجستيات (Logistics)",correct:!1,feedback:"يعمل تحت القيادة."},{text:"المالية والإدارة (Finance)",correct:!1,feedback:"يعمل تحت القيادة."}]},{question:"في JumpSTART، طفل يتنفّس 50 مرة في الدقيقة. أيّ لون؟",options:[{text:"أسود (Expectant)",correct:!1,feedback:"غير صحيح: الأسود فقط للطفل الذي لا يتنفّس بعد فتح المجرى الهوائي وإعطاء 5 أنفاس إنقاذية، أو الذي لا نبض له."},{text:"أحمر (Immediate)",correct:!0,feedback:"صحيح: معدّل تنفّس أقل من 15 أو أكثر من 45 = أحمر."},{text:"أصفر (Delayed)",correct:!1,feedback:"الأصفر فقط إذا كان التنفّس بين 15–45، والنبض موجودًا، وAVPU ملائمًا."},{text:"أخضر (Minor)",correct:!1,feedback:"الأخضر لمن يستطيعون المشي."}]},{question:"في حادث إصابات جماعية، يصل بالغ مصاب بجرح في ذراعه ماشيًا بمفرده إلى منطقة الفرز. ما الفئة التي يُعطاها أولًا في START؟",options:[{text:"الأخضر (Minor)، ويُعاد فرزه لاحقًا",correct:!0,feedback:"صحيح: في START كل من يستطيع المشي أخضر في البداية؛ ويُعاد الفرز كلما تغيّرت الحالة."},{text:"الأحمر (Immediate)، لأنه ينزف",correct:!1,feedback:"غير صحيح: يستطيع المشي، فلا يكون أحمر في البداية؛ ويُعاد تقييمه إذا ساءت حالته."},{text:"الأصفر (Delayed)، بسبب الجرح في ذراعه",correct:!1,feedback:"غير صحيح: في START من يمشي أخضر؛ والأصفر لمن لا يستطيع المشي وإصابته خطيرة."},{text:"الأسود (Expectant)، لأنه يستطيع الانتظار أطول من الجميع",correct:!1,feedback:"غير صحيح: الأسود للمتوفّى أو لمن لا أمل في نجاته، لا لمن يستطيع الانتظار."}],explanation:"يبدأ START بسؤال أول: هل يستطيع المشي؟ إن كان كذلك فهو أخضر. ويُعاد الفرز كلما تغيّرت الحالة."},{question:"يسأل زائر في قاعة الانتظار ممرضة عن معنى الرمز الذي أُعلن للتو. ماذا تفعل الممرضة؟",options:[{text:"تعطيه تعليمات واضحة بلغة بسيطة عمّا يفعله، من دون كلمات الرمز",correct:!0,feedback:"صحيح: مع الجمهور تُستخدم اللغة الواضحة لا الرموز؛ قل بهدوء ما يجب فعله."},{text:"تقول له إنه سرّ خاص بالموظفين وتنصرف دون توضيح",correct:!1,feedback:"غير صحيح: قد يحتاج الزائر إلى تعليمات كي يبقى آمنًا."},{text:"تكرّر لون الرمز كي يبحث هو عن معناه بنفسه",correct:!1,feedback:"غير صحيح: تختلف معاني الرموز بين المستشفيات ولا يعرفها الجمهور؛ وهذا يزيد الارتباك والخوف."},{text:"تطلب منه مغادرة المبنى بسرعة بالمصعد قبل أن يزدحم",correct:!1,feedback:"غير صحيح: قد يخالف ذلك الخطة، ولا يُستخدم المصعد في الحريق والزلزال؛ اتّبع تعليمات الخطة."}],explanation:"خارج المستشفى ومع الجمهور استخدم لغة واضحة لا رموزًا. فالرموز للموظفين فقط ووفق قائمة مستشفاك."}],tips:["احتفظ بنسخة من قائمة رموز مستشفاك في مكان عملك، وتعلّم ما يطلبه منك كل رمز.","اعرف قبل وقوع الحادث أين تحضر ولمن تقدّم تقريرك وفق خطة الطوارئ في مستشفاك.","في أثناء الحادث، تلقَّ المهام من مسؤولك في هيكل القيادة، وأبلغه عند إنهاء كل مهمة.","شارك في كل تمرين طوارئ كأنه حقيقي؛ ففيه تُكشف ثغرات الخطة."],activity:{prompt:"يُعلَن رمز مستشفاك لحادث الإصابات الجماعية (MCI). أنت ممرض في قسم الجراحة، وبدأ زملاء من خارج المناوبة يصلون إلى قسمك. ماذا تفعل؟",options:[{text:"أتّبع الخطة: أبلّغ مسؤولي وأوجّه الموظفين القادمين إلى المكان الذي تحدّده الخطة",correct:!0,feedback:"صحيح: في HICS يُكلَّف الموظفون عبر هيكل القيادة؛ والتوجّه الذاتي يسبّب الازدحام والثغرات."},{text:"أتوجّه مباشرة إلى قسم الطوارئ، لأن المصابين سيكونون هناك",correct:!1,feedback:"غير صحيح: الموظفون غير المطلوبين يزحمون قسم الطوارئ ويتركون مرضاك بلا رعاية."},{text:"أتّصل بأسر مرضاي لأحذّرهم من وقوع كارثة",correct:!1,feedback:"غير صحيح: يقدّم المعلومات للجمهور المسؤول المكلَّف (PIO)، وخطوط الهاتف لازمة للاستجابة."},{text:"أواصل عملي المعتاد وأتجاهل الرمز، لأنني لست في قسم الطوارئ",correct:!1,feedback:"غير صحيح: لكل قسم دور في الخطة، مثل تجهيز الأسرّة لاستقبال المرضى."}]}},{id:15,code:"QUAKE-15",icon:"Activity",accent:"#a16207",category:"الكوارث",title:"الزلزال في المستشفى",subtitle:"قاعدة «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On)، وحماية المرضى، وفحص المبنى",summary:"يشكّل الزلزال خطرًا كبيرًا على المستشفيات: فالمرضى طريحو الفراش لا يستطيعون الهرب فورًا، وقد تسقط الأجهزة وأسطوانات الغاز والمعدات الثقيلة. ووفق الوكالة الفدرالية الأمريكية لإدارة الطوارئ (FEMA) ومؤشّر سلامة المستشفيات لمنظمة WHO (Hospital Safety Index)، يجب أن تُبنى المستشفيات وتُجهَّز بحيث تواصل العمل حتى بعد الزلزال. ويقع إقليم كوردستان على حزام زاغروس، وهو منطقة زلزالية نشطة. ويوضّح هذا الدرس ما يجب فعله في أثناء الهزّة، وحماية المرضى، وفحص المبنى بعد الهزّة.",facts:[{label:"منطقة كوردستان",value:"حزام زاغروس (Zagros)"},{label:"في أثناء الهزّة",value:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)"},{label:"المعيار",value:"FEMA + مؤشّر سلامة المستشفيات (WHO)"},{label:"فحص المبنى",value:"ATC-20 (أخضر · أصفر · أحمر)"}],steps:[{title:"1. في أثناء الهزّة — انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",detail:"انخفض (Drop): انزل فورًا على ركبتيك ويديك. احتمِ (Cover): احمِ رأسك وعنقك تحت طاولة متينة، بعيدًا عن النوافذ والمعدات الثقيلة. تمسّك (Hold On): أمسك بالطاولة وابقَ في مكانك حتى تتوقف الهزّة. لا تركض نحو الباب أو إلى الخارج أو إلى المصعد.",critical:!0},{title:"2. المرضى طريحو الفراش",detail:"ثبّت مكابح عجلات الأسرّة. يبقى المريض على سريره ويحمي رأسه بالوسادة. وإذا سمح الوقت، أبعد عن المريض الأشياء القابلة للسقوط. ويبقى مرضى ICU والمرضى على أجهزة التنفس الاصطناعي في أماكنهم ويُحمَون بالوسائد. لا تُخرج المرضى في أثناء الهزّة؛ فالمبنى ما زال يهتزّ.",critical:!0},{title:"3. بعد الهزّة — الدقائق الخمس الأولى",detail:"1. افحص نفسك وزملاءك: هل هناك مصاب؟ 2. أحصِ المرضى وافحصهم. 3. افحص أجهزة التنفس الاصطناعي وتدفّق الأكسجين. 4. افحص أنابيب الغاز؛ وإذا شممت رائحة الغاز أو سمعت صوت تسرّبه، فلا يُغلق صمامَ الغاز إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا أمكن الوصول إليه بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون أيّ شرارة؛ وإلا فأبعِد الجميع عن ذلك المكان واتصل بالرقم 115. 5. أبلغ قسم الهندسة وICS.",critical:!0},{title:"4. فحص المبنى — التقييم السريع للأضرار (Rapid Damage Assessment)",detail:`لنظام ATC-20 ثلاث فئات من الملصقات:
• أخضر (Inspected): فُحص ويمكن استخدامه.
• أصفر (Restricted Use): استخدام محدود.
• أحمر (Unsafe): غير آمن؛ لا تدخل.
ولا يضع الملصقات إلا المهندسون أو المفتّشون المدرَّبون والمكلَّفون. لا تعُد إلى مبنى متضرّر من دون فحص.`,critical:!0},{title:"5. الهزّات الارتدادية (Aftershocks)",detail:"بعد الهزّة الرئيسية، تحدث الهزّات الارتدادية في الغالب في الفترة الأولى، وقد تستمر أيامًا وأسابيع؛ وقد تُسقط المباني الضعيفة. أبقِ المرضى في أماكن آمنة حتى يُجرى الفحص الهندسي. ومع كل هزّة ارتدادية، كرّر «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On).",critical:!0},{title:"6. إخلاء المبنى",detail:"فقط إذا حصل المبنى على الملصق الأحمر أو طلب المهندس ذلك. جهّز قائمة المرضى قبل الإخلاء. الإخلاء الأفقي قبل العمودي. ولكل مريض في ICU أو على جهاز التنفس الاصطناعي 3 أشخاص. لا تحمل الأغراض الثمينة. ويجب أن تكون نقطة التجمّع بعيدة عن المباني وأسلاك الكهرباء والجدران."}],reference:[{heading:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",points:["انخفض (Drop): فورًا على الركبتين.","احتمِ (Cover): تحت طاولة متينة، واحمِ رأسك وعنقك.","تمسّك (Hold On): أمسك بالطاولة وابقَ في مكانك.","ابقَ حتى تتوقف الهزّة.","لا تركض نحو الباب.","لا تستخدم المصعد.","لا تبقَ بالقرب من النوافذ."]},{heading:"ملصقات ATC-20",points:["أخضر: «تم الفحص» (Inspected)، يمكن استخدامه.","أصفر: «استخدام محدود» (Restricted Use)، الدخول محدود.","أحمر: «غير آمن» (Unsafe)، لا تدخل.","لا تعُد إلى المبنى من دون ملصق.","لا يضع الملصقات إلا المهندسون أو المفتّشون المكلَّفون.","يُعاد الفحص بعد كل هزّة ارتدادية قوية."]},{heading:"نقاط الضعف في المستشفى",points:["العناصر غير الإنشائية: أسطوانات الغاز، وأجهزة CT وMRI، والخزائن.","الأشياء القابلة للسقوط: الأجهزة والمستلزمات الموضوعة على الرفوف.","تحطّم الزجاج: النوافذ.","انقطاع الكهرباء: المولّدات وأجهزة الطاقة غير المنقطعة (UPS).","انقطاع الماء: الخزانات الاحتياطية.","الاتصالات: اللاسلكي والهاتف الفضائي."]}],warnings:["لا تستخدم المصعد في أثناء الهزّة ولا بعدها. لا تعُد إلى مبنى متضرّر من دون فحص وملصق هندسي. قد تُسقط الهزّات الارتدادية المباني الضعيفة؛ فأبقِ المرضى في أماكن آمنة. لا يُغلق صمام الغاز إلا عند وجود رائحة الغاز أو صوت تسرّبه، وعلى يد الموظفين المدرَّبين والمكلَّفين، وإذا أمكن الوصول إليه بأمان؛ ولا تقطع الأكسجين عن المرضى الذين يحتاجون إليه."],realCase:"في 6 شباط (فبراير) 2023، ضرب زلزالان قويان (Mw 7.8 وMw 7.5 بحسب USGS) جنوب تركيا وشمال سوريا. وبحسب تقارير صحفية، انهار في الإسكندرونة جزء من المستشفى الحكومي، ومات أشخاص. الدروس المستفادة لكوردستان: بناء المستشفيات وفق كودات الزلازل، وتثبيت الأجهزة والأسطوانات بالجدران، والتدريب المستمر على «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On) وعلى الإخلاء.",caseStudy:[{prompt:"أنتِ ممرضة في ICU. عند الساعة 02:47 ليلًا تهتزّ الأرض بقوة. لديكِ مريضان على جهاز التنفس الاصطناعي وأربعة مرضى آخرون. ماذا تفعلين أولًا؟",options:[{text:"أركض نحو الباب",correct:!1,feedback:"غير صحيح: قد تسقطين أو تسقط الأشياء عليكِ."},{text:"أطبّق «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On) تحت طاولة متينة، وأثبّت مكابح عجلات الأسرّة إذا كانت قريبة",correct:!0,feedback:"صحيح: سلامتكِ أولًا؛ فالموظف المصاب لا يستطيع حماية المرضى."},{text:"أُخرج المرضى فورًا إلى الخارج",correct:!1,feedback:"خطير: فالمبنى ما زال يهتزّ."},{text:"أغلق باب الغرفة وأقف أمامه",correct:!1,feedback:"الوقوف أمام الباب ليس مكانًا آمنًا؛ احمي نفسكِ تحت طاولة متينة."}]},{prompt:"توقّفت الهزّة بعد 45 ثانية. وأنتِ واقفة على قدميكِ. ما الخطوة الأولى؟",options:[{text:"أخرج فورًا وحدي",correct:!1,feedback:"غير صحيح: المرضى يحتاجون إليكِ، والخروج من دون فحص خطير."},{text:"أفحص نفسي والمرضى، وأفحص أجهزة التنفس الاصطناعي والأكسجين، وإذا وُجدت رائحة غاز أُبلغ عنها ليُغلق الموظفون المدرَّبون صمام الغاز إذا كان الوصول إليه آمنًا",correct:!0,feedback:"صحيح: فحص النفس والمرضى والأجهزة."},{text:"أنقل المرضى إلى المصعد",correct:!1,feedback:"لا يُستخدم المصعد بعد الهزّة."},{text:"أبقى في مكاني ولا أفعل شيئًا",correct:!1,feedback:"يجب أن تفحصي المرضى وتستعدي للهزّات الارتدادية."}]},{prompt:"انتهى الفحص. سقط شيء على مريض قرب الباب وأُصيب في عنقه. ماذا تفعلين؟",options:[{text:"أرفعه فورًا وأضعه على السرير",correct:!1,feedback:"قبل تحريكه، تلزم حماية العنق والعمود الفقري (spinal precautions)."},{text:"أستدعي Code Blue أو فريق الإصابات، وأحمي العنق والعمود الفقري، وأُبلغ المهندس لفحص المبنى",correct:!0,feedback:"صحيح: علاج المصاب وسلامة المبنى معًا."},{text:"أخرج وحدي",correct:!1,feedback:"غير صحيح: المريض يحتاج إليكِ."},{text:"أنقله بالمصعد إلى قسم الطوارئ",correct:!1,feedback:"لا يُستخدم المصعد بعد الهزّة؛ استخدمي السلالم."}]}],quiz:[{question:"ما المقصود بقاعدة «انخفض، احتمِ، تمسّك» (Drop, Cover, Hold On)؟",options:[{text:"الركض نحو الباب والوقوف تحت إطاره حتى يتوقّف الاهتزاز",correct:!1,feedback:"خطير: إطار الباب لا يحميك، والركض قد يُسقطك."},{text:"النزول على الركبتين، والاحتماء تحت طاولة متينة، والإمساك بها",correct:!0,feedback:"صحيح: أفضل حماية في أثناء الهزّة."},{text:"الوقوف بالقرب من النافذة",correct:!1,feedback:"خطر تحطّم الزجاج."},{text:"الركض نحو المصعد للخروج من المبنى قبل أن يشتدّ الاهتزاز",correct:!1,feedback:"لا تستخدم المصعد أثناء الهزّة ولا بعدها؛ انخفض، واحتمِ تحت طاولة متينة، وتمسّك."}],explanation:"انزل على يديك وركبتيك، واحتمِ تحت طاولة متينة بعيدًا عن النوافذ والمعدات الثقيلة، وتمسّك بها حتى تتوقف الهزّة."},{question:"ماذا يعني الملصق الأحمر (ATC-20)؟",options:[{text:"آمن",correct:!1,feedback:"هذا هو الأخضر."},{text:"Unsafe: لا تدخل",correct:!0,feedback:"الأحمر (Unsafe) يعني لا تدخل؛ ولا يضع الملصقات إلا المهندسون أو المفتّشون المكلَّفون."},{text:"الدخول محدود",correct:!1,feedback:"هذا هو الأصفر."},{text:"المبنى منهار بالكامل",correct:!1,feedback:"ليس بالضرورة؛ فالأحمر يعني أنّ الدخول غير آمن."}],explanation:"وفق ATC-20 يعني الملصق الأحمر أن المبنى غير آمن: لا تدخل. والأخضر يعني أنه فُحص ويمكن استخدامه، والأصفر يعني استخدامًا محدودًا."},{question:"متى تحدث الهزّات الارتدادية (Aftershocks)؟",options:[{text:"لا تحدث أبدًا",correct:!1,feedback:"غير صحيح: تحدث دائمًا بعد الزلازل القوية."},{text:"في الغالب بعد الهزّة الرئيسية بوقت قصير، وقد تستمر أيامًا وأسابيع",correct:!0,feedback:"صحيح: ولذلك لا تعُد إلى المبنى من دون فحص."},{text:"خلال أول 5 دقائق فقط بعد الهزّة الرئيسية؛ وبعدها يصبح المبنى آمنًا",correct:!1,feedback:"غير صحيح: قد تحدث بعد ذلك بكثير أيضًا."},{text:"بعد أسبوع فقط، عندما تستقرّ الأرض بعد الهزّة الرئيسية",correct:!1,feedback:"غير صحيح: تحدث في الغالب في الفترة الأولى."}]},{question:"بعد الهزّة، ماذا تفعل بأنابيب الغاز وأجهزته؟",options:[{text:"لا حاجة إلى فحصها",correct:!1,feedback:"هناك خطر تسرّب الغاز."},{text:"أفحصها؛ وإذا وُجدت رائحة غاز أو صوت تسرّب، يُغلق الموظفون المدرَّبون صمام الغاز فقط إذا كان الوصول إليه آمنًا",correct:!0,feedback:"لا يُغلق صمام الغاز إلا الموظفون المدرَّبون والمكلَّفون، وعند وجود رائحة أو تسرّب فقط، وإذا أمكن الوصول إليه بأمان."},{text:"أتجوّل بنفسي وأغلق جميع الصمامات فورًا، بما فيها أكسجين المرضى، ثم أفحص أنابيب الغاز بعد ذلك فقط",correct:!1,feedback:"غير صحيح: قطع الأكسجين يعرّض المرضى للخطر."},{text:"أفحصها فقط إذا كان أحد الأجهزة أو الأنابيب مكسورًا بوضوح؛ فرائحة الغاز وحدها ليست سببًا",correct:!1,feedback:"غير صحيح: افحص جميع الأنابيب والأجهزة؛ فرائحة الغاز أو صوت التسرّب علامة خطر."}],explanation:"افحص أنابيب الغاز. وعند وجود رائحة غاز أو صوت تسرّب، لا يُغلق صمام الغاز إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا أمكن الوصول إليه بأمان، ولا يُقطع أكسجين المرضى أبدًا."},{question:"بعد الهزّة، تضع الهندسة لافتة صفراء (ATC-20) على جناحك. ماذا يعني ذلك لقسمك؟",options:[{text:"استخدام مقيّد: الدخول والعمل فقط بحسب ما تسمح به الهندسة",correct:!0,feedback:"صحيح: الأصفر = استخدام مقيّد؛ الدخول فقط بالطريقة المحدّدة ووفق تعليمات الهندسة."},{text:"فُحص وهو آمن: يستمر العمل المعتاد في كل مكان",correct:!1,feedback:"غير صحيح: هذا معنى اللافتة الخضراء."},{text:"غير آمن: لا يدخل أحد، ويخرج جميع المرضى فورًا",correct:!1,feedback:"غير صحيح: هذا معنى اللافتة الحمراء."},{text:"لم يُفحص بعد: يقرّر الموظفون بأنفسهم أين يعملون",correct:!1,feedback:"غير صحيح: توضع اللافتة بعد الفحص، ولا يقرّر الموظفون وحدهم سلامة المبنى."}],explanation:"ATC-20: الأخضر = فُحص ويمكن استخدامه؛ الأصفر = استخدام مقيّد؛ الأحمر = غير آمن، لا تدخل. ولا يضع اللافتات إلا المهندسون أو المفتّشون المكلَّفون."},{question:"تبدأ هزّة ارتدادية (aftershock) بينما تدفع مريضًا على كرسي متحرك في الممر. ماذا تفعل؟",options:[{text:"أتوقف بعيدًا عن النوافذ وأثبّت المكابح وأحمي رأسه وأطبّق «انخفض، احتمِ، تمسّك»",correct:!0,feedback:"صحيح: مع كل هزّة ارتدادية نطبّق «انخفض، احتمِ، تمسّك» من جديد؛ ويبقى المريض في مكانه مع حماية رأسه."},{text:"أركض بالكرسي المتحرك إلى أقرب مخرج قبل أن تشتدّ الهزّة أكثر",correct:!1,feedback:"غير صحيح: الركض في أثناء الهزّة يعرّضك أنت والمريض للسقوط وللأجسام المتساقطة."},{text:"أنزل بالمصعد إلى الطابق الأرضي، لأن المريض لا يستطيع استخدام الدرج",correct:!1,feedback:"غير صحيح: لا يُستخدم المصعد في أثناء الهزّة ولا بعدها؛ فقد يتوقف وتُحتجزان فيه."},{text:"أترك المريض في الممر وأحتمي وحدي تحت أقرب طاولة",correct:!1,feedback:"غير صحيح: لا تترك المريض وحده؛ ثبّت المكابح واحمِ رأسه واحمِ نفسك بالقرب منه."}],explanation:"تأتي الهزّات الارتدادية بعد الزلزال الرئيسي؛ ومع كل هزّة طبّق «انخفض، احتمِ، تمسّك» من جديد، ولا تستخدم المصعد، ولا تترك المريض وحده."}],tips:["قبل وقوع الزلزال، أبلغ قسم الهندسة عن أسطوانات الغاز غير المثبّتة والخزائن العالية والمعدات الثقيلة في مكان عملك.","أبقِ مكابح عجلات السرير مثبّتة كلما لم يكن السرير يُنقل.","اعرف أقرب طاولة متينة إلى مكان عملك المعتاد، بعيدًا عن النوافذ والمعدات الثقيلة.","احتفظ بقائمة محدّثة بالمرضى ومصباح يدوي في مكان تصل إليه بسرعة."],activity:{prompt:"تبدأ هزّة قوية وأنت واقف بجانب مريض طريح الفراش في قسم عام. ماذا تفعل؟",options:[{text:"أثبّت مكابح عجلات السرير، وأحمي رأسه بوسادة، وأطبّق «انخفض، احتمِ، تمسّك» قريبًا منه",correct:!0,feedback:"صحيح: يبقى المريض في سريره مع حماية رأسه، وتحمي نفسك بعيدًا عن النوافذ والمعدات الثقيلة."},{text:"أدفع السرير بسرعة إلى المصعد لإنزاله إلى الطابق الأرضي",correct:!1,feedback:"غير صحيح: لا يُستخدم المصعد في أثناء الهزّة ولا بعدها، ولا يُنقل المرضى والمبنى يهتزّ."},{text:"أقف عند باب الغرفة وأمسك إطاره حتى تتوقف الهزّة",correct:!1,feedback:"غير صحيح: المدخل ليس مكانًا آمنًا؛ احمِ نفسك تحت طاولة متينة."},{text:"أركض إلى الخارج لأرى هل تضرّر المبنى",correct:!1,feedback:"غير صحيح: الركض في أثناء الهزّة يسبّب الإصابات، ويبقى مريضك وحده."}]}},{id:16,code:"COLD-16",icon:"Snowflake",accent:"#0ea5e9",category:"السلامة",title:"مخاطر الشتاء",subtitle:"انخفاض حرارة الجسم (Hypothermia)، وقضمة الصقيع (Frostbite)، والمولّد الاحتياطي، والوقاية من الانزلاق",summary:"يحمل شتاء كوردستان مخاطر خاصة للمستشفيات: الثلج والجليد، والانزلاق، وانقطاع الكهرباء، وانخفاض حرارة الجسم (Hypothermia) ولا سيما لدى كبار السن، وقضمة الصقيع (Frostbite). ويُصنَّف Hypothermia عمومًا في ثلاث درجات: خفيف (32–35°C)، ومتوسط (28–32°C)، وشديد (أقل من 28°C). والمولّدات التي تُفحص وفق NFPA 110، والوقود الاحتياطي، والبطانيات الإضافية، هي من أسس الحماية.",facts:[{label:"Hypothermia الخفيف",value:"32–35°C"},{label:"Hypothermia المتوسط",value:"28–32°C"},{label:"Hypothermia الشديد",value:"أقل من 28°C"},{label:"عودة الكهرباء عبر المولّد",value:"خلال 10 ثوانٍ (NFPA 110، Type 10)"}],steps:[{title:"Hypothermia — التعرّف عليه",detail:"خفيف (32–35°C): ارتعاش، واضطراب الوعي، وتلعثم في الكلام. متوسط (28–32°C): يتوقف الارتعاش، ويتباطأ النبض والتنفّس، وتتّسع حدقتا العينين. شديد (أقل من 28°C): فقدان الوعي، واضطراب نظم القلب (J-wave/Osborn)، والرجفان البطيني (VF) أو انعدام الانقباض القلبي (Asystole). وتُقاس الحرارة المركزية عن طريق المستقيم (Rectal) أو المريء (Esophageal)، لا على الجلد.",critical:!0},{title:"التدفئة (Rewarming) — ثلاث طرق",detail:"التدفئة السلبية (Passive) للحالات الخفيفة: البطانيات، والغرفة الدافئة، ونزع الملابس المبلّلة. التدفئة الخارجية النشطة (Active External) للحالات المتوسطة: الهواء الدافئ المدفوع (Bair Hugger) والسوائل الوريدية الدافئة (38–42°C). التدفئة الداخلية النشطة (Active Core) للحالات الشديدة: الأكسجين الدافئ المرطَّب، والسوائل الوريدية الدافئة، والأكسجة الغشائية خارج الجسم (ECMO) أو المجازة القلبية الرئوية (CPB) للمرضى غير المستقرّين أو المتوقّفة قلوبهم. حرّك المريض ببطء وفي وضع أفقي؛ فالتحريك العنيف قد يُحدث الرجفان البطيني (VF).",critical:!0},{title:"قضمة الصقيع (Frostbite) — أربع درجات",detail:"الدرجة 1: جلد أبيض أو أصفر مع خدر. الدرجة 2: فقاعات بسائل صافٍ. الدرجة 3: فقاعات دموية وضرر أعمق. الدرجة 4: يصل الضرر إلى العضلات والعظام (موت الأنسجة). التدفئة: ماء بحرارة 37–39°C، لمدة 15–30 دقيقة تقريبًا، حتى يلين الجلد. لا تستخدم: الماء الساخن جدًا، أو الحرارة المباشرة (النار أو المدفأة)، أو التدليك (massage). ولا تُدفّئ إذا كان هناك خطر لعودة التجمّد.",critical:!0},{title:"المولّد الاحتياطي — NFPA 110",detail:"النوع 10 (Type 10): تعود الكهرباء خلال 10 ثوانٍ. الفئة (Class): الحدّ الأدنى لساعات التشغيل دون إعادة التزوّد بالوقود؛ وتستخدم المستشفيات الفئة X (Class X) وفق NFPA 99، وغالبًا 96 ساعة في المناطق الزلزالية. المستوى 1 (Level 1): لفرعَي سلامة الأرواح (Life Safety) والأحمال الحرجة (Critical)، أي ICU وOR والمختبر. الفحص: فحص بصري أسبوعي، وتشغيل شهري تحت الحمل لمدة 30 دقيقة على الأقل، وتشغيل لمدة 4 ساعات تحت الحمل مرة كل 36 شهرًا على الأقل.",critical:!0},{title:"الوقاية من الانزلاق والسقوط",detail:"أزِل الثلج والجليد بانتظام عن الأبواب والممرات. انثر الملح أو كلوريد الكالسيوم (Calcium Chloride) على الممرات. أحذية مانعة للانزلاق للعاملين. إطارات شتوية لسيارات الإسعاف. لافتات «Wet Floor» في الأماكن المبلّلة.",critical:!0},{title:"حالات خاصة في الشتاء",detail:"التسمّم بأول أكسيد الكربون (CO) (من المولّدات أو المدافئ): صداع، واضطراب الوعي، وغثيان. ولا يُعتمد على SpO₂؛ بل يلزم Co-oximetry. العلاج: O₂ بتركيز 100%، والعلاج بالأكسجين عالي الضغط (Hyperbaric) في الحالات الشديدة وفق قرار المختص. والشتاء موسم ازدياد الإنفلونزا والفيروس المخلوي التنفسي (RSV) لدى الأطفال؛ فجهّز خطة لاستيعاب تزايد المرضى في قسم الطوارئ."}],reference:[{heading:"درجات Hypothermia وعلاجها",points:["خفيف (32–35): تدفئة سلبية (Passive)، ومشروبات دافئة إذا كان المريض واعيًا ويستطيع البلع بأمان.","متوسط (28–32): التدفئة بالهواء الدافئ (Bair Hugger) وسوائل وريدية دافئة.","شديد (أقل من 28): التدفئة الداخلية النشطة (Active core) وECMO/CPB.","حرّك المريض ببطء وفي وضع أفقي.","«Not dead until warm and dead»: لا تُعلَن الوفاة بسبب البرد وحده.","واصل CPR في أثناء التدفئة (عمومًا حتى نحو 32°C) قبل اتخاذ قرار الإيقاف."]},{heading:"التعرّف على التسمّم بأول أكسيد الكربون (CO)",points:["صداع، ودوار، واضطراب الوعي.","احمرار الشفتين بلون كرزي علامة متأخرة ونادرة.","قد يظهر تشبّع الأكسجين (SpO₂) طبيعيًا على نحو خاطئ.","يُقاس مستوى الكربوكسي هيموغلوبين (COHb) بمقياس الأكسجة المشترك (Co-oximetry).","العلاج: O₂ بتركيز 100% حتى تزول الأعراض (عمومًا بضع ساعات).","العلاج بالأكسجين عالي الضغط (Hyperbaric) في الحالات الشديدة، أو لدى الحوامل، أو عند وجود أعراض عصبية، وفق قرار المختص."]},{heading:"فحص المولّد (NFPA 110)",points:["أسبوعيًا: فحص بصري للمولّد والوقود.","شهريًا: تشغيل تحت الحمل لمدة 30 دقيقة على الأقل.","مرة كل 36 شهرًا على الأقل: تشغيل لمدة 4 ساعات تحت الحمل.","الوقود: بحسب فئة (Class) المولّد (مثلًا 96 ساعة).","عودة الكهرباء: خلال 10 ثوانٍ (Type 10).","البطاريات: بطاريات بدء التشغيل وأجهزة الطاقة غير المنقطعة (UPS)."]}],warnings:["«Not dead until warm and dead» (لا تُعلَن الوفاة إلا بعد التدفئة): قد يكون لدى مريض Hypothermia الشديد انعدام الانقباض القلبي (Asystole) ومع ذلك يمكن إنقاذه؛ فواصل CPR والتدفئة قبل اتخاذ قرار الإيقاف. لا تُدفّئ قضمة الصقيع (Frostbite) بالماء الساخن جدًا؛ بل بحرارة 37–39°C فقط. افحص المولّد بانتظام وتحت الحمل؛ فالمولّد غير المفحوص قد لا يعمل عند الحاجة."],realCase:"حالة عملية (مثال تعليمي): أدّت عاصفة ثلجية شديدة إلى انقطاع الكهرباء عن المدينة 48 ساعة. فاشتغل مولّد المستشفى خلال 10 ثوانٍ (Type 10)، لكنّ وقود المستشفى لم يكفِ إلا 12 ساعة، ووصل الصهريج الجديد بصعوبة. وفي هذه الأثناء وصل عدد من المرضى المسنّين مصابين بـ Hypothermia خفيف، وعولجوا بالبطانيات وأجهزة التدفئة بالهواء الدافئ (Bair Hugger) والسوائل الدافئة. وأُصيب موظفان عند الباب بقضمة صقيع (Frostbite) خفيفة. الدروس المستفادة: وقود احتياطي يتناسب مع فئة (Class) المولّد وخطة لإعادة التزوّد بالوقود، وأجهزة التدفئة بالهواء الدافئ في جميع الأقسام، وأحذية وملابس شتوية للعاملين.",caseStudy:[{prompt:"أنتِ ممرضة في قسم الطوارئ. انقطعت الكهرباء عن المدينة بسبب الثلج والمولّد يعمل. يصل مريض عمره 72 عامًا بقي 45 دقيقة في الشارع. يرتعش بشدة، ولديه اضطراب في الوعي، ودرجة مقياس غلاسكو للغيبوبة (GCS) 13. ما الخطوة الأولى؟",options:[{text:"التدفئة الداخلية النشطة (Active Core Rewarming) فورًا",correct:!1,feedback:"هذا مفرط؛ فالتدفئة السلبية (Passive) والتدفئة الخارجية النشطة (Active External) تكفيان لـ Hypothermia الخفيف."},{text:"أقيس الحرارة المركزية (Rectal/Esophageal)، وأنزع الملابس المبلّلة، وأبدأ التدفئة السلبية (Passive)",correct:!0,feedback:"صحيح: الارتعاش واضطراب الوعي يشيران إلى Hypothermia خفيف؛ ويمكن إضافة التدفئة بالهواء الدافئ (Bair Hugger) والسوائل الدافئة."},{text:"أكتفي بإعطائه بطانية",correct:!1,feedback:"يلزم قياس الحرارة المركزية لتحديد الدرجة."},{text:"أعطيه ماءً ساخنًا جدًا ليشربه",correct:!1,feedback:"خطير: وعيه مضطرب (خطر الاستنشاق إلى الرئتين)، والماء الساخن جدًا يسبّب الحروق."}]},{prompt:"الحرارة المركزية 27.5°C، ودرجة مقياس غلاسكو للغيبوبة (GCS) 6، والنبض ضعيف. ما الخطوة التالية؟",options:[{text:"تدفئة سلبية (Passive) وبطانيات",correct:!1,feedback:"هذا لا يكفي لـ Hypothermia الشديد؛ تلزم التدفئة الداخلية النشطة (Active Core)."},{text:"التدفئة الداخلية النشطة (Active Core): أكسجين دافئ مرطَّب، وسوائل وريدية دافئة، والتحضير لـ ECMO/CPB",correct:!0,feedback:"صحيح: Hypothermia شديد؛ حرّكي المريض ببطء."},{text:"أبدأ CPR فورًا رغم وجود النبض",correct:!1,feedback:"لا يُجرى CPR لمريض لديه نبض؛ تلزم التدفئة الداخلية النشطة (Active Core)."},{text:"أعلن وفاته",correct:!1,feedback:"«Not dead until warm and dead» (لا تُعلَن الوفاة إلا بعد التدفئة): غير صحيح."}]},{prompt:"بُدئ بالتدفئة الداخلية النشطة (Active Core). وبعد 3 ساعات بلغت الحرارة المركزية 29°C. ويُظهر تخطيط القلب (ECG) نظم الرجفان البطيني (VF) والمريض بلا نبض. ما الخطوة الصحيحة؟",options:[{text:"لا أعطي أي صدمة حتى 32°C",correct:!1,feedback:"غير صحيح: لا يجوز تأجيل الصدمة حتى 32°C؛ وتوصي AHA بالصدمة مع التدفئة."},{text:"أواصل CPR وأعطي الصدمة (وفق خوارزمية ACLS؛ ووفق ERC حتى 3 صدمات تحت 30°C)، مع التدفئة النشطة وECMO إن توفّر",correct:!0,feedback:"صحيح: قد لا يستجيب القلب البارد للصدمة حتى تتجاوز الحرارة 30°C، ولذلك فإنّ التدفئة هي أهم علاج."},{text:"أعطي الأدوية فقط ولا أعطي الصدمة أبدًا",correct:!1,feedback:"غير صحيح: الرجفان البطيني (VF) يحتاج إلى صدمة."},{text:"أعلن وفاته",correct:!1,feedback:"غير صحيح: ما زال من الممكن إنقاذه."}]}],quiz:[{question:"عند أيّ درجة حرارة يكون Hypothermia شديدًا؟",options:[{text:"أقل من 35°C",correct:!1,feedback:"هذا حدّ Hypothermia الخفيف."},{text:"أقل من 28°C",correct:!0,feedback:"Hypothermia الشديد يعني حرارة داخلية أقل من 28°C؛ والمتوسط 28–32°C، والخفيف 32–35°C."},{text:"أقل من 32°C",correct:!1,feedback:"هذا حدّ Hypothermia المتوسط."},{text:"أقل من 20°C",correct:!1,feedback:"هذا منخفض جدًا: إذ يبدأ Hypothermia الشديد عند أقل من 28°C."}],explanation:"يُصنَّف Hypothermia عمومًا حسب حرارة الجسم الداخلية: خفيف 32–35°C، ومتوسط 28–32°C، وشديد أقل من 28°C."},{question:"ما درجة حرارة الماء لتدفئة قضمة الصقيع (Frostbite)؟",options:[{text:"25°C",correct:!1,feedback:"بارد جدًا."},{text:"37–39°C",correct:!0,feedback:"صحيح: لمدة 15–30 دقيقة تقريبًا، حتى يلين الجلد (Wilderness Medical Society)."},{text:"50°C",correct:!1,feedback:"ساخن جدًا؛ يحرق الجلد."},{text:"ماء مغليّ",correct:!1,feedback:"خطير: حروق."}]},{question:"وفق NFPA 110، خلال كم من الوقت تعود الكهرباء من المولّد؟",options:[{text:"أقل من دقيقة واحدة، بعد التشغيل التلقائي",correct:!1,feedback:"بطيء جدًا."},{text:"أقل من 10 ثوانٍ (Type 10)",correct:!0,feedback:"النوع 10 (Type 10) وفق NFPA 110 يعني أن المولّد يعيد الكهرباء خلال 10 ثوانٍ."},{text:"أقل من ساعة واحدة",correct:!1,feedback:"بطيء جدًا."},{text:"أقل من نصف ساعة، بعد التشغيل اليدوي",correct:!1,feedback:"بطيء جدًا."}],explanation:"وفق NFPA 110 يعيد المولّد من النوع 10 (Type 10) الكهرباء خلال 10 ثوانٍ، ويُفحص بانتظام تحت الحمل ليعمل عند الحاجة."},{question:"ماذا تعني عبارة «Not dead until warm and dead»؟",options:[{text:"لا معنى لها",correct:!1,feedback:"لها معنى مهم."},{text:"قبل إعلان الوفاة، يجب تدفئة مريض Hypothermia الشديد ومواصلة CPR (عمومًا حتى نحو 32°C)",correct:!0,feedback:"لا تُعلَن الوفاة بسبب البرد وحده: دفّئ المريض وواصل CPR، عمومًا حتى نحو 32°C."},{text:"مرضى Hypothermia الشديد مع انعدام الانقباض القلبي (Asystole) متوفّون، فيُوقَف CPR وتُعلَن الوفاة فورًا دون تدفئة",correct:!1,feedback:"العكس صحيح: قد يكون لدى مريض Hypothermia الشديد انعدام الانقباض القلبي (Asystole) ومع ذلك يمكن إنقاذه."},{text:"تخصّ Hypothermia الخفيف فقط: يُدفّأ المريض ببطء بالبطانيات الدافئة، ولا يُبدأ CPR قبل ذلك أبدًا",correct:!1,feedback:"إنها خاصة بـ Hypothermia الشديد."}],explanation:"قد يكون لدى مريض Hypothermia الشديد انعدام الانقباض القلبي (Asystole) ومع ذلك يمكن إنقاذه، لذا لا تُعلَن الوفاة بسبب البرد وحده: دفّئه وواصل CPR، عمومًا حتى نحو 32°C."},{question:"يطلب مريض أصيبت قدماه بقضمة الصقيع (Frostbite) وضع مدفأة قرب قدميه. ماذا تفعل؟",options:[{text:"أوضّح أن الحرارة المباشرة لا تُستخدم، ونُدفئ بماء بدرجة 37–39°C",correct:!0,feedback:"صحيح: لا تُدفأ قضمة الصقيع إلا بماء بدرجة 37–39°C؛ فالجلد المخدَّر لا يشعر بالحرق."},{text:"أضع المدفأة قريبة، لأن التدفئة الأسرع تحفظ نسيجًا أكثر",correct:!1,feedback:"غير صحيح: الحرارة المباشرة (النار أو المدفأة) تحرق الجلد المخدَّر."},{text:"أدلك القدمين بقوة لتعود إليهما الدورة الدموية",correct:!1,feedback:"غير صحيح: التدليك (massage) يزيد ضرر الأنسجة المتجمّدة."},{text:"أنقع القدمين في ماء بأشدّ حرارة يحتملها، لتسريع الأمر",correct:!1,feedback:"غير صحيح: الماء الساخن يحرق الجلد المخدَّر؛ 37–39°C فقط."}],explanation:"تُدفأ قضمة الصقيع بماء بدرجة 37–39°C حتى يلين الجلد. لا ماء ساخن، ولا حرارة مباشرة، ولا تدليك."},{question:"تُحضر عائلة قريبًا لها يعاني صداعًا ودوارًا واضطرابًا في الوعي؛ وكانوا قد شغّلوا مولّدًا داخل البيت. ويُظهر مقياس التأكسج النبضي (Pulse oximeter) قيمة SpO₂ طبيعية. ما استنتاجك؟",options:[{text:"قد تبدو SpO₂ طبيعية خطأً؛ فيبقى الاشتباه بأول أكسيد الكربون قائمًا ويلزم CO-oximetry",correct:!0,feedback:"صحيح: في التسمّم بأول أكسيد الكربون قد تظهر SpO₂ طبيعية خطأً؛ ويُقاس مستوى COHb بـ CO-oximetry."},{text:"SpO₂ الطبيعية تنفي التسمّم بأول أكسيد الكربون، فنبحث عن سبب آخر",correct:!1,feedback:"غير صحيح: لا يميّز مقياس التأكسج النبضي أول أكسيد الكربون من الأكسجين، فلا تنفي SpO₂ الطبيعية التسمّم."},{text:"الأرجح أنه فيروس شتوي، فنعيده إلى البيت مع نصيحة بالراحة",correct:!1,feedback:"غير صحيح: تشغيل مولّد داخل البيت وتشابه الأعراض في العائلة يقوّيان الاشتباه بأول أكسيد الكربون؛ وإعادته إلى البيت خطرة."},{text:"لا نشتبه بأول أكسيد الكربون إلا إذا صارت شفتاه حمراوين كالكرز، فننتظر",correct:!1,feedback:"غير صحيح: الشفتان الحمراوان كالكرز علامة متأخرة ونادرة؛ والانتظار يؤخّر العلاج."}],explanation:"في الشتاء تُعدّ المولّدات والمدافئ من أسباب التسمّم بأول أكسيد الكربون. وقد تكون SpO₂ طبيعية خطأً؛ فيلزم CO-oximetry ويُعطى العلاج وفق تعليمات الطبيب."}],tips:["أبلغ الفريق المسؤول عن الجليد أو الثلج عند المداخل والممرّات فور رؤيته.","ارتدِ أحذية مانعة للانزلاق في الشتاء، وضع لافتة «أرضية مبلّلة» (Wet Floor) حيث يدخل الثلج مع الناس.","أبقِ بطانيات إضافية جاهزة في قسمك لانقطاع الكهرباء وللمرضى الذين يشعرون بالبرد.","لا تستخدم أبدًا مولّدًا أو منقلة فحم أو مدفأة ذات لهب مكشوف داخل غرفة مغلقة، حتى لتدفئة مكان المرضى."],activity:{prompt:"يُنقل رجل مسنّ وُجد في الخارج في البرد إلى قسم الطوارئ. يرتجف، ومشوّش، وكلامه متلعثم؛ وملابسه مبلّلة. ماذا تفعل أولًا؟",options:[{text:"أتعامل معه بلطف، وأنزع الملابس المبلّلة، وأغطّيه بالبطانيات وأقيس الحرارة المركزية",correct:!0,feedback:"صحيح: هذه علامات انخفاض حرارة خفيف؛ فالتعامل اللطيف ونزع الملابس المبلّلة والبطانيات أولًا، والحرارة المركزية تحدّد الخطوة التالية."},{text:"أدلك ذراعيه وساقيه بقوة بمنشفة لتعود الدورة الدموية",correct:!1,feedback:"غير صحيح: التعامل العنيف قد يُحدث VF لدى مريض بارد؛ تعامل معه بلطف."},{text:"أُجلسه وأعطيه مشروبًا ساخنًا فورًا ليدفأ",correct:!1,feedback:"غير صحيح: هو مشوّش، فلا يُعطى شيئًا بالفم؛ والمشروب الدافئ فقط لمريض واعٍ يستطيع البلع بأمان."},{text:"أضع يديه وقدميه في ماء ساخن ليدفأ بسرعة",correct:!1,feedback:"غير صحيح: الماء الساخن والحرارة المباشرة يؤذيان الجلد البارد؛ وفي الانخفاض الخفيف: بطانيات وغرفة دافئة."}]}},{id:17,code:"MCI-17",icon:"Users",accent:"#b91c1c",category:"الطوارئ",title:"حوادث الإصابات الجماعية (MCI) والفرز الطبي",subtitle:"عندما يفوق عدد المصابين قدرة المستشفى: الخطة وألوان الفرز ودور كل موظف",summary:"حادث الإصابات الجماعية (MCI) هو حادث يفوق فيه عدد المصابين ما هو متاح من موظفين وأماكن ومستلزمات. وعندها ينتقل المستشفى من العمل الاعتيادي إلى خطة الطوارئ: يُفعَّل نظام قيادة الحوادث (ICS)، ويعمل الموظفون وفق أدوارهم، ويحدّد الفرز الطبي (Triage) من يُعالَج أولًا. والهدف أفضل نتيجة لأكبر عدد من الناس. أمّا الخطة والرموز والأدوار الفعلية فهي الخاصة بمستشفاك؛ فاتّبع تعليمات الدفاع المدني والجهات المختصة.",facts:[{label:"الأحمر",value:"علاج فوري"},{label:"الأصفر",value:"خطير لكنه يحتمل الانتظار قليلًا"},{label:"الأخضر",value:"إصابة طفيفة، يستطيع المشي"},{label:"الأسود",value:"وفق بروتوكول المستشفى"}],blocks:[{heading:"ألوان الفرز بوصفها مفهومًا",body:`يرتّب الفرز المصابين بحسب حاجتهم إلى العلاج العاجل، لا بحسب من وصل أولًا أو من يصرخ أعلى. وتستخدم معظم الأنظمة الألوان:
• الأحمر (فوري): الحياة في خطر لكن العلاج ممكن الآن.
• الأصفر (مؤجَّل): حالة خطيرة لكنها تحتمل الانتظار قليلًا.
• الأخضر (طفيف): مصابون يستطيعون المشي.
• الأسود: متوفى أو فرصته ضئيلة جدًا، وفق بروتوكول المستشفى.

ويُعاد الفرز: فحالة المريض تتغير، فيتغير اللون أيضًا. ويحدّد مستشفاك النظام الفعلي (مثل START للبالغين وJumpSTART للأطفال) ومن يحق له إجراء الفرز.`},{heading:"عندما يتعرّض المستشفى لضغط مفاجئ: ما الذي يتغير",points:["تُعلَن خطة الطوارئ برمز مستشفاك ويتولى قائد الحادث القيادة.","قد تُؤجَّل العمليات المجدولة والأعمال غير العاجلة، وقد يُخرَج المرضى المستقرون أو يُنقلون، بقرار من فريق القيادة.","لا يحضر الموظفون خارج مناوبتهم إلا عند استدعائهم، ويسجّلون حضورهم في مكان تجمّع الموظفين (Labor Pool) لا في القسم مباشرةً.","مدخل واحد للمصابين، ومكان مستقل لكل لون من ألوان الفرز، وسجل واضح لكل مريض."]}],steps:[{title:"استمع إلى الرمز وتوجّه إلى دورك",detail:"عند إعلان رمز MCI، أنهِ فقط ما يمكن إيقافه بأمان، ثم توجّه إلى الدور الذي تحدّده لك خطة المستشفى. وإن لم يكن لك دور، فسجّل حضورك في مكان تجمّع الموظفين. ولا تذهب إلى مدخل الطوارئ من تلقاء نفسك.",critical:!0},{title:"الفرز عند المدخل",detail:"يفرز الموظفون المدرَّبون كل مصاب عند المدخل ويعطونه لونًا؛ ويتوجه المصاب إلى مكان لونه. والفرز سريع: افحص المشي والتنفس والدورة الدموية والوعي وفق بروتوكولك، ولا تتوقف لعلاج طويل في أثناء الفرز.",critical:!0},{title:"الإجراءات المنقذة للحياة أولًا",detail:"في منطقة اللون الأحمر، أول الإجراءات هي المنقذة للحياة: فتح مجرى الهواء، وإيقاف النزف الشديد، وطلب مساعدة الفريق. ويجري العلاج وفق بروتوكولات مستشفاك.",critical:!0},{title:"إعادة الفرز والتوثيق",detail:"أعِد فحص المرضى، ولا سيما في المنطقتين الصفراء والخضراء؛ فالمريض الذي تسوء حالته ينتقل إلى لون أكثر إلحاحًا. ويحصل كل مريض على تعريف وسجل (بطاقة أو استمارة) يبقى معه."},{title:"التواصل عبر سلسلة القيادة",detail:"أبلغ قائد فريقك بالأعداد والاحتياجات، لا بالهاتف إلى الجميع. ولا تُعطى المعلومات للعائلات ووسائل الإعلام إلا عبر الأشخاص الذين يكلّفهم فريق القيادة. وبعد انتهاء الحادث، شارك في جلسة المراجعة."}],warnings:["لا تعالج المصابين بحسب ترتيب وصولهم أو علوّ أصواتهم: فقد يكون المصاب الصامت هو الأخطر حالةً.","لا تذهب إلى موقع الحادث ولا تترك موقعك من تلقاء نفسك: فالمستشفى يحتاج إليك حيث تضعك الخطة.","لا تُعطِ بنفسك معلومات عن المصابين للعائلات أو وسائل الإعلام أو مواقع التواصل: فهذا عمل الأشخاص المكلَّفين فقط."],tips:["تعلّم دورك في خطة MCI قبل وقوع الحادث: إلى أين تذهب ولمن تقدّم تقريرك.","اعرف مكان حفظ بطاقات الفرز والاستمارات والمستلزمات الإضافية في قسمك.","حدّث رقم هاتفك لدى قسمك لكي تصلك رسالة الاستدعاء.","شارك في التمارين؛ فخطة MCI لا تنجح إلا إذا تدرّب عليها الموظفون."],activity:{prompt:"أنت ممرض في قسم الجراحة. أُعلن رمز MCI وأنت تعطي المرضى أدويتهم الاعتيادية. في قسمك أسرّة شاغرة ومريضان جاهزان للخروج. ماذا تفعل؟",options:[{text:"أُنهي ما يمكن إيقافه بأمان، وأبلغ المشرف بالأسرّة الشاغرة والمريضين الجاهزين، وأعمل وفق دوري",correct:!0,feedback:"صحيح: يحتاج فريق القيادة إلى معرفة الأسرّة المتاحة، وأنت تعمل في دورك المحدد."},{text:"أركض إلى قسم الطوارئ لأساعد في الفرز",correct:!1,feedback:"الذهاب من تلقاء نفسك يسبب الفوضى؛ فالفرز عمل موظفين مدرَّبين ومكلَّفين، وقسمك يحتاج إليك أيضًا."},{text:"أُخرج المريضين بنفسي فورًا لإخلاء الأسرّة",correct:!1,feedback:"الإخراج في هذه الحالة بقرار فريق القيادة والطبيب المعالج، لا بقرار شخص واحد."},{text:"أواصل عملي المعتاد وأنتظر حتى يستدعيني أحد",correct:!1,feedback:"الرمز يعني أن الخطة مفعّلة الآن؛ أبلغ المشرف بالأسرّة الشاغرة وبوضعك."}]},caseStudy:[{prompt:"كُلِّفت بالفرز عند مدخل الطوارئ بعد انهيار مبنى. يصل المصابون: رجل يصرخ وذراعه مكسورة، وامرأة صامتة شاحبة تتنفس بسرعة، وشاب يمشي وعليه جروح طفيفة. من يأخذ اللون الأحمر؟",options:[{text:"المرأة الصامتة الشاحبة التي تتنفس بسرعة",correct:!0,feedback:"صحيح: علامات الصدمة ومشكلات التنفس تهدد الحياة؛ والصمت لا يعني أن الإصابة طفيفة."},{text:"الرجل الذي يصرخ، لأن ألمه شديد",correct:!1,feedback:"الألم والصوت ليسا المقياس؛ والذراع المكسورة وحدها تكون عادةً صفراء."},{text:"الشاب الذي يمشي، لأنه وصل أولًا",correct:!1,feedback:"من يستطيع المشي يكون عادةً أخضر؛ وترتيب الوصول لا يحدّد شيئًا."},{text:"الثلاثة يأخذون الأحمر احتياطًا",correct:!1,feedback:"إذا كان الجميع أحمر يفشل الفرز وينتظر الأخطر حالةً وقتًا أطول."}]},{prompt:"لاحقًا يصبح الشاب ذو الجروح الطفيفة، الذي كان أخضر، مشوَّشًا وشاحبًا جدًا في المنطقة الخضراء. ماذا تفعل؟",options:[{text:"أبلغ قائد الفريق ويُعاد فرزه إلى لون أكثر إلحاحًا",correct:!0,feedback:"صحيح: الفرز يتكرر؛ والحالة الأسوأ تعني لونًا أكثر إلحاحًا."},{text:"يبقى أخضر لأن بطاقته كُتبت من قبل",correct:!1,feedback:"البطاقة ليست نهائية؛ فحالة المريض هي التي تقرر."},{text:"أطلب منه الانتظار حتى ينتهي المرضى الحمر",correct:!1,feedback:"قد تكون حالته خطيرة الآن؛ وإعادة الفرز لا تحتمل الانتظار."},{text:"أرسله إلى البيت لأن جروحه صغيرة",correct:!1,feedback:"التشوش والشحوب علامتا خطر؛ ولا تُخرج مريضًا لم يُفحص أبدًا."}]}],realCase:"سيناريو سلامة توضيحي: بعد حادث حافلة، وصل عدد كبير من المصابين إلى مستشفى في وقت قصير. أُعلنت خطة الطوارئ وتولّى قائد الحادث القيادة. أجرت ممرضتان مدرَّبتان الفرز عند مدخل واحد، وتوجّه كل مريض إلى مكان لونه. أُعطيت امرأة مسنّة صامتة بلا جرح ظاهر اللون الأحمر بعد فحص تنفسها ونبضها؛ وكان لديها نزف داخلي فنُقلت سريعًا إلى الجراحة. وسجّل الموظفون الذين حضروا من خارج مناوبتهم حضورهم في مكان تجمّع الموظفين ووُزِّعوا حيث الحاجة. وفي المراجعة لاحظ الفريق أن التمارين والأدوار الواضحة منعت الازدحام عند المدخل.",quiz:[{question:"يصل عدد كبير من المصابين معًا. من يحدّد ترتيب العلاج؟",options:[{text:"فرز يجريه موظفون مدرَّبون بحسب إلحاح كل حالة",correct:!0},{text:"ترتيب وصول المصابين إلى مدخل الطوارئ",correct:!1},{text:"عائلات المصابين، لأنهم يعرفونهم أكثر",correct:!1},{text:"المصاب الذي يطلب المساعدة بأعلى صوت",correct:!1}],explanation:"يرتّب الفرز المصابين بحسب الإلحاح، كي يُعالَج أولًا من حياته في خطر ويمكن إنقاذه."},{question:"يدخل مصاب ماشيًا وفي يده جرح صغير ويتكلم بشكل طبيعي. أي لون يناسبه عادةً؟",options:[{text:"الأخضر (طفيف)",correct:!0},{text:"الأحمر (فوري)",correct:!1},{text:"الأصفر (مؤجَّل)",correct:!1},{text:"الأسود (وفق البروتوكول)",correct:!1}],explanation:"من يمشي ويتكلم وجرحه صغير يكون عادةً أخضر؛ وأعِد فحصه لاحقًا لأن الحالة قد تتغير."},{question:"أنت خارج المناوبة وتسمع بوقوع حادث كبير. ما التصرف الصحيح؟",options:[{text:"لا أحضر إلا عند استدعائي وأسجّل في مكان تجمّع الموظفين",correct:!0},{text:"أذهب مباشرةً إلى موقع الحادث لمساعدة المصابين",correct:!1},{text:"أذهب إلى مدخل الطوارئ وأبدأ العلاج",correct:!1},{text:"أتصل بالقسم مرات كثيرة لأسأل عن الأخبار",correct:!1}],explanation:"الحضور الذاتي يسبب الازدحام والفوضى؛ فالخطة تستدعي الموظفين وتوزّع أدوارهم عبر مكان التجمّع."},{question:"مريض يحمل بطاقة صفراء تسوء حالته. ماذا يحدث؟",options:[{text:"يُعاد فرزه وينتقل إلى لون أكثر إلحاحًا",correct:!0},{text:"يبقى معه اللون الأصفر حتى نهاية الحادث",correct:!1},{text:"ينتظر حتى يُعالَج جميع المرضى الحمر",correct:!1},{text:"يُنقل إلى المنطقة الخضراء لتوفير المكان",correct:!1}],explanation:"يتكرر الفرز؛ واللون يتبع حالة المريض الحالية لا البطاقة السابقة."},{question:"يسألك صحفي عن عدد المصابين الذين توفّوا. ماذا تفعل؟",options:[{text:"أحيله إلى الشخص الذي كلّفه فريق القيادة",correct:!0},{text:"أعطيه العدد الذي سمعته من زملائي",correct:!1},{text:"أنشر بنفسي خبرًا قصيرًا على مواقع التواصل",correct:!1},{text:"أخبره بأسماء أخطر الحالات",correct:!1}],explanation:"لا تُعطى معلومات المصابين إلا من الأشخاص المكلَّفين؛ فالمعلومات الخاطئة أو الخاصة تضرّ المرضى وعائلاتهم."},{question:"أي عبارة عن MCI خاطئة؟",options:[{text:"يُعالَج كل شخص بحسب ترتيب وصوله",correct:!0},{text:"يهدف الفرز إلى أفضل نتيجة لأكبر عدد",correct:!1},{text:"يبقى سجل كل مريض معه",correct:!1},{text:"يعمل الموظفون في الأدوار التي تحدّدها الخطة",correct:!1}],explanation:"في MCI يتبع العلاج أولوية الفرز لا ترتيب الوصول."}]},{id:18,code:"SEC-18",icon:"ShieldAlert",accent:"#7c3aed",category:"السلامة",title:"العنف والأمن في المستشفى",subtitle:"تعرّف إلى علامات الخطر، وهدّئ الموقف، وأطلق الإنذار، واحمِ المرضى والموظفين",summary:"يتعرض العاملون الصحيون للإساءة اللفظية والتهديد والعنف الجسدي، وكثيرًا ما يكون مصدرها مرضى أو أقارب خائفون وتحت ضغط. ويمكن منع معظم هذه الحوادث أو الحدّ منها بملاحظة علامات الخطر مبكرًا والكلام بهدوء. وعند وجود خطر فليست مهمتك القتال: أطلق الإنذار، وحافظ على مسافة آمنة، واحمِ المرضى وزملاءك، ودع موظفي الأمن والشرطة (104) يتعاملون مع الشخص. ويُبلَّغ عن كل حادث حتى لو لم يُصَب أحد. ويُطبَّق رمز مستشفاك (وكثيرًا ما يُسمّى Code Gray أو Violet) وإجراءاته.",blocks:[{heading:"علامات الخطر",points:["رفع الصوت أو الشتم أو تكرار المطالب.","قبضتان مشدودتان، أو ذهاب وإياب متواصل، أو الوقوف قريبًا جدًا.","التحديق الغاضب أو التهديد أو ضرب الأشياء.","علامات السُّكر أو الضيق النفسي الشديد."]},{heading:"الكلام للتهدئة (De-escalation)",points:["ابقَ هادئًا وتكلّم ببطء وبصوت منخفض.","أصغِ وأعِد بكلماتك ما يحتاج إليه.","اشرح ما سيحدث ومتى، من دون وعود لا تستطيع الوفاء بها.","حافظ على مسافة آمنة، وأبقِ يديك ظاهرتين، ولا تسدّ طريق خروجه."]}],steps:[{title:"لاحظ مبكرًا",detail:"راقب علامات الخطر في منطقة الانتظار وعند سرير المريض. وأخبر زميلك أو قائد الفريق مبكرًا؛ ولا تنتظر حتى يصبح الشخص عنيفًا."},{title:"هدّئ الموقف",detail:"تكلّم بهدوء، وأصغِ، واشرح. قف على مسافة آمنة واجعل باب الخروج خلفك. يتكلم موظف واحد، ويبقى الآخرون قريبين ومستعدين.",critical:!0},{title:"أطلق الإنذار",detail:"إذا هدّد الشخص أو ساء الموقف، فاستخدم زر الإنذار أو رقم الطوارئ الداخلي وأعلن رمز مستشفاك. وإذا وُجد سلاح أو تهديد خطير، فاتصل بالشرطة على 104 وفق إجراءات مستشفاك.",critical:!0},{title:"احمِ المرضى والزملاء ونفسك",detail:"أبعِد المرضى والزوار عن الشخص، وأغلق الأبواب بينكم إن كان ذلك آمنًا، وغادر المكان إن كنت في خطر. ولا تحاول تقييد أحد أو نزع سلاحه: فهذا عمل موظفي الأمن المدرَّبين والشرطة.",critical:!0},{title:"الإبلاغ والدعم",detail:"أبلغ عن كل حادث، بما في ذلك الإساءة اللفظية، على استمارة مستشفاك: ماذا حدث ومتى ومن كان حاضرًا. واطلب العلاج إن أُصبت، واطلب الدعم بعد الحادث."}],warnings:["لا تحاول أبدًا قتال شخص عنيف أو تقييده أو نزع سلاحه: فقد تُصاب أنت وغيرك إصابات بالغة. أطلق الإنذار وابتعد.","لا تُدِر ظهرك لشخص غاضب ولا تدعه يقف بينك وبين المخرج.","لا تجادل الشخص ولا ترفع صوتك عليه ولا تهدّده: فذلك يزيد احتمال العنف."],tips:["اعرف أماكن أزرار الإنذار وكيف يُعلَن رمز مستشفاك.","أخبر زميلًا بمكانك عندما ترى مريضًا أو قريبًا سبق أن كان عدوانيًا.","أعطِ الأقارب المنتظرين معلومات واضحة ومنتظمة؛ فالانتظار الطويل بلا معلومات يثير غضبًا كثيرًا.","أبلغ عن الإساءة اللفظية أيضًا: فالبلاغات تساعد المستشفى على تخطيط الأمن والكوادر."],activity:{prompt:"أنت موظف استقبال في قسم الطوارئ. يصرخ أحد الأقارب بأن والده انتظر طويلًا، ويضرب المكتب ويقترب. ماذا تفعل أولًا؟",options:[{text:"أتكلم بهدوء وأُبقي المكتب بيننا وأصغي وأشير إلى زميل ليستدعي الأمن",correct:!0,feedback:"صحيح: الكلام الهادئ والمسافة الآمنة وطلب المساعدة مبكرًا تقلل الخطر معًا."},{text:"أصرخ عليه بأن عليه انتظار دوره مثل الجميع",correct:!1,feedback:"الصراخ يرفع التوتر ويزيد احتمال العنف."},{text:"أترك المكتب وأدير له ظهري",correct:!1,feedback:"إدارة الظهر لشخص غاضب قد تكون خطيرة؛ حافظ على المسافة وابقَ منتبهًا."},{text:"أقول له أن يهدأ وإلا ستعتقله الشرطة",correct:!1,feedback:"التهديد يرفع التوتر؛ اطلب المساعدة من دون تهديده."}]},caseStudy:[{prompt:"أنت ممرض في جناح. يغضب شقيق أحد المرضى ويبدأ رمي الأشياء قرب محطة التمريض، وبالقرب مريضان آخران. ماذا تفعل؟",options:[{text:"أطلق الإنذار برمز المستشفى وأُبعد المريضين القريبين وأحافظ على مسافتي",correct:!0,feedback:"صحيح: الإنذار وحماية المرضى وسلامتك."},{text:"أمسك ذراعيه لأوقفه",correct:!1,feedback:"التقييد عمل موظفي الأمن المدرَّبين؛ وقد تُصاب."},{text:"أواصل عملي وأتجاهله",correct:!1,feedback:"قد يتصاعد العنف بسرعة؛ والتجاهل يعرّض المرضى للخطر."},{text:"أحبس نفسي في المكتب وأترك المرضى",correct:!1,feedback:"احمِ نفسك، لكن خذ المرضى معك أو أبعِدهم إن أمكن ذلك بأمان."}]},{prompt:"يصل موظفو الأمن ويُخرجون الرجل. لم يُصَب أحد. ماذا تفعل الآن؟",options:[{text:"أطمئن على المرضى والزملاء ثم أبلغ عن الحادث على استمارة المستشفى",correct:!0,feedback:"صحيح: يُبلَّغ عن كل حادث حتى دون إصابات."},{text:"لا شيء، لأن أحدًا لم يُصَب",correct:!1,feedback:"البلاغات تمنع الحادث التالي؛ والإصابة ليست شرطًا."},{text:"أنشر فيديو للحادث على الإنترنت لتحذير الآخرين",correct:!1,feedback:"هذا ينتهك خصوصية المرضى؛ أبلغ عبر المستشفى."},{text:"أخبر عائلته بأنه ممنوع من دخول المستشفى",correct:!1,feedback:"قرارات الزيارة تتخذها الإدارة وفق قواعد المستشفى لا موظف واحد."}]}],realCase:"سيناريو سلامة توضيحي: في وقت متأخر من الليل في قسم طوارئ، وصل شاب مع صديقه المصاب وغضب من الانتظار. لاحظت ممرضة أنه يذهب ويجيء ويصرخ. فكلّمته بهدوء وباسمه، وشرحت ما يفعله الأطباء وأعطته معلومات محدّثة. وعندما ضرب الجدار واقترب، تراجعت لتُبقي المخرج خلفها وضغطت زر الإنذار. وصل موظفو الأمن وهدّؤوه، ولم يُصَب أحد. أبلغت الممرضة عن الحادث، وأضاف القسم لاحقًا تحديثات منتظمة للأقارب المنتظرين.",quiz:[{question:"زائر يذهب ويجيء ويشتم ويقف قريبًا جدًا منك. ما أفضل إجراء أول؟",options:[{text:"ابتعد قليلًا وتكلّم بهدوء واطلب مساعدة زميل",correct:!0},{text:"اطلب منه بحزم أن يغادر وإلا ستستدعي الشرطة",correct:!1},{text:"أدِر ظهرك وتجاهله حتى يتوقف",correct:!1},{text:"أمسك ذراعه وأخرجه من الجناح",correct:!1}],explanation:"الكلام الهادئ والمسافة وطلب المساعدة مبكرًا تقلل الخطر؛ أمّا التهديد أو التجاهل أو اللمس فقد تزيد العنف."},{question:"عندما تكلّم شخصًا غاضبًا في غرفة، أين يجب أن تقف؟",options:[{text:"والمخرج خلفي وعلى مسافة آمنة",correct:!0},{text:"بينه وبين الباب لأمنعه من الخروج",correct:!1},{text:"قريبًا جدًا كي يسمعني جيدًا",correct:!1},{text:"في زاوية كي لا يأتي من خلفي",correct:!1}],explanation:"تحتاج إلى طريق خروج مفتوح؛ فلا تسدّ أبدًا طريق خروج الشخص ولا تحاصر نفسك في زاوية."},{question:"شخص يُظهر سكينًا في منطقة الانتظار. ماذا تفعل؟",options:[{text:"أطلق الإنذار وأُبعد الناس وأتصل بالشرطة على 104",correct:!0},{text:"أحاول أخذ السكين منه حين يكون منشغلًا",correct:!1},{text:"أطلب منه بهدوء أن يعطيني السكين",correct:!1},{text:"أتصل بـ115 لأن هذا من عمل الدفاع المدني",correct:!1}],explanation:"لا تحاول أبدًا نزع سلاح أحد؛ فالإنذار والمسافة والشرطة (104) وفق إجراءات المستشفى هي الاستجابة الآمنة."},{question:"شتمك أحد الأقارب وهدّدك لكنه لم يضرب أحدًا. هل تبلغ عن ذلك؟",options:[{text:"نعم، يُبلَّغ عن كل حادث بما فيه الإساءة اللفظية",correct:!0},{text:"لا، يُبلَّغ فقط عن الحوادث التي فيها إصابات",correct:!1},{text:"فقط إذا كرّر القريب ذلك مرة ثانية",correct:!1},{text:"لا، فهذا جزء من العمل ويجب تقبّله",correct:!1}],explanation:"بلاغات الإساءة اللفظية تساعد المستشفى على منع العنف؛ والإساءة ليست جزءًا من العمل."},{question:"أي تصرّف يزيد احتمال العنف؟",options:[{text:"مجادلة الشخص ورفع الصوت عليه",correct:!0},{text:"الإصغاء وإعادة ما يحتاج إليه",correct:!1},{text:"شرح ما سيحدث ومتى",correct:!1},{text:"إبقاء اليدين ظاهرتين ومرتخيتين",correct:!1}],explanation:"الجدال والصراخ يرفعان التوتر، أمّا الإصغاء والشرح والوضعية المنفتحة فتخفضه."},{question:"انتظر الأقارب طويلًا في قسم الطوارئ وبدؤوا يغضبون. ما الذي يساعد على منع العنف؟",options:[{text:"إعطاؤهم معلومات واضحة ومنتظمة عن المريض",correct:!0},{text:"إغلاق باب غرفة الانتظار ليبقوا خارجها",correct:!1},{text:"الطلب من الأمن الوقوف بجانبهم طوال الوقت",correct:!1},{text:"عدم إخبارهم بشيء حتى ينتهي الطبيب",correct:!1}],explanation:"الغموض يغذّي الغضب؛ والمعلومات الواضحة المنتظمة وسيلة وقاية بسيطة."}]},{id:19,code:"UTIL-19",icon:"PlugZap",accent:"#ca8a04",category:"الطوارئ",title:"انقطاع الكهرباء والماء والغازات الطبية",subtitle:"حافظ على سلامة مرضى أجهزة دعم الحياة عند انقطاع الكهرباء أو الماء أو الأكسجين",summary:"يعتمد المستشفى على الكهرباء والماء والغازات الطبية مثل الأكسجين. وعند انقطاع أحدها، يكون أول من يتعرض للخطر مرضى أجهزة التنفس الاصطناعي والأكسجين ومضخات التسريب وغيرها من أجهزة دعم الحياة. ولدى المستشفى أنظمة احتياطية مثل المولدة والأكسجين الاحتياطي، لكن على الموظفين عند السرير فحص المرضى فورًا والاستعداد لتهويتهم يدويًا. اتّبع خطة مستشفاك لانقطاع الخدمات وأبلغ قسم الهندسة، ولا تُصلح الأنظمة أو تبدّلها بنفسك.",blocks:[{heading:"الكهرباء الاحتياطية: ما يجب أن تعرفه",points:["عند انقطاع الكهرباء تتولى المولدة التغذية بعد انقطاع قصير؛ وبعض المقابس والأجهزة فقط موصولة بالكهرباء الاحتياطية.","اعرف أي المقابس في قسمك موصولة بكهرباء الطوارئ، كما يعلّمها مستشفاك.","تُوصل أجهزة دعم الحياة بمقابس كهرباء الطوارئ، وتُبقى الأجهزة العاملة بالبطارية مشحونة.","قد لا تعمل الإنارة والمصاعد والتكييف كلها على الكهرباء الاحتياطية."]},{heading:"انقطاع الغازات الطبية",points:["تُظهر لوحة الإنذار انخفاض الضغط أو ارتفاعه في خطوط الأكسجين أو الغازات الأخرى.","افحص أولًا مرضى الأكسجين وانقلهم إلى أسطوانات أكسجين محمولة وفق الخطة.","أبقِ كيس التنفس اليدوي (bag-mask) جاهزًا بجانب كل مريض على جهاز التنفس الاصطناعي.","لا تُغلق صمامات المناطق (zone valves) إلا بأمر المسؤول أو فريق الهندسة."]}],steps:[{title:"افحص مرضى دعم الحياة أولًا",detail:"عند انقطاع الكهرباء أو الغاز، اذهب أولًا إلى مرضى أجهزة التنفس الاصطناعي والأكسجين ومضخات التسريب وأجهزة المراقبة. وتحقق من أن كلًا منهم يتنفس وأن الجهاز يعمل أو على البطارية.",critical:!0},{title:"كن مستعدًا للتهوية اليدوية",detail:"إذا توقف جهاز التنفس الاصطناعي، فهوِّ المريض بكيس التنفس اليدوي (bag-mask) موصولًا بأسطوانة أكسجين محمولة إن توفرت، كما تدرّبت، واطلب المساعدة. ولا تترك مريض جهاز التنفس وحده أبدًا في أثناء الانقطاع.",critical:!0},{title:"انتقل إلى الأكسجين المحمول",detail:"إذا انخفض ضغط خط الأكسجين، فانقل المرضى إلى أسطوانات محمولة وفق الخطة، بدءًا بالأشد حاجة. وثبّت الأسطوانات وأبعِدها عن الحرارة واللهب.",critical:!0},{title:"أبلغ واتّبع الخطة",detail:"أبلغ فورًا قسم الهندسة وقائد فريقك بالانقطاع عبر الرقم الداخلي. واتّبع خطة المستشفى لانقطاع الخدمات؛ ويقرر فريق القيادة نقل المرضى أو إيقاف الإجراءات المجدولة."},{title:"انقطاع الماء",detail:"استخدم ماء الشرب المخزَّن ومعقّم اليدين الكحولي عندما لا تكون اليدان متسختين بشكل ظاهر، ووفّر الماء للرعاية الضرورية. وتعمل الأقسام المعتمدة على الماء، مثل الغسيل الكلوي والتعقيم (sterilization)، وفق خططها الخاصة."}],warnings:["لا تترك أبدًا مريض جهاز التنفس الاصطناعي دون شخص مستعد للتهوية اليدوية في أثناء انقطاع الكهرباء أو الغاز.","لا تفتح صمامات الغازات الطبية أو تغلقها، ولا تُعِد ضبط اللوحات، ولا توصل الأجهزة بالمولدة بنفسك: فهذا عمل الهندسة والموظفين المخوَّلين.","لا توصل أجهزة دعم الحياة بمقبس غير معلَّم لكهرباء الطوارئ: فقد تنقطع عنه الكهرباء."],tips:["في بداية كل مناوبة، تحقق من وجود كيس التنفس اليدوي وقناع بالمقاس المناسب بجانب كل مريض على جهاز التنفس.","أبقِ الأجهزة العاملة بالبطارية على الشحن، واعرف من أدلّتها كم تعمل على البطارية.","اعرف أماكن أسطوانات الأكسجين المحمولة والمصابيح اليدوية في قسمك.","شارك في تمارين انقطاع الخدمات."],activity:{prompt:"تعمل في المناوبة الليلية في ICU. تنطفئ الأضواء لحظة ثم تعود أخفت، ويُطلق أحد أجهزة التنفس الاصطناعي إنذارًا. ماذا تفعل أولًا؟",options:[{text:"أفحص مريض ذلك الجهاز، وإن لم يكن يعمل أهوّيه يدويًا بكيس التنفس",correct:!0,feedback:"صحيح: المريض أولًا، والتهوية اليدوية تُبقيه يتنفس."},{text:"أتصل بالهندسة وأنتظر وصولهم قبل لمس المريض",correct:!1,feedback:"أبلغ، لكن المريض لا يحتمل الانتظار؛ افحصه وهوِّه أولًا أو دع زميلًا يتصل."},{text:"أفصل الجهاز وأوصله بمقبس آخر",correct:!1,feedback:"نقل القابس دون فحص قد يزيد الأمر سوءًا؛ افحص المريض والجهاز واستخدم مقابس كهرباء الطوارئ."},{text:"أعيد تشغيل الجهاز مرات عدة حتى يعمل",correct:!1,feedback:"إعادة التشغيل تضيّع الوقت وقد لا يتنفس المريض؛ هوِّه يدويًا."}]},caseStudy:[{prompt:"أنت ممرض في قسم الباطنية. يرنّ إنذار ضغط الأكسجين ويتوقف أكسجين الجدار. ثلاثة مرضى يستخدمون أكسجين الجدار، وأحدهم يعاني ضيق نفس شديدًا. ماذا تفعل أولًا؟",options:[{text:"أنقل الأشد ضيقًا في التنفس إلى أسطوانة محمولة ثم الآخرين، وأبلغ عن الإنذار",correct:!0,feedback:"صحيح: الأشد حاجة أولًا، ثم الإبلاغ."},{text:"أغلق صمام أكسجين المنطقة لأجد التسرب",correct:!1,feedback:"لا تُغلق الصمامات إلا بأمر المسؤول أو الهندسة."},{text:"أنتظر حتى يتوقف الإنذار من تلقاء نفسه",correct:!1,feedback:"المرضى يحتاجون إلى الأكسجين الآن؛ تصرّف وأبلغ."},{text:"أعطي المرضى ماء وأطلب منهم التنفس ببطء",correct:!1,feedback:"هذا لا يغني عن الأكسجين؛ انقلهم إلى أسطوانات محمولة."}]},{prompt:"يقول فريق الهندسة إن الخط سيتوقف مدة من الوقت، والأسطوانات المحمولة توشك أن تنفد. ماذا تفعل؟",options:[{text:"أبلغ قائد الفريق بعدد المرضى والأسطوانات ليرتّب فريق القيادة الإمداد أو نقل المرضى",correct:!0,feedback:"صحيح: يحتاج فريق القيادة إلى معلومات دقيقة ليقرر."},{text:"أخفض أكسجين جميع المرضى ليدوم أطول",correct:!1,feedback:"الأكسجين دواء؛ ولا يُغيَّر إلا بأمر الطبيب المعالج."},{text:"آخذ أسطوانات من قسم آخر دون إخبار أحد",correct:!1,feedback:"قد يعرّض ذلك مرضى القسم الآخر للخطر؛ فالإمداد يمر عبر سلسلة القيادة."},{text:"أنقل المرضى بنفسي إلى طابق آخر",correct:!1,feedback:"نقل المرضى يقرره فريق القيادة وفق الخطة."}]}],realCase:"سيناريو سلامة توضيحي: في أثناء عاصفة انقطعت الكهرباء الرئيسية عن مستشفى. اشتغلت المولدة، لكن مقابس أحد الأقسام لم تكن موصولة بالكهرباء الاحتياطية، فأطلقت مضخة تسريب وجهاز تنفس اصطناعي إنذارًا. فحصت ممرضة مريض جهاز التنفس أولًا وبدأت التهوية اليدوية بكيس التنفس الموجود عند السرير، بينما اتصل زميل بالهندسة. ونُقل الجهاز إلى مقبس معلَّم لكهرباء الطوارئ فعاد يعمل. وفي المراجعة تحقق المستشفى من المقابس الموصولة بالكهرباء الاحتياطية، وأضاف فحص كيس التنفس إلى كل مناوبة.",quiz:[{question:"تنقطع الكهرباء في ICU. من تفحص أولًا؟",options:[{text:"مرضى أجهزة التنفس الاصطناعي وأجهزة دعم الحياة",correct:!0},{text:"المرضى النائمون الذين يحتاجون إلى الإنارة",correct:!1},{text:"حاسوب التمريض وسجلات المرضى",correct:!1},{text:"الزوار الذين قد يخافون في الظلام",correct:!1}],explanation:"مرضى دعم الحياة معرّضون للخطر خلال لحظات؛ فافحصهم أولًا."},{question:"يتوقف جهاز تنفس اصطناعي ولا يعود إلى العمل. ماذا تفعل؟",options:[{text:"أهوّي يدويًا بكيس التنفس وأطلب المساعدة",correct:!0},{text:"أنتظر حتى تُصلح الهندسة الجهاز",correct:!1},{text:"أضع قناع أكسجين على وجهه وأنصرف",correct:!1},{text:"أعيد تشغيل الجهاز مرارًا حتى يعمل",correct:!1}],explanation:"التهوية اليدوية تُبقي المريض يتنفس حتى تصل المساعدة؛ فالمريض لا يحتمل الانتظار."},{question:"يرنّ إنذار خط الأكسجين. من يحق له إغلاق صمام أكسجين المنطقة؟",options:[{text:"المسؤول أو الهندسة وفق الخطة",correct:!0},{text:"أي ممرض يسمع الإنذار في الجناح",correct:!1},{text:"أقارب المريض إن لم يكن الموظفون قريبين",correct:!1},{text:"أول شخص يجد صندوق الصمامات",correct:!1}],explanation:"إغلاق صمام المنطقة يقطع الأكسجين عن جميع مرضاها؛ فلا يكون إلا بأمر وبعد نقل المرضى إلى أسطوانات محمولة."},{question:"بأي مقبس يجب أن تُوصل أجهزة دعم الحياة؟",options:[{text:"مقبس معلَّم لكهرباء الطوارئ",correct:!0},{text:"أي مقبس هو الأقرب إلى السرير",correct:!1},{text:"وصلة تمديد بمقابس كثيرة",correct:!1},{text:"المقبس المستخدم لمصباح الغرفة",correct:!1}],explanation:"وحدها مقابس كهرباء الطوارئ تتلقى التغذية من المولدة بعد الانقطاع."},{question:"ينقطع الماء في الجناح. كيف تحافظ على نظافة اليدين حين لا تكونان متسختين بشكل ظاهر؟",options:[{text:"بمعقّم اليدين الكحولي",correct:!0},{text:"أوقف تنظيف اليدين حتى يعود الماء",correct:!1},{text:"أمسح يديّ بمنشفة نظيفة فقط",correct:!1},{text:"أستخدم ماء خزان المرحاض",correct:!1}],explanation:"توصي WHO بمعقّم اليدين الكحولي حين لا تكون اليدان متسختين بشكل ظاهر؛ ووفّر الماء المخزَّن للرعاية الضرورية."},{question:"أي تصرّف خاطئ في أثناء انقطاع الكهرباء؟",options:[{text:"إعادة ضبط لوحة المولدة بنفسي",correct:!0},{text:"فحص كل مريض على جهاز التنفس فورًا",correct:!1},{text:"إبلاغ الهندسة بالانقطاع",correct:!1},{text:"إبقاء كيس التنفس بجانب السرير",correct:!1}],explanation:"لا يعمل على لوحات المولدة والكهرباء إلا الهندسة والموظفون المخوَّلون."}]},{id:20,code:"SHARP-20",icon:"Scissors",accent:"#be123c",category:"السلامة",title:"الأدوات الحادة وإصابات وخز الإبر",subtitle:"امنع الإصابات بالإبر والأدوات الحادة، واعرف ما تفعله فورًا إذا وقعت",summary:"يمكن أن تنقل الإصابات بالإبر والمشارط وغيرها من الأدوات الحادة عدوى منقولة بالدم، مثل التهاب الكبد B والتهاب الكبد C وHIV، من المريض إلى العامل الصحي. ويمكن منع معظمها بعادات عمل آمنة: استخدام أدوات مزوّدة بخاصية أمان، وعدم إعادة غطاء الإبرة أبدًا، ورمي الأدوات الحادة فورًا في حاوية Sharps. وإذا وقعت إصابة أو تناثر دم، فإن الإسعاف الأولي يستغرق لحظات، لكن الإبلاغ الفوري لا يقل أهمية: فأي دواء بعد التعرّض يقرّره الطبيب وفق بروتوكول مستشفاك، ويكون أنجع إذا بدأ مبكرًا.",blocks:[{heading:"عادات آمنة مع الأدوات الحادة",points:["لا تُعِد غطاء إبرة مستعملة أبدًا، ولا تثنِها ولا تكسرها.","استخدم أدوات مزوّدة بخاصية أمان وفعّلها فور الاستعمال.","ارمِ كل أداة حادة فورًا في حاوية Sharps في مكان الاستعمال؛ ومن استعملها هو من يرميها.","لا تملأ الحاوية فوق خط الامتلاء؛ أغلقها واستبدلها بأخرى جديدة.","لا تناول أداة حادة باليد أبدًا؛ استخدم صينية."]},{heading:"من المعرّض للخطر",points:["الممرضون والأطباء في أثناء الحقن وسحب الدم والجراحة.","موظفو المختبر في أثناء التعامل مع العينات.","عمال النظافة والمغاسل عندما تُترك الأدوات الحادة في السلال أو الأغطية أو الأكياس."]}],steps:[{title:"اغسل الجرح فورًا",detail:"إذا أصابتك إبرة أو أداة حادة، فاغسل المكان فورًا بالماء الجاري والصابون. ولا تفركه بقوة، ولا تستخدم المبيّض (bleach) أو مواد كيميائية قوية على الجلد.",critical:!0},{title:"اغسل الرذاذ",detail:"إذا تناثر دم أو سائل جسدي في العين أو الأنف أو الفم، فاشطفه فورًا بكمية وافرة من الماء النظيف أو المحلول الملحي. واغسل الرذاذ على الجلد بالماء والصابون.",critical:!0},{title:"أبلغ فورًا",detail:"أخبر مشرفك فورًا، واذهب إلى الجهة التي يحددها مستشفاك لتعرّض الموظفين (مثل صحة الموظفين أو قسم الطوارئ). ولا تنتظر حتى نهاية المناوبة.",critical:!0},{title:"التقييم الطبي",detail:"يقيّم الطبيب الخطر ويقرّر الفحوص وأي دواء بعد التعرّض (post-exposure prophylaxis) وفق بروتوكول مستشفاك. ولا تتناول أي دواء من تلقاء نفسك. ويمكن فحص المريض المصدر بموافقته ووفق أنظمة المستشفى."},{title:"التوثيق والمتابعة",detail:"املأ استمارة الإصابة: ماذا ومتى وكيف وبأي أداة. واحضر جميع زيارات المتابعة وفحوصها. فالبلاغات تساعد المستشفى على اكتشاف الأدوات والممارسات غير الآمنة."}],warnings:["لا تُعِد غطاء إبرة مستعملة ولا تثنِها ولا تكسرها باليد أبدًا: فهذا سبب شائع لإصابات الوخز.","لا تُخفِ الإصابة ولا تؤخّر الإبلاغ: فأي دواء بعد التعرّض يكون أنجع إذا بدأ مبكرًا.","لا تُدخل يدك أبدًا في حاوية Sharps أو كيس النفايات لتضغط محتواه."],tips:["خذ حاوية Sharps إلى جانب السرير قبل بدء الإجراء.","تأكد من تطعيمك ضد التهاب الكبد B كما يوفره برنامج صحة الموظفين في مستشفاك.","اطلب من المريض قبل الإجراء أن يبقى ساكنًا، واستعن بزميل مع المريض المضطرب.","اعرف إجراء التعرّض في مستشفاك والجهة التي تذهب إليها في أي ساعة."],activity:{prompt:"أنت عامل نظافة تفرغ كيس نفايات في جناح. تخز يدك إبرة تُركت في الكيس عبر القفاز. ماذا تفعل؟",options:[{text:"أغسل المكان بالماء الجاري والصابون وأبلغ مشرفي فورًا",correct:!0,feedback:"صحيح: الإسعاف الأولي ثم الإبلاغ الفوري للتقييم الطبي."},{text:"أعصر الجرح بقوة وأضع عليه المبيّض",correct:!1,feedback:"المبيّض والمواد القوية تؤذي الجلد؛ اغسل بالماء والصابون."},{text:"أُكمل مناوبتي وأبلغ غدًا إن آلمني",correct:!1,feedback:"التأخير مهم؛ فأي دواء بعد التعرّض أنجع إذا بدأ مبكرًا."},{text:"أضع لاصقًا ولا أقول شيئًا لأنه صغير",correct:!1,feedback:"حتى الوخزة الصغيرة قد تنقل العدوى؛ فكل إصابة يُبلَّغ عنها وتُقيَّم."}]},caseStudy:[{prompt:"أنت ممرض تسحب دمًا من مريض مضطرب. تنزلق الإبرة وتخز إصبعك. ماذا تفعل أولًا؟",options:[{text:"أؤمّن الإبرة وأغسل الجرح بالماء الجاري والصابون وأبلغ المشرف",correct:!0,feedback:"صحيح: التخلص الآمن والغسل والإبلاغ."},{text:"أُكمل سحب الدم أولًا ثم أفكر في الأمر",correct:!1,feedback:"توقّف واعتنِ بالإصابة؛ ويمكن لزميل آخر أن يُكمل."},{text:"أعيد غطاء الإبرة كي لا تخز أحدًا آخر",correct:!1,feedback:"إعادة الغطاء تسبب إصابات أكثر؛ ارمِها في حاوية Sharps."},{text:"أنظفه بمعقّم كحولي وأتابع عملي",correct:!1,feedback:"اغسل بالماء الجاري والصابون وأبلغ؛ فالمعقّم ليس الإسعاف الأولي هنا."}]},{prompt:"في عيادة الموظفين يقول الطبيب إن نتائج فحص المريض لم تظهر بعد، ويقترح دواء ما بعد التعرّض وفق البروتوكول. ما الصحيح؟",options:[{text:"أتّبع نصيحة الطبيب وفق البروتوكول وأحضر كل زيارات المتابعة",correct:!0,feedback:"صحيح: القرار للطبيب والمتابعة جزء من الرعاية."},{text:"أنتظر نتائج المريض قبل أي قرار",correct:!1,feedback:"الطبيب يحدد التوقيت؛ والانتظار قد يقلل فائدة الدواء."},{text:"آخذ دواء من مخزون الجناح دون وصفة",correct:!1,feedback:"لا تتناول دواءً من تلقاء نفسك أبدًا؛ اتبع الطبيب والبروتوكول."},{text:"أسأل المريض مباشرة في الجناح عن أمراضه",correct:!1,feedback:"فحص المريض المصدر ومعلوماته تمر عبر المستشفى بموافقة وسرية."}]}],realCase:"سيناريو سلامة توضيحي: كان عامل في مغسلة مستشفى يفرز أغطية أسرّة مستعملة حين وخزت يده إبرة تُركت في ملاءة. وكان يعرف الإجراء من التدريب: غسل المكان بالماء الجاري والصابون وأخبر مشرفه فورًا. وفُحص في عيادة الموظفين في المناوبة نفسها، حيث قيّم الطبيب الخطر وقرّر المتابعة وفق بروتوكول المستشفى. وقاد البلاغ القسم إلى مراجعة طريقة التخلص من الأدوات الحادة، وذُكِّر الموظفون برمي كل أداة حادة في الحاوية عند السرير.",quiz:[{question:"استُعملت إبرة للتو في حقنة. ماذا تفعل بها؟",options:[{text:"أرميها فورًا في حاوية Sharps عند السرير",correct:!0},{text:"أعيد غطاءها بحذر بكلتا يديّ ثم أرميها",correct:!1},{text:"أتركها على الصينية لأرميها بعد الجولة",correct:!1},{text:"أثنيها كي لا يستعملها أحد مرة أخرى",correct:!1}],explanation:"الرمي الفوري في مكان الاستعمال يمنع معظم الإصابات؛ وإعادة الغطاء والثني يسببانها."},{question:"تخز إبرة مستعملة إصبعك. ما الإسعاف الأولي؟",options:[{text:"الغسل بالماء الجاري والصابون",correct:!0},{text:"أصبّ المبيّض على الجرح لقتل الجراثيم",correct:!1},{text:"أمصّ الجرح وأبصق الدم",correct:!1},{text:"أضع لاصقًا وأتابع العمل",correct:!1}],explanation:"الماء والصابون هما الإسعاف الأولي؛ والمبيّض والمواد القوية تؤذي الجلد، ثم يلزم الإبلاغ الفوري."},{question:"يتناثر دم في عين زميلك. ماذا تفعل؟",options:[{text:"نشطف العين فورًا بماء نظيف وفير أو محلول ملحي",correct:!0},{text:"نفرك العين بمنديل جاف لإزالة الدم",correct:!1},{text:"نضع فيها قطرات مضاد حيوي من مخزون الجناح",correct:!1},{text:"ننتظر لنرى هل تحمرّ العين لاحقًا",correct:!1}],explanation:"الشطف الفوري الوافر بالماء النظيف أو المحلول الملحي يزيل الدم؛ ثم يُبلَّغ عن التعرّض."},{question:"من يقرر الدواء بعد إصابة وخز الإبرة؟",options:[{text:"الطبيب وفق بروتوكول المستشفى",correct:!0},{text:"الموظف المصاب من أدوية الجناح",correct:!1},{text:"المشرف بحسب حجم الجرح",correct:!1},{text:"لا أحد؛ فالوخزة لا تحتاج إلى دواء أبدًا",correct:!1}],explanation:"دواء ما بعد التعرّض يعتمد على تقييم طبي للخطر؛ فلا تأخذه إلا كما يقرر الطبيب والبروتوكول."},{question:"امتلأت حاوية Sharps حتى خط الامتلاء. ماذا تفعل؟",options:[{text:"أغلقها وأستخدم حاوية جديدة",correct:!0},{text:"أضغط محتواها بيد مرتدية قفازًا",correct:!1},{text:"أهزّها ليتسع المكان لإبر أكثر",correct:!1},{text:"أضع الإبر الزائدة في كيس بلاستيكي",correct:!1}],explanation:"الحاوية الممتلئة تُغلق وتُستبدل؛ فالضغط أو الهز أو الأكياس البلاستيكية تسبب الإصابات."},{question:"أي عبارة خاطئة؟",options:[{text:"الوخزة الصغيرة لا تحتاج إلى إبلاغ",correct:!0},{text:"يُبلَّغ فورًا عن كل إصابة بأداة حادة",correct:!1},{text:"تُفعَّل خصائص الأمان بعد الاستعمال",correct:!1},{text:"لا تُناوَل الأدوات الحادة باليد أبدًا",correct:!1}],explanation:"حتى الوخزة الصغيرة قد تنقل العدوى؛ فكل إصابة يُبلَّغ عنها وتُقيَّم."}]},{id:21,code:"DECON-21",icon:"Biohazard",accent:"#0f766e",category:"الطوارئ",title:"المرضى الملوَّثون في قسم الطوارئ",subtitle:"احمِ الموظفين والمستشفى أولًا، ثم أزِل التلوث وعالج",summary:"بعد حادث كيميائي، قد يصل المصابون إلى قسم الطوارئ والمادة ما تزال على جلدهم وملابسهم، وكثيرًا ما يأتون بأنفسهم وقبل أي إنذار. وإذا دخلوا، فقد يتعرض الموظفون والمرضى الآخرون للمادة وقد يُغلق القسم. والقاعدة: احمِ الموظفين والمستشفى أولًا. أوقف المرضى الملوَّثين عند المدخل، وخذهم إلى منطقة إزالة التلوث (decontamination) التي تحددها خطة مستشفاك، ولا يعتني بهم إلا موظفون مدرَّبون يرتدون معدات الوقاية الشخصية (PPE) المناسبة. ويتولى الدفاع المدني (115) موقع الحادث؛ فاتّبع تعليمات الدفاع المدني والجهات المختصة.",blocks:[{heading:"علامات احتمال تلوّث المريض",points:["عدة مرضى من مكان واحد بالأعراض نفسها.","رائحة أو مسحوق أو سائل على الجلد أو الملابس.","حرقة العينين أو السعال أو صعوبة التنفس لدى المرضى والموظفين القريبين منهم.","معلومات من 115 أو الإسعاف أو المريض عن انطلاق مادة كيميائية."]},{heading:"منطقة إزالة التلوث بوصفها مفهومًا",points:["تقع خارج المبنى الرئيسي قرب مدخل الطوارئ، كما تحددها خطة مستشفاك.","لها جانب ملوَّث يصل إليه المرضى، وجانب نظيف ينتقلون إليه بعد إزالة التلوث.","خلع الملابس والغسل بالماء يزيلان جزءًا كبيرًا من التلوث.","لا يعمل في الجانب الملوَّث إلا موظفون مدرَّبون بمعدات الوقاية التي تحددها الخطة."]}],steps:[{title:"تعرّف وأوقف عند المدخل",detail:"إذا اشتبهت في التلوث، فأوقف المريض بهدوء ومن مسافة خارج المدخل. ولا تدعه يدخل القسم، ولا تلمسه دون PPE.",critical:!0},{title:"أطلق الإنذار",detail:"أخبر المسؤول وأعلن رمز مستشفاك للمواد الخطرة. وأغلق الأبواب كي لا يصل التلوث إلى القسم؛ وإن كان مريض قد دخل فعلًا، فأبقِ ذلك المكان مغلقًا وانتظر التعليمات.",critical:!0},{title:"ارتدِ PPE قبل أي تماس",detail:"لا يرتدي معدات الوقاية التي تحددها الخطة ويعمل في منطقة إزالة التلوث إلا الموظفون المدرَّبون على ذلك. وإن لم تكن مدرَّبًا، فأرشد المرضى من مسافة ولا تدخل الجانب الملوَّث.",critical:!0},{title:"الرعاية المنقذة للحياة وإزالة التلوث",detail:"يقدّم الموظفون المدرَّبون بمعدات الوقاية الرعاية العاجلة المنقذة للحياة في منطقة إزالة التلوث، مثل فتح مجرى الهواء أو إيقاف النزف الشديد. ويخلع المرضى ملابسهم التي توضع في أكياس، ويُغسلون بالماء كما تقول الخطة.",critical:!0},{title:"الدخول النظيف والتوثيق",detail:"بعد إزالة التلوث يدخل المرضى عبر المسار النظيف للعلاج. وثّق كل مريض وأكياس متعلقاته، وأبلغ فريق العلاج و115 بالمادة المشتبه فيها."}],warnings:["لا تُدخل أبدًا مريضًا ملوَّثًا إلى قسم الطوارئ قبل إزالة التلوث: فقد يتأذى الموظفون والمرضى الآخرون ويُغلق القسم.","لا تلمس مريضًا ملوَّثًا أو تساعده أبدًا دون PPE مناسبة وتدريب: فالموظف الذي يصبح مصابًا لا يستطيع مساعدة أحد.","لا تستخدم الماء الساخن أو المبيّض (bleach) أو الفرك القوي على جلد المرضى."],tips:["اعرف مكان منطقة إزالة التلوث في مستشفاك ومن المدرَّب على العمل فيها.","تعلّم رمز مستشفاك للمواد الخطرة وكيف يُعلَن.","أبقِ ملابس احتياطية أو أردية المستشفى وأكياس المتعلقات جاهزة قرب منطقة إزالة التلوث."],activity:{prompt:"تعمل في استقبال قسم الطوارئ. يدخل ثلاثة عمال من المصنع نفسه يسعلون وملابسهم مبتلة وتفوح منهم رائحة كيميائية قوية. ماذا تفعل؟",options:[{text:"أطلب منهم بهدوء البقاء خارج المدخل وأحافظ على مسافتي وأبلغ المسؤول لتفعيل خطة المواد الخطرة",correct:!0,feedback:"صحيح: الإيقاف عند المدخل والمسافة والإنذار."},{text:"أدخلهم غرفة العلاج لأنهم يسعلون",correct:!1,feedback:"هذا يُدخل التلوث إلى القسم؛ يجب إزالة تلوثهم أولًا."},{text:"أساعدهم على خلع ملابسهم المبتلة في غرفة الانتظار",correct:!1,feedback:"دون PPE تصبح مصابًا، وتتلوث غرفة الانتظار."},{text:"أعطيهم ماء ليشربوا وأطلب منهم الانتظار في الممر",correct:!1,feedback:"يجب أن يبقوا في الخارج وتُزال ملوثاتهم؛ فالممر ينشر التلوث."}]},caseStudy:[{prompt:"أنت ممرض عند مدخل الطوارئ. يبلّغ فريق الإسعاف أنه ينقل مصابين من انسكاب كيميائي، وقد وصل بعض المرضى بسياراتهم. ماذا تفعل أولًا؟",options:[{text:"أتأكد من إعلان الرمز وأوقف المرضى خارجًا وأُبعد الموظفين غير المدرَّبين",correct:!0,feedback:"صحيح: خطة المستشفى تبدأ فورًا ويُحمى الموظفون."},{text:"أركض إلى الخارج لأساعد المرضى على النزول من السيارات دون PPE",correct:!1,feedback:"قد تتعرض للمادة؛ ولا يلامسهم إلا موظفون مدرَّبون بمعدات الوقاية."},{text:"أفتح كل الأبواب ليدخل المرضى بسرعة",correct:!1,feedback:"الأبواب المفتوحة تُدخل التلوث إلى القسم."},{text:"أنتظر وصول 115 قبل أي إجراء",correct:!1,feedback:"خطة المستشفى تبدأ فورًا؛ و115 يتولى موقع الحادث."}]},{prompt:"في منطقة إزالة التلوث، مريض لا يتنفس جيدًا وما يزال يرتدي ملابسه الملوَّثة. أنت مدرَّب وترتدي PPE. ماذا تفعل؟",options:[{text:"أقدّم رعاية عاجلة لمجرى الهواء بينما يخلع الفريق ملابسه ويزيل تلوثه",correct:!0,feedback:"صحيح: للموظفين المدرَّبين بمعدات الوقاية، تسير الرعاية المنقذة للحياة وإزالة التلوث معًا."},{text:"أنقله كما هو إلى غرفة الإنعاش في الداخل",correct:!1,feedback:"هذا يلوّث القسم؛ فالرعاية تبدأ في منطقة إزالة التلوث."},{text:"أنتظر انتهاء إزالة التلوث تمامًا قبل أي رعاية",correct:!1,feedback:"لا ينبغي تأخير الإجراءات المنقذة للحياة إذا استطاع موظفون مدرَّبون بمعدات الوقاية تقديمها."},{text:"أنزع قناعي لأسمع تنفسه بشكل أفضل",correct:!1,feedback:"نزع PPE يعرّضك للمادة؛ أبقِها عليك."}]}],realCase:"سيناريو سلامة توضيحي: وصل عمال ورشة إلى مستشفى بسيارتهم بعد تسرّب مادة كيميائية. وقبل أي إنذار، دخل اثنان منهم غرفة الانتظار وتفوح منهما رائحة قوية، فبدأ موظف الاستقبال يسعل. أغلق المسؤول غرفة الانتظار، وأعلن رمز المواد الخطرة، ووجّه القادمين الجدد إلى منطقة إزالة التلوث في الخارج. وخلع موظفون مدرَّبون بمعدات الوقاية ملابس المرضى ووضعوها في أكياس وغسلوهم، ثم دخل المرضى عبر المسار النظيف. وفي المراجعة درّب المستشفى موظفي الاستقبال على التعرّف إلى التلوث وإيقاف المرضى عند المدخل.",quiz:[{question:"يدخل مريض تفوح منه رائحة كيميائية وعلى ملابسه مسحوق رطب. ماذا تفعل أولًا؟",options:[{text:"أوقفه خارج المدخل وأطلق الإنذار",correct:!0},{text:"أدخله غرفة العلاج قبل أن تسوء حالته",correct:!1},{text:"أنفض المسحوق عن ملابسه بيديّ",correct:!1},{text:"أطلب منه الجلوس في غرفة الانتظار حتى يُنادى",correct:!1}],explanation:"الإيقاف عند المدخل والإنذار يمنعان دخول التلوث إلى القسم ويحميان الموظفين."},{question:"من يحق له العمل في الجانب الملوَّث من منطقة إزالة التلوث؟",options:[{text:"موظفون مدرَّبون بمعدات الوقاية التي تحددها الخطة",correct:!0},{text:"أي موظف بقفازين وكمامة جراحية",correct:!1},{text:"الأقارب الذين جاؤوا مع المرضى للمساعدة",correct:!1},{text:"موظفو الأمن الذين يحرسون باب الطوارئ",correct:!1}],explanation:"الجانب الملوَّث يتطلب تدريبًا ومعدات وقاية خاصة؛ ومن يفتقر إليهما قد يصبح مصابًا."},{question:"ما الذي يزيل جزءًا كبيرًا من التلوث عن المريض؟",options:[{text:"خلع الملابس والغسل بالماء",correct:!0},{text:"إعطاء المريض حليبًا أو ماء ليشربه",correct:!1},{text:"تغطية المريض ببطانية نظيفة",correct:!1},{text:"فرك الجلد بقوة بمحلول المبيّض",correct:!1}],explanation:"تحتجز الملابس كثيرًا من المادة؛ فخلعها والغسل بالماء هما الوسيلة الأساسية. والمبيّض والفرك القوي يؤذيان الجلد."},{question:"مريض ملوَّث في منطقة إزالة التلوث لديه نزف شديد. ماذا يحدث؟",options:[{text:"يوقف موظفون مدرَّبون بمعدات الوقاية النزف أثناء إزالة التلوث",correct:!0},{text:"يُنقل كما هو فورًا إلى غرفة العمليات في الداخل",correct:!1},{text:"يُؤجَّل إيقاف النزف حتى تنتهي إزالة التلوث",correct:!1},{text:"يضغط أي شخص قريب على الجرح بيدين مكشوفتين",correct:!1}],explanation:"تُقدَّم الإجراءات المنقذة للحياة من موظفين مدرَّبين بمعدات الوقاية في أثناء إزالة التلوث؛ لا داخل القسم ولا بأيدٍ مكشوفة."},{question:"يريد زميلك مساعدة مريض ملوَّث دون PPE «لتوفير الوقت». ما أفضل رد؟",options:[{text:"إن تعرّضتَ للمادة أصبحت مصابًا ولن تستطيع المساعدة",correct:!0},{text:"لا بأس إذا غسلت يديك جيدًا بعد ذلك",correct:!1},{text:"لا بأس إذا لم يبدُ المريض مريضًا جدًا",correct:!1},{text:"لا بأس إذا حبست أنفاسك أثناء المساعدة",correct:!1}],explanation:"الموظف المتعرّض يصبح مريضًا إضافيًا وينقص الفريق؛ فمعدات الوقاية والتدريب لازمة قبل أي تماس."},{question:"أي تصرّف خاطئ؟",options:[{text:"ترك المرضى الملوَّثين ينتظرون داخل القسم",correct:!0},{text:"وضع ملابس المرضى ومتعلقاتهم في أكياس",correct:!1},{text:"استخدام مسار نظيف منفصل بعد إزالة التلوث",correct:!1},{text:"إبلاغ الفريق بالمادة المشتبه فيها",correct:!1}],explanation:"يبقى المرضى الملوَّثون في الخارج حتى تُزال ملوثاتهم؛ فداخل القسم يلوّثون الموظفين والمرضى الآخرين."}]}],t={lessons:e};export{t as default,e as lessons};
